# go_version_needed reads the go directive out of the go.mod that is baked
# into the function above, so there is one statement of the minimum and the
# build cannot disagree with the module. The old script kept its own
# GO_MIN_MINOR=19 beside a module that said 1.24, accepted a toolchain four
# years too old, and then died inside go build with a message about toolchain
# downloads that named none of that.
#
# declare -f prints a function's heredocs verbatim, so the whole embedded
# tree is readable without touching the disk. It is fed to awk with a here
# string rather than a pipe on purpose: awk exits at the first match, and a
# printf pouring a hundred kilobytes into a pipe that just closed takes
# SIGPIPE and reports 141 under pipefail.
go_version_needed() {
    local body v=
    body=$(declare -f write_core_sources 2>/dev/null) || body=
    if [ -n "$body" ]; then
        v=$(awk '/^go [0-9]/ { print $2; exit }' <<<"$body")
    fi
    # If bash ever stops reproducing heredocs, fall back to reading the file
    # this writes. Slower, and correct for the same reason.
    if [ -z "$v" ]; then
        local tmp
        tmp=$(mktemp -d) || return 1
        write_core_sources "$tmp" >/dev/null 2>&1 &&
            v=$(awk '/^go [0-9]/ { print $2; exit }' "$tmp/go.mod")
        rm -rf "$tmp"
    fi
    [ -n "$v" ] || return 1
    printf '%s' "$v"
}

# ver_ge compares two dotted versions, missing parts counting as zero, so
# 1.24 and 1.24.0 are the same version. String comparison gets 1.9 and 1.24
# the wrong way round, which is exactly the pair that matters here.
ver_ge() {
    local i av bv
    local -a A B
    IFS=. read -r -a A <<<"$1"
    IFS=. read -r -a B <<<"$2"
    for i in 0 1 2; do
        av=${A[i]:-0}
        bv=${B[i]:-0}
        case $av in '' | *[!0-9]*) av=0 ;; esac
        case $bv in '' | *[!0-9]*) bv=0 ;; esac
        [ "$av" -gt "$bv" ] && return 0
        [ "$av" -lt "$bv" ] && return 1
    done
    return 0
}

# --------------------------------------------------------------------------
# a compiler
# --------------------------------------------------------------------------

# ensure_go finds a Go new enough for the module or offers to fetch one, and
# sets GO_BIN. It never installs anything without being asked.
ensure_go() {
    local want cand out v found= arch tar_ver url tmp pid rc

    if ! want=$(go_version_needed); then
        bad "the embedded go.mod could not be read, so I cannot tell what Go this needs"
        fix "rebuild the script from the repository:  ./build.sh"
        return 1
    fi

    # /usr/local/go before PATH: if an earlier run put one there it is the one
    # known to be new enough, and a distro package earlier on PATH usually is
    # not. command -v may print nothing; the quotes keep that an empty word
    # rather than dropping the loop item.
    for cand in /usr/local/go/bin/go "$(command -v go 2>/dev/null)"; do
        [ -x "$cand" ] || continue
        out=$("$cand" version 2>/dev/null) || continue
        v=${out#go version go}
        v=${v%% *}
        case $v in '' | *[!0-9.]*) continue ;; esac
        if ver_ge "$v" "$want"; then
            GO_BIN=$cand
            return 0
        fi
        found=$v
    done

    arch=$(arch_go)
    if [ -z "$arch" ]; then
        bad "$(uname -m) is not a machine this can build for"
        fix "amd64 and arm64 are what the core is built and tested on"
        return 1
    fi

    # A released minor always has a .0, so deriving the tarball from the go
    # directive keeps this from drifting the way a hardcoded GO_FALLBACK did.
    tar_ver=$want
    case $want in *.*.*) ;; *) tar_ver=$want.0 ;; esac
    url=$GO_DL_BASE/go$tar_ver.linux-$arch.tar.gz

    blank
    if [ -n "$found" ]; then
        warn "the Go here is $found and the core needs $want or newer"
    else
        warn "there is no Go on this machine, and the core is built here"
    fi
    blank
    dim "This is the one step that wants the network. It would fetch:"
    dim "  $url"
    field "size" "about 80 MB, roughly 250 MB unpacked"
    field "into" "/usr/local/go, deleting whatever is there now"
    blank
    dim "Nothing verifies it beyond TLS to go.dev: this script carries no"
    dim "checksum, and one fetched from the same place as the tarball would"
    dim "prove nothing. If that is not good enough, install Go by hand and run"
    dim "this again - it wants a compiler, not that compiler."
    blank

    if ! confirm "fetch it?" y; then
        bad "no compiler, so no core"
        fix "install Go $want or newer, then run this again"
        return 1
    fi

    tmp=$(mktemp) || return 1
    go_fetch_now() {
        if have curl; then
            curl -fSL --retry 2 --connect-timeout 20 -o "$tmp" "$url" >"$STATE_DIR/fetch.log" 2>&1
        else
            wget -O "$tmp" "$url" >"$STATE_DIR/fetch.log" 2>&1
        fi
    }
    if ! have curl && ! have wget; then
        rm -f "$tmp"
        bad "neither curl nor wget is installed, so nothing here can fetch it"
        fix "apt install curl   (or install Go yourself from $url)"
        return 1
    fi
    spin "fetching go$tar_ver for $arch" go_fetch_now
    rc=$?

    if [ "$rc" != 0 ]; then
        rm -f "$tmp"
        bad "the download failed, exit $rc"
        [ -s "$STATE_DIR/fetch.log" ] &&
            tail -n 3 "$STATE_DIR/fetch.log" | sed 's/^/       /'
        fix "from a machine that can reach it:  curl -fLO $url"
        fix "copy it here, then:  tar -C /usr/local -xzf go$tar_ver.linux-$arch.tar.gz"
        return 1
    fi

    # Unpack beside whatever is there and swap only when it worked. Deleting
    # first is how a truncated download leaves a server with no compiler at
    # all - including the too-old one it had a minute ago - and the advice
    # printed after that failure needs the network that just failed.
    rm -rf /usr/local/go.new
    if ! tar -C /usr/local --one-top-level=go.new --strip-components=1 -xzf "$tmp"; then
        rm -rf /usr/local/go.new
        rm -f "$tmp"
        bad "the tarball would not unpack - it is probably a truncated download"
        fix "run this again, or unpack it by hand into /usr/local"
        return 1
    fi
    rm -f "$tmp"
    if [ ! -x /usr/local/go.new/bin/go ]; then
        rm -rf /usr/local/go.new
        bad "the tarball unpacked but there is no bin/go in it"
        return 1
    fi
    rm -rf /usr/local/go.old
    [ -d /usr/local/go ] && mv /usr/local/go /usr/local/go.old
    mv /usr/local/go.new /usr/local/go
    rm -rf /usr/local/go.old

    if [ ! -x /usr/local/go/bin/go ]; then
        bad "the tarball unpacked but there is no /usr/local/go/bin/go in it"
        return 1
    fi
    GO_BIN=/usr/local/go/bin/go
    ok "go $tar_ver is installed in /usr/local/go"
    return 0
}

# --------------------------------------------------------------------------
# building
# --------------------------------------------------------------------------

build_core() {
    require_root
    ensure_dirs
    ensure_go || return 1

    local log out rc
    log=$STATE_DIR/build.log
    out=$SRC_DIR/pingify-core

    # Clear the tree first. A file dropped between versions would otherwise
    # sit there and be compiled alongside the new ones, and a stale
    # internal/carrier/*.go is a build error nobody can explain by reading
    # this script. The build cache under gocache/ is kept, so an unchanged
    # rebuild is a couple of seconds rather than forty.
    rm -rf "$SRC_DIR/cmd" "$SRC_DIR/internal" "$SRC_DIR/go.mod"
    if ! write_core_sources "$SRC_DIR"; then
        bad "the core sources could not be written into $SRC_DIR"
        fix "check there is space and that $SRC_DIR is writable:  df -h $SRC_DIR"
        return 1
    fi

    # GOPROXY=off and GOFLAGS=-mod=vendor because everything is already here:
    # saying so turns a confusing "cannot reach proxy.golang.org" into a build
    # that simply works. GOTOOLCHAIN=local because from 1.21 go will otherwise
    # try to download the toolchain the go directive names, over the network
    # this machine may not have - ensure_go has already checked the local one
    # is new enough, so there is nothing to gain and a hang to lose.
    go_build_now() {
        (
            cd "$SRC_DIR" &&
                GOTOOLCHAIN=local GO111MODULE=on GOPROXY=off GOSUMDB=off \
                    GOFLAGS=-mod=vendor GOPATH="$SRC_DIR/gopath" \
                    GOCACHE="$SRC_DIR/gocache" CGO_ENABLED=0 \
                    "$GO_BIN" build -trimpath -ldflags "-s -w" -o "$out" ./cmd/pingify
        ) >"$log" 2>&1
    }
    spin "compiling the core (a minute or so on a small VPS)" go_build_now
    rc=$?

    if [ "$rc" != 0 ]; then
        bad "the core did not build, go exited $rc"
        tail -n 20 "$log" | sed 's/^/       /'
        fix "the whole log is in $log"
        return 1
    fi

    # Only now. An install that overwrites the binary before the build is
    # known to have worked leaves a machine with no core and a running tunnel
    # that cannot be restarted.
    if ! install -m 0755 "$out" "$CORE_BIN"; then
        bad "the core built but would not install to $CORE_BIN"
        return 1
    fi
    # Ask the binary that just landed. `ok "core $(core_version) ..."` reads as
    # a check and is not one: the substitution runs inside an argument, so a
    # core that will not exec - wrong architecture, most likely - prints
    # "core  is installed" in green and returns success, and every later run
    # rebuilds it from scratch and says the same thing again.
    local here
    here=$(core_version)
    if [ -z "$here" ]; then
        bad "the core installed but will not run - is $(arch_go) really this machine?"
        return 1
    fi
    if [ "$here" != "$PINGIFY_VERSION" ]; then
        bad "the core says it is $here and this script is $PINGIFY_VERSION"
        fix "they are built from the same file, so this means a stale copy somewhere"
        return 1
    fi
    ok "core $here is installed at $CORE_BIN"
    return 0
}

# core_version prints what is installed, and nothing at all when there is no
# core to ask. The binary answers "pingify-core 2.0.0"; only the number is of
# use to a caller comparing it with this script's own.
core_version() {
    local out
    [ -x "$CORE_BIN" ] || return 1
    out=$("$CORE_BIN" -version 2>/dev/null) || return 1
    printf '%s' "${out#pingify-core }"
}

# ensure_core is what every path that needs a working core calls first.
#
# The version has to match this script exactly, not merely be present. The two
# halves ship together and a config key the manager writes may be one the
# older core refuses, which surfaces as the core rejecting a file the manager
# just built - a confusing failure a long way from its cause.
#
# Replacing the binary does not disturb a running tunnel: systemd keeps the
# old inode open until the unit is restarted, so nothing is felt until the
# caller restarts it, which is the caller's decision to make and to announce.
ensure_core() {
    local here
    here=$(core_version) || here=

    [ "$here" = "$PINGIFY_VERSION" ] && return 0

    if [ -n "$here" ]; then
        blank
        dim "the core here is $here and this manager is $PINGIFY_VERSION - rebuilding"
    fi
    build_core
}

# core_matches_script is the one comparison every screen makes: the two ship
# together, and a config key the manager writes may be one an older core
# refuses.
core_matches_script() {
    [ -x "$CORE_BIN" ] || return 1
    [ "$(core_version)" = "$PINGIFY_VERSION" ]
}
#!/usr/bin/env bash
#
# AmneziaWG: obfuscated WireGuard, from their packages rather than ours.
#
# This is the one transport Pingify does not implement. It is somebody else's
# careful cryptography with a deliberate junk-and-header layer on top of it,
# and the right thing to do with that is install it from the repository the
# people who wrote it publish - ppa:amnezia/ppa, the same one their own
# clients use - and drive it.
#
# What the tunnel does on top is unchanged. awg-quick brings up a private link
# between the two servers; the core then runs its ordinary UDP carrier inside
# that link, so the profile's queue depth, the socket buffers, the counters
# every screen reads, the status endpoint and the health port all work exactly
# as they do on every other transport. The obfuscation is theirs, the tuning
# is ours, and neither has to know about the other.
#
# The keys are the one thing that does not fit the shared-file design without
# help: WireGuard needs a private key on each side and the far side's public
# key, which is four values rather than one shared secret. Both keypairs are
# generated once, on the first server, and all four values travel in the file
# - so the second server still needs nothing but the paste, and each side
# picks out the half that is its own.

AWG_DIR=${PINGIFY_AWG_DIR:-/etc/amnezia/amneziawg}
AWG_PPA=${PINGIFY_AWG_PPA:-ppa:amnezia/ppa}

awg_ready() { have awg && have awg-quick; }

# awg_install adds their repository and installs from it.
#
# It is a network operation on a server that may not be able to reach a
# launchpad mirror, so the failure is reported as what it is rather than as a
# broken tunnel: the packages are missing, here is the command, and every
# other transport still works.
awg_install() {
    awg_ready && return 0
    blank
    dim "installing AmneziaWG from $AWG_PPA"
    if have add-apt-repository; then
        add-apt-repository -y "$AWG_PPA" >/dev/null 2>&1
    fi
    if have apt-get; then
        apt-get update >/dev/null 2>&1
        DEBIAN_FRONTEND=noninteractive apt-get install -y \
            amneziawg amneziawg-tools >/dev/null 2>&1
    fi
    if awg_ready; then
        ok "AmneziaWG installed - $(awg --version 2>/dev/null | head -1)"
        return 0
    fi
    bad "AmneziaWG could not be installed on this server"
    fix "it needs $AWG_PPA, which a server in Iran often cannot reach"
    fix "install it from a server that can, or pick another transport"
    return 1
}

# --------------------------------------------------------------------------
# what the wizard generates
# --------------------------------------------------------------------------

# awg_rand is a number in a range, from the kernel's own random device.
awg_rand() {
    local lo=$1 hi=$2 n
    n=$(od -An -N4 -tu4 /dev/urandom 2>/dev/null | tr -d ' \n')
    case $n in '' | *[!0-9]*) n=$((RANDOM * 32768 + RANDOM)) ;; esac
    printf '%s' $((lo + n % (hi - lo + 1)))
}

# awg_generate fills in the keys and the obfuscation for a new tunnel.
#
# The obfuscation numbers are what make an AmneziaWG packet not look like a
# WireGuard one: Jc junk packets of Jmin to Jmax bytes before the handshake,
# S1 and S2 bytes of junk inside the first two handshake packets, and H1 to H4
# in place of WireGuard's four fixed message types. They have to match on both
# servers, which they do, because they are generated once and travel in the
# file. The ranges are the ones Amnezia's own documentation gives.
awg_generate() {
    awg_ready || return 1
    T_AWG_IKEY=$(awg genkey)
    T_AWG_IPUB=$(printf '%s' "$T_AWG_IKEY" | awg pubkey)
    T_AWG_KKEY=$(awg genkey)
    T_AWG_KPUB=$(printf '%s' "$T_AWG_KKEY" | awg pubkey)
    [ -n "$T_AWG_IPUB" ] && [ -n "$T_AWG_KPUB" ] || return 1

    # Not generated. These five are the set that has been run on this path and
    # found stable - no periodic drops - and randomising them was how this
    # transport came to hand shake and then carry nothing. The documentation
    # gives ranges; the ranges contain combinations that do not work, and
    # finding out which is not something to do on somebody's live tunnel.
    #
    # S1 + 56 must not equal S2, and 68 and 91 do not.
    T_AWG_JC=5
    T_AWG_JMIN=50
    T_AWG_JMAX=1000
    T_AWG_S1=68
    T_AWG_S2=91

    # Four distinct header types, none of them the four WireGuard uses.
    local i h
    T_AWG_H1= T_AWG_H2= T_AWG_H3= T_AWG_H4=
    for i in 1 2 3 4; do
        while :; do
            h=$(awg_rand 5 2147483000)
            list_has "$h" "$T_AWG_H1" "$T_AWG_H2" "$T_AWG_H3" "$T_AWG_H4" || break
        done
        eval "T_AWG_H$i=\$h"
    done
    return 0
}

# --------------------------------------------------------------------------
# the link itself
# --------------------------------------------------------------------------

awg_iface() { toml_get "$(cfg_file "$1")" awg name; }

# awg_conf writes this server's half of the link.
#
# The file is built from the shared config every time rather than kept, so a
# change to the tunnel is a change to the interface without anybody having to
# remember there are two of them. 0600, because the private key is in it.
awg_conf() {
    local name=$1 f side iface mine peer_pub my_key peer_addr port endpoint
    f=$(cfg_file "$name")
    side=$(toml_get "$f" tunnel side)
    iface=$(toml_get "$f" awg name)
    [ -n "$iface" ] || return 1

    if [ "$side" = iran ]; then
        mine=$(toml_get "$f" awg iran)
        my_key=$(toml_get "$f" awg iran_key)
        peer_pub=$(toml_get "$f" awg kharej_pub)
        peer_addr=$(toml_get "$f" awg kharej)
    else
        mine=$(toml_get "$f" awg kharej)
        my_key=$(toml_get "$f" awg kharej_key)
        peer_pub=$(toml_get "$f" awg iran_pub)
        peer_addr=$(toml_get "$f" awg iran)
    fi
    port=$(toml_get "$f" awg port)

    # Both ends get an Endpoint and both get a ListenPort.
    #
    # WireGuard only needs one of them to know where the other is - the far
    # end learns the address from the first handshake that arrives. Setting
    # both anyway is what a working AmneziaWG deployment on this path does,
    # and the reason is the path: a side that has to learn the address has
    # nothing to send to until something arrives, and on a link where the
    # first packets are the ones most likely to be dropped that is a tunnel
    # that comes up only sometimes.
    if [ "$side" = iran ]; then
        endpoint="Endpoint = $(toml_get "$f" transport kharej):$port"
    else
        endpoint="Endpoint = $(toml_get "$f" transport iran):$port"
    fi

    mkdir -p "$AWG_DIR"
    umask 077
    cat >"$AWG_DIR/$iface.conf" <<CONF
# Written by Pingify for the tunnel $name. Edited here, it is overwritten on
# the next change: the tunnel's own file in $CFG_DIR is where it comes from.
[Interface]
PrivateKey = $my_key
Address = $mine
MTU = $(toml_get "$f" awg mtu)
ListenPort = $port
Jc = $(toml_get "$f" awg jc)
Jmin = $(toml_get "$f" awg jmin)
Jmax = $(toml_get "$f" awg jmax)
S1 = $(toml_get "$f" awg s1)
S2 = $(toml_get "$f" awg s2)
H1 = $(toml_get "$f" awg h1)
H2 = $(toml_get "$f" awg h2)
H3 = $(toml_get "$f" awg h3)
H4 = $(toml_get "$f" awg h4)

[Peer]
PublicKey = $peer_pub
AllowedIPs = ${peer_addr%.*}.0/24
$endpoint
PersistentKeepalive = 25
CONF
    chmod 0600 "$AWG_DIR/$iface.conf"
}

# awg_up writes the interface's config and starts it, and is safe to call
# again: awg-quick refuses a device that already exists, so the old one goes
# first. That is also what makes a settings change take effect.
awg_up() {
    local name=$1 iface
    iface=$(awg_iface "$name")
    [ -n "$iface" ] || return 0
    awg_conf "$name" || return 1
    systemctl disable --now "awg-quick@$iface" >/dev/null 2>&1
    ip link del "$iface" >/dev/null 2>&1
    if ! systemctl enable --now "awg-quick@$iface" >/dev/null 2>&1; then
        bad "the AmneziaWG link $iface would not come up"
        fix "journalctl -u awg-quick@$iface -n 20"
        return 1
    fi
    return 0
}

awg_down() {
    local name=$1 iface
    iface=$(awg_iface "$name")
    [ -n "$iface" ] || return 0
    systemctl disable --now "awg-quick@$iface" >/dev/null 2>&1
    ip link del "$iface" >/dev/null 2>&1
    rm -f "$AWG_DIR/$iface.conf"
    return 0
}

# awg_free_iface is the first awgN nothing on this host is using. The tunnel's
# own device is pfyN and this one is beside it, so a server with three tunnels
# has three of each and no two of them meet.
awg_free_iface() {
    local i=0
    while [ "$i" -lt 64 ]; do
        if ! ip link show "awg$i" >/dev/null 2>&1 &&
            [ ! -e "$AWG_DIR/awg$i.conf" ]; then
            printf 'awg%s' "$i"
            return 0
        fi
        i=$((i + 1))
    done
    return 1
}

# awg_handshake is how long ago the far end was last heard from, in seconds,
# or nothing when there has been no handshake at all. It is the one number
# that says whether the link underneath a tunnel is alive.
awg_handshake() {
    local iface=$1 t now
    have awg || return 1
    t=$(awg show "$iface" latest-handshakes 2>/dev/null | awk 'NR == 1 { print $2 }')
    case $t in '' | 0 | *[!0-9]*) return 1 ;; esac
    now=$(date +%s)
    printf '%s' $((now - t))
}
#!/usr/bin/env bash
#
# What is already taken on this server, and by whom.
#
# Every question the wizard asks that names a number - a port, a private
# network, a device - is a number something else on this machine may already
# hold. Two tunnels on one network route into each other; two on one port
# means whichever bound it first wins and the other never sees a connection;
# and the symptom of either is traffic going somewhere it was not meant to
# with nothing on the server to explain it. So every such question says what
# is taken, offers something that is not, and refuses a repeat.
#
# Two sources, always: the tunnels this server knows about, from their files,
# and what the kernel itself reports - an address on an interface, a socket
# listening - because a docker bridge or another VPN is just as much in the
# way as one of ours.

cfg_files() {
    local f
    for f in "$CFG_DIR"/*."$CFG_EXT"; do
        [ -f "$f" ] && printf '%s\n' "$f"
    done
    return 0
}

cfg_name() {
    local n
    n=$(toml_get "$1" tunnel name)
    if [ -z "$n" ]; then
        n=${1##*/}
        n=${n%.$CFG_EXT}
    fi
    printf '%s' "$n"
}

# --------------------------------------------------------------------------
# private networks
# --------------------------------------------------------------------------

# tun_nets [except] - "10.x.10 name" for every tunnel with a private link.
tun_nets() {
    local except=${1:-} f addr name
    cfg_files | while read -r f; do
        addr=$(toml_get "$f" tun iran)
        [ -n "$addr" ] || continue
        name=$(cfg_name "$f")
        [ -n "$except" ] && [ "$name" = "$except" ] && continue
        printf '%s %s\n' "${addr%.*}" "$name"
    done
    return 0
}

net_owner() {
    local want=$1 except=${2:-}
    tun_nets "$except" | while read -r net name; do
        if [ "$net" = "$want" ]; then
            printf '%s' "$name"
            break
        fi
    done
    return 0
}

# ip4_int turns a dotted quad into a number so two of them can be compared.
# The 10# prefixes are not decoration: bash reads a leading zero as octal.
ip4_int() {
    local a b c d rest x
    IFS=. read -r a b c d rest <<<"$1"
    [ -z "$rest" ] || return 1
    for x in "$a" "$b" "$c" "$d"; do
        case $x in '' | *[!0-9]*) return 1 ;; esac
        [ "$((10#$x))" -le 255 ] || return 1
    done
    printf '%s' $(((10#$a << 24) + (10#$b << 16) + (10#$c << 8) + 10#$d))
}

# net_overlap ADDR PLEN OCTET - does 10.<octet>.10.0/24 land inside an address
# already on this host. Comparing the top min(24, prefix) bits is what makes a
# docker bridge on 10.42.0.0/16 count as owning 10.42.10.0/24.
net_overlap() {
    local addr=$1 plen=$2 oct=$3 a b m
    a=$(ip4_int "$addr") || return 1
    case $plen in '' | *[!0-9]*) return 1 ;; esac
    case $oct in '' | *[!0-9]*) return 1 ;; esac
    b=$(((10 << 24) + ((10#$oct) << 16) + (10 << 8)))
    m=$plen
    [ "$m" -gt 24 ] && m=24
    [ "$m" -ge 1 ] || return 1
    [ "$((a >> (32 - m)))" -eq "$((b >> (32 - m)))" ]
}

# host_net_owner OCTET - prints "addr on dev" when an address on this host
# already covers 10.<octet>.10.0/24.
host_net_owner() {
    local oct=$1 dev addr plen
    have ip || return 1
    while read -r dev addr; do
        [ -n "$addr" ] || continue
        plen=${addr#*/}
        [ "$plen" = "$addr" ] && plen=32
        if net_overlap "${addr%%/*}" "$plen" "$oct"; then
            printf '%s on %s' "$addr" "$dev"
            return 0
        fi
    done < <(ip -4 -o addr 2>/dev/null | awk '$3 == "inet" { print $2, $4 }')
    return 1
}

host_has_net() { host_net_owner "$1" >/dev/null; }

# free_link_octet [except] - the lowest 1-254 nothing here owns.
free_link_octet() {
    local except=${1:-} x=1
    while [ "$x" -le 254 ]; do
        if [ -z "$(net_owner "10.${x}.10" "$except")" ] && ! host_has_net "$x"; then
            printf '%s' "$x"
            return 0
        fi
        x=$((x + 1))
    done
    return 1
}

show_taken_nets() {
    local except=${1:-} taken dev addr
    taken=$(tun_nets "$except")
    if [ -n "$taken" ]; then
        warn "private networks already used on this server"
        printf '%s\n' "$taken" | while read -r net name; do
            [ -n "$net" ] && dim "$(pad_to "${net}.0/24" 18)${BX_ARR} $name"
        done
    fi
    if have ip; then
        while read -r dev addr; do
            case ${addr%%/*} in
            10.*) dim "$(pad_to "$addr" 18)${BX_ARR} $dev, on this host" ;;
            esac
        done < <(ip -4 -o addr 2>/dev/null | awk '$3 == "inet" { print $2, $4 }')
    fi
    return 0
}

# --------------------------------------------------------------------------
# devices
# --------------------------------------------------------------------------

tun_ifaces() {
    local except=${1:-} f iface name
    cfg_files | while read -r f; do
        iface=$(toml_get "$f" tun name)
        [ -n "$iface" ] || continue
        name=$(cfg_name "$f")
        [ -n "$except" ] && [ "$name" = "$except" ] && continue
        printf '%s %s\n' "$iface" "$name"
    done
    return 0
}

iface_owner() {
    local want=$1 except=${2:-}
    tun_ifaces "$except" | while read -r iface name; do
        if [ "$iface" = "$want" ]; then
            printf '%s' "$name"
            break
        fi
    done
    return 0
}

host_has_iface() { [ -e "/sys/class/net/$1" ]; }

free_tun_iface() {
    local except=${1:-} n=0
    while [ "$n" -lt 64 ]; do
        if [ -z "$(iface_owner "pfy$n" "$except")" ] && ! host_has_iface "pfy$n"; then
            printf 'pfy%s' "$n"
            return 0
        fi
        n=$((n + 1))
    done
    return 1
}

# --------------------------------------------------------------------------
# the tunnel's own port
# --------------------------------------------------------------------------

# port_family says which kind of socket a transport binds. tcp and udp are
# separate: 9443/udp does not block 9443/tcp. ICMP and GRE have no port.
port_family() {
    case $1 in
    tcp | ws | wss | utls | fallback | rawtcp) printf 'tcp' ;;
    udp | awg) printf 'udp' ;;
    *) printf 'none' ;;
    esac
}

# tunnel_port_of FILE - "port family" for the port a tunnel's file names, on
# the side that waits for it. AmneziaWG's is the one somebody has to open.
tunnel_port_of() {
    local f=$1 t p fam
    t=$(toml_get "$f" transport type)
    fam=$(port_family "$t")
    [ "$fam" = none ] && return 1
    if [ "$t" = awg ]; then
        p=$(toml_get "$f" awg port)
    else
        p=$(toml_get "$f" transport port)
    fi
    case $p in '' | *[!0-9]*) return 1 ;; esac
    printf '%s %s' "$p" "$fam"
}

# tunnel_port_owner PORT TRANSPORT [except] - the tunnel that already carries
# on that port and family.
tunnel_port_owner() {
    local want=$1 fam except=${3:-} f name p
    fam=$(port_family "$2")
    case $want in '' | *[!0-9]*) return 0 ;; esac
    [ "$fam" = none ] && return 0
    cfg_files | while read -r f; do
        p=$(tunnel_port_of "$f") || continue
        [ "${p%% *}" = "$want" ] || continue
        [ "${p##* }" = "$fam" ] || continue
        name=$(cfg_name "$f")
        [ -n "$except" ] && [ "$name" = "$except" ] && continue
        printf '%s' "$name"
        break
    done
    return 0
}

show_taken_tunnel_ports() {
    local except=${1:-} listing
    listing=$(
        cfg_files | while read -r f; do
            p=$(tunnel_port_of "$f") || continue
            name=$(cfg_name "$f")
            [ -n "$except" ] && [ "$name" = "$except" ] && continue
            printf '%s %s %s\n' "$name" "${p%% *}" "${p##* }"
        done
    )
    [ -n "$listing" ] || return 0
    warn "tunnel ports this server already uses"
    printf '%s\n' "$listing" | while read -r name port fam; do
        [ -n "$name" ] && dim "$(pad_to "$name" 22)${BX_ARR} ${port}/${fam}"
    done
    dim "tcp and udp are separate: 9443/udp does not block 9443/tcp"
    blank
    return 0
}

# --------------------------------------------------------------------------
# forwarded ports
# --------------------------------------------------------------------------

# ports_of NAME - the tokens a tunnel forwards, as typed: the manager's state
# on the IRAN side, the [forward] table in the file otherwise.
ports_of() {
    local name=$1 list
    list=$(forwards_of "$name" 2>/dev/null | tr '\n' ' ')
    [ -n "${list// /}" ] || list=$(toml_arr "$(cfg_file "$name")" forward ports)
    printf '%s' "$(printf '%s' "$list" | tr -s ' ' | sed 's/^ //; s/ $//')"
}

show_taken_ports() {
    local except=${1:-} n list any=0
    while IFS= read -r n; do
        [ -n "$n" ] || continue
        [ "$n" = "$except" ] && continue
        list=$(ports_of "$n")
        [ -n "$list" ] || continue
        [ "$any" = 0 ] && warn "ports already forwarded on this server"
        any=1
        dim "$(pad_to "$n" 22)${BX_ARR} $list"
    done < <(cfg_list)
    [ "$any" = 1 ] && blank
    return 0
}

# --------------------------------------------------------------------------
# the two ports the manager picks by itself
# --------------------------------------------------------------------------

# The status endpoint has to be unique per tunnel, and asking the kernel
# whether a port is free only answers for the tunnels running right now - so
# the files are consulted too, or a second tunnel built while the first was
# stopped is handed the same port and the two fight over it at boot.
status_owner() {
    local want=$1 except=${2:-} f name
    case $want in '' | *[!0-9]*) return 0 ;; esac
    cfg_files | while read -r f; do
        [ "$(toml_get "$f" status port)" = "$want" ] || continue
        name=$(cfg_name "$f")
        [ -n "$except" ] && [ "$name" = "$except" ] && continue
        printf '%s' "$name"
        break
    done
    return 0
}

pick_status_port() {
    local except=${1:-} p=$STATUS_BASE n=0
    while [ "$n" -lt 100 ]; do
        if [ -z "$(status_owner "$p" "$except")" ] && port_free "$p" tcp; then
            printf '%s' "$p"
            return 0
        fi
        p=$((p + 1))
        n=$((n + 1))
    done
    return 1
}

show_taken_status() {
    local except=${1:-} listing
    listing=$(
        cfg_files | while read -r f; do
            p=$(toml_get "$f" status port)
            [ -n "$p" ] || continue
            name=$(cfg_name "$f")
            [ -n "$except" ] && [ "$name" = "$except" ] && continue
            printf '%s %s\n' "$name" "$p"
        done
    )
    [ -n "$listing" ] || return 0
    warn "status ports already used on this server"
    printf '%s\n' "$listing" | while read -r name p; do
        [ -n "$name" ] && dim "$(pad_to "$name" 22)${BX_ARR} 127.0.0.1:$p"
    done
    blank
    return 0
}

# The health port is bound to the tunnel's own private address, so only a
# listener on every address is in the way of it - and on Linux an IPv6
# wildcard holds the IPv4 one along with it.
health_bound() {
    local p=$1 a
    have ss || return 1
    while read -r a; do
        case $a in
        "0.0.0.0:$p" | "*:$p" | "[::]:$p" | ":::$p") return 0 ;;
        esac
    done < <(ss -ltnH 2>/dev/null | awk '{ print $4 }')
    return 1
}

free_health_port() {
    local p=$HEALTH_PORT n=0
    while health_bound "$p"; do
        p=$((p + 1))
        n=$((n + 1))
        [ "$n" -gt 20 ] && return 1
    done
    printf '%s' "$p"
}

# --------------------------------------------------------------------------
# the token an ICMP tunnel is told apart by
# --------------------------------------------------------------------------

# An ICMP tunnel has no port: what tells it apart from another one on the
# same server is an identifier taken from its token. Two sharing a token
# read each other's packets, both flap, and the log blames the token.
icmp_token_owner() {
    local want=$1 except=${2:-} f name
    [ -n "$want" ] || return 0
    cfg_files | while read -r f; do
        [ "$(toml_get "$f" transport type)" = icmp ] || continue
        [ "$(toml_get "$f" security token)" = "$want" ] || continue
        name=$(cfg_name "$f")
        [ -n "$except" ] && [ "$name" = "$except" ] && continue
        printf '%s' "$name"
        break
    done
    return 0
}

show_taken_icmp_token() {
    local owner
    owner=$(icmp_token_owner "$1" "${2:-}")
    [ -n "$owner" ] || return 0
    warn "the tunnel \"$owner\" already carries ICMP with this token"
    dim "Both would put the same identifier on every packet, so each would"
    dim "read the other's. Give this one a different token."
    return 1
}
#!/usr/bin/env bash
#
# The wizard: the questions on the first server, one paste on the second.
#
# The config file is the same on both servers but for the side and the name
# that carries it, so the second server does not answer questions at all: it
# takes a short setup token the first one printed, flips the side, checks
# that nothing on it is in the way, and writes the file.
#
# Every question is its own function reading into a T_* variable, so a test
# can drive the real wizard through its stdin. The steps run down one page
# and nothing is cleared between them, so the answers already given stay on
# screen above the question being asked.

# ---------------------------------------------------------------------------
# what a tunnel is made of
# ---------------------------------------------------------------------------

cfg_reset() {
    T_NAME= T_SIDE= T_TRANSPORT=tcp T_MODE=forward T_KIND=tcp
    # Which end opens the connection. IRAN dials out by default, because on a
    # real Iranian line that is the one that survives: a connection dialled
    # INTO Iran is commonly allowed to complete, carry a few exchanges, and
    # then be blackholed with no reset and no error - measured, repeatedly,
    # on this tool's own test pair. Ports still live on IRAN either way.
    T_DIALS=iran
    T_PUBLIC_IP= T_PEER_IP= T_IRAN= T_KHAREJ=
    T_PORT=8443 T_PATH= T_CONNS=8
    T_TOKEN= T_PRESET=balanced T_LOG=info
    T_STATUS= T_HEALTH=
    T_FORWARDS=
    T_OCTET= T_TUNIF= T_TUNLOCAL= T_TUNPEER= T_TUNMTU=1320
    T_FEC= T_QUEUE=
    T_AWG_PORT=51820 T_AWG_IFACE= T_AWG_IKEY= T_AWG_IPUB= T_AWG_KKEY= T_AWG_KPUB=
    T_AWG_JC= T_AWG_JMIN= T_AWG_JMAX= T_AWG_S1= T_AWG_S2=
    T_AWG_H1= T_AWG_H2= T_AWG_H3= T_AWG_H4=
}

# mode_of is the kind a transport makes: streams forward ports, packets need
# a private link. The core refuses the other pairing.
mode_of() {
    case $1 in
    tcp | ws | wss | utls | fallback) printf 'forward' ;;
    *) printf 'tun' ;;
    esac
}
cfg_mode() {
    T_MODE=$(mode_of "$T_TRANSPORT")
    [ "$T_MODE" = tun ] && T_KIND=tun || T_KIND=tcp
}
cfg_needs_link() { [ "$(mode_of "${1:-$T_TRANSPORT}")" = tun ]; }

side_label() {
    case $1 in
    iran | server) printf 'IRAN' ;;
    kharej | client) printf 'KHAREJ' ;;
    *) printf '%s' "${1^^}" ;;
    esac
}
other_side() { [ "$1" = iran ] && printf 'kharej' || printf 'iran'; }

transport_label() {
    case $1 in
    tcp) printf 'TCP MUX' ;;
    ws) printf 'WS MUX' ;;
    wss) printf 'WSS MUX' ;;
    utls) printf 'TCP UTLS' ;;
    fallback) printf 'TLS FALLBACK' ;;
    icmp) printf 'ICMP' ;;
    gre) printf 'GRE' ;;
    udp) printf 'UDP' ;;
    rawtcp) printf 'Raw TCP' ;;
    awg) printf 'AmneziaWG' ;;
    *) printf '%s' "${1^^}" ;;
    esac
}

# kind_label wears the [TUN] tag on the transports that build a link.
kind_label() {
    if cfg_needs_link "$1"; then printf 'TUN %s' "$(transport_label "$1")"
    else transport_label "$1"; fi
}

# The side that waits for the connection. A bound port only matters there.
waits_side() { other_side "${T_DIALS:-iran}"; }
this_side_waits() { [ "$T_SIDE" = "$(waits_side)" ]; }

# The name a tunnel is given, which is also the name of its file. It starts
# with the side, so `ls /root/pingify` says which end of the border each
# file is; then the transport, then the one number that tells two of the
# same kind apart - the port, or for ICMP and GRE, which have none, the
# private link's octet. iran-tcp-8443, iran-udp-8446, kharej-icmp-20.
tunnel_default_name() {
    local side=${1:-$T_SIDE} trans=${2:-$T_TRANSPORT} num
    case $trans in
    awg) num=$T_AWG_PORT ;;
    icmp | gre) num=$T_OCTET ;;
    *) num=$T_PORT ;;
    esac
    printf '%s-%s-%s' "$side" "$trans" "${num:-1}"
}

# The same tunnel's name on the other server: the first word is the side.
name_for_side() {
    local name=$1 side=$2
    case $name in
    iran-* | kharej-*) printf '%s-%s' "$side" "${name#*-}" ;;
    *) printf '%s' "$name" ;;
    esac
}

unique_name() {
    local base=$1 n=$1 i=2
    while [ -e "$(cfg_file "$n")" ]; do
        n="$base-$i"
        i=$((i + 1))
        [ "$i" -gt 50 ] && break
    done
    printf '%s' "$n"
}

# ---------------------------------------------------------------------------
# the security token
#
# Generated rather than asked for: eighteen random bytes are twenty-four
# base64 characters, which removes a question and the whole class of bug
# where one server has the token with a trailing space and the other does
# not. Both servers print the same fingerprint when the token matches, which
# is the only way to tell a wrong token apart from a broken network.
# ---------------------------------------------------------------------------

wiz_sha256() {
    if have sha256sum; then sha256sum | cut -d' ' -f1
    elif have shasum; then shasum -a 256 | cut -d' ' -f1
    elif have openssl; then openssl dgst -sha256 | sed 's/.*= *//'
    else return 1
    fi
}

wiz_token() {
    local t
    t=$(head -c 18 /dev/urandom 2>/dev/null | base64 2>/dev/null) || t=
    t=${t//$'\n'/}
    [ "${#t}" -ge 16 ] || return 1
    printf '%s' "$t"
}

token_print() {
    local t h
    t=$(printf '%s' "${1:-}" | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//')
    [ -n "$t" ] || { printf 'none'; return; }
    h=$(printf '%s' "$t" | wiz_sha256) || { printf 'unknown'; return; }
    printf '%s' "${h:0:8}"
}
wiz_fingerprint() { token_print "$1"; }

# ---------------------------------------------------------------------------
# performance presets
#
# Everything the tunnel tunes was measured to have one right answer whatever
# it carries - the socket buffers, the batching, a pacing rate it works out
# for itself. What trades is how deep the queues may get: a deep one absorbs
# bursts and carries more; a shallow one is emptier when a small packet
# arrives, so that packet waits less. Measured on the real path, Tehran to
# Frankfurt, restarted fresh at each depth:
#
#   profile     queue    16 streams   one stream   under load
#   gaming        600     397 Mbit/s   167 Mbit/s   84.5 / 92.5 ms
#   balanced      900     448          254          93.3 / 106.5
#   download     1500     466          253         115.8 / 139.3
# ---------------------------------------------------------------------------

preset_rcvbuf() {
    case $1 in
    download) printf '3072' ;;
    *) printf '256' ;;
    esac
}

preset_queue() {
    case $1 in
    gaming) printf '600' ;;
    download) printf '1500' ;;
    *) printf '900' ;;
    esac
}

preset_menu() {
    CHOICE_DEF=2
    choice 1 "Gaming" "shallow queues - lowest delay under load"
    choice 2 "Balanced" "the one to pick if unsure"
    choice 3 "Download" "deep queues - most throughput for many streams"
    CHOICE_DEF=
    blank
    dim "Deeper queues carry more; shallower ones answer faster. Changeable later."
    blank
    local n
    pick n "select" 2 3 || return 1
    case $n in
    1) T_PRESET=gaming ;;
    3) T_PRESET=download ;;
    *) T_PRESET=balanced ;;
    esac
    return 0
}

# ---------------------------------------------------------------------------
# reading a tunnel back
# ---------------------------------------------------------------------------

cfg_load() {
    local f
    f=$(cfg_file "$1")
    [ -f "$f" ] || return 1
    cfg_reset
    T_NAME=$(toml_get "$f" tunnel name)
    [ -n "$T_NAME" ] || T_NAME=$1
    T_SIDE=$(toml_get "$f" tunnel side)
    T_TRANSPORT=$(toml_get "$f" transport type)
    [ -n "$T_TRANSPORT" ] || T_TRANSPORT=udp
    T_MODE=$(toml_get "$f" tunnel mode)
    [ -n "$T_MODE" ] || T_MODE=$(mode_of "$T_TRANSPORT")
    [ "$T_MODE" = tun ] && T_KIND=tun || T_KIND=tcp
    T_DIALS=$(toml_get "$f" transport dials)
    [ -n "$T_DIALS" ] || T_DIALS=kharej
    T_IRAN=$(toml_get "$f" transport iran)
    T_KHAREJ=$(toml_get "$f" transport kharej)
    if [ "$T_SIDE" = iran ]; then T_PUBLIC_IP=$T_IRAN T_PEER_IP=$T_KHAREJ
    else T_PUBLIC_IP=$T_KHAREJ T_PEER_IP=$T_IRAN; fi
    T_PORT=$(toml_get "$f" transport port)
    T_PATH=$(toml_get "$f" transport path)
    T_CONNS=$(toml_get "$f" transport connections)
    [ -n "$T_CONNS" ] || T_CONNS=8
    T_TOKEN=$(toml_get "$f" security token)
    T_PRESET=$(toml_get "$f" tuning profile)
    [ -n "$T_PRESET" ] || T_PRESET=balanced
    T_FEC=$(toml_get "$f" tuning fec)
    T_QUEUE=$(toml_get "$f" tuning queue_packets)
    T_LOG=$(toml_get "$f" logging level)
    [ -n "$T_LOG" ] || T_LOG=info
    T_STATUS=$(toml_get "$f" status port)
    T_HEALTH=$(toml_get "$f" status health_port)
    T_FORWARDS=$(ports_of "$1")
    if [ "$T_MODE" = tun ]; then
        T_TUNIF=$(toml_get "$f" tun name)
        [ -n "$T_TUNIF" ] || T_TUNIF=pfy0
        local a b
        a=$(toml_get "$f" tun iran)
        b=$(toml_get "$f" tun kharej)
        if [ "$T_SIDE" = iran ]; then T_TUNLOCAL=$a T_TUNPEER=$b; else T_TUNLOCAL=$b T_TUNPEER=$a; fi
        T_OCTET=${a#10.}
        T_OCTET=${T_OCTET%%.*}
        T_TUNMTU=$(toml_get "$f" tun mtu)
        [ -n "$T_TUNMTU" ] || T_TUNMTU=1320
    fi
    if [ "$T_TRANSPORT" = awg ]; then
        T_AWG_IFACE=$(toml_get "$f" awg name)
        T_AWG_PORT=$(toml_get "$f" awg port)
        T_AWG_IKEY=$(toml_get "$f" awg iran_key)
        T_AWG_IPUB=$(toml_get "$f" awg iran_pub)
        T_AWG_KKEY=$(toml_get "$f" awg kharej_key)
        T_AWG_KPUB=$(toml_get "$f" awg kharej_pub)
        T_AWG_JC=$(toml_get "$f" awg jc)
        T_AWG_JMIN=$(toml_get "$f" awg jmin)
        T_AWG_JMAX=$(toml_get "$f" awg jmax)
        T_AWG_S1=$(toml_get "$f" awg s1)
        T_AWG_S2=$(toml_get "$f" awg s2)
        T_AWG_H1=$(toml_get "$f" awg h1)
        T_AWG_H2=$(toml_get "$f" awg h2)
        T_AWG_H3=$(toml_get "$f" awg h3)
        T_AWG_H4=$(toml_get "$f" awg h4)
    fi
    return 0
}

# ---------------------------------------------------------------------------
# the file
#
# Every setting the core reads, written out with its value, in two columns
# and nothing else - what a person expects to find when they open it, and
# what the Tuning screen edits in place. The values a preset chooses are in
# the file as numbers, so what the tunnel runs with is what the file says.
# ---------------------------------------------------------------------------

fwd_toml_list() {
    local first=1 t
    for t in "$@"; do
        [ "$first" = 1 ] || printf ', '
        printf '"%s"' "$t"
        first=0
    done
}

cfg_render() {
    local mode=${T_MODE:-$(mode_of "$T_TRANSPORT")}
    kv() { printf '%-16s = %s\n' "$1" "$2"; }
    q() { printf '"%s"' "$1"; }

    printf '[tunnel]\n'
    kv name "$(q "$T_NAME")"
    kv side "$(q "$T_SIDE")"
    kv mode "$(q "$mode")"

    printf '\n[transport]\n'
    kv type "$(q "$T_TRANSPORT")"
    kv kharej "$(q "$T_KHAREJ")"
    kv iran "$(q "$T_IRAN")"
    case $T_TRANSPORT in
    icmp | gre) ;;
    *) kv port "$T_PORT" ;;
    esac
    kv dials "$(q "$T_DIALS")"
    case $T_TRANSPORT in
    tcp | ws | wss | utls | fallback) kv connections "${T_CONNS:-8}" ;;
    esac
    kv keepalive_sec 10
    case $T_TRANSPORT in
    ws | wss) kv path "$(q "$T_PATH")" ;;
    esac
    case $T_TRANSPORT in
    wss | utls | fallback)
        kv cert '""'
        kv key '""'
        kv insecure false
        ;;
    esac

    if [ "$T_TRANSPORT" = awg ]; then
        printf '\n[awg]\n'
        kv name "$(q "$T_AWG_IFACE")"
        kv iran "$(q "10.$T_OCTET.20.1/24")"
        kv kharej "$(q "10.$T_OCTET.20.2/24")"
        kv mtu 1320
        kv port "$T_AWG_PORT"
        kv iran_key "$(q "$T_AWG_IKEY")"
        kv iran_pub "$(q "$T_AWG_IPUB")"
        kv kharej_key "$(q "$T_AWG_KKEY")"
        kv kharej_pub "$(q "$T_AWG_KPUB")"
        kv jc "$T_AWG_JC"
        kv jmin "$T_AWG_JMIN"
        kv jmax "$T_AWG_JMAX"
        kv s1 "$T_AWG_S1"
        kv s2 "$T_AWG_S2"
        kv h1 "$T_AWG_H1"
        kv h2 "$T_AWG_H2"
        kv h3 "$T_AWG_H3"
        kv h4 "$T_AWG_H4"
    fi

    printf '\n[security]\n'
    kv token "$(q "$T_TOKEN")"

    printf '\n[tuning]\n'
    kv profile "$(q "$T_PRESET")"
    kv queue_packets "${T_QUEUE:-$(preset_queue "$T_PRESET")}"
    kv rcvbuf_kb "$(preset_rcvbuf "$T_PRESET")"
    kv sndbuf_kb 16384
    if [ "$mode" = tun ]; then
        kv send_batch 32
        kv pace true
        kv pace_mbit 0
    fi
    kv dscp 0
    if [ "$mode" = tun ] && [ "$T_TRANSPORT" != gre ]; then
        kv fec "${T_FEC:-0}"
    fi

    printf '\n[forward]\n'
    # shellcheck disable=SC2086
    kv ports "[$(fwd_toml_list $T_FORWARDS)]"
    if [ "$mode" = forward ]; then
        kv bind_addr '"0.0.0.0"'
        kv allow "[]"
    fi

    if [ "$mode" = tun ]; then
        printf '\n[tun]\n'
        kv name "$(q "$T_TUNIF")"
        kv iran "$(q "10.$T_OCTET.10.1/24")"
        kv kharej "$(q "10.$T_OCTET.10.2/24")"
        kv mtu "${T_TUNMTU:-1320}"
        kv txqueuelen 1000
        kv write_workers 0
        kv queues 1
    fi

    printf '\n[logging]\n'
    kv level "$(q "${T_LOG:-info}")"

    printf '\n[status]\n'
    kv port "${T_STATUS:-$STATUS_BASE}"
    if [ "$mode" = forward ]; then
        kv health_port -1
    else
        kv health_port "${T_HEALTH:-$HEALTH_PORT}"
    fi
}

# ---------------------------------------------------------------------------
# writing it, and saying honestly what happened
# ---------------------------------------------------------------------------

# tunnel_create NAME FILE - FILE is the finished config. It is checked by
# the core before anything is started, and nothing is left behind when the
# core refuses it.
tunnel_create() {
    local name=$1 src=$2 f out
    [ -n "$name" ] || { fail "a tunnel needs a name"; return 1; }
    ensure_dirs || { fail "could not create $CFG_DIR"; return 1; }
    f=$(cfg_file "$name")
    [ -e "$f" ] && { fail "there is already a tunnel called $name here"; return 1; }
    if [ ! -x "$CORE_BIN" ]; then
        fail "the core is not installed at $CORE_BIN"
        fix "install Pingify first - nothing has been changed"
        return 1
    fi
    # The file is 0600 before a single byte of the token exists in it.
    : >"$f" || { fail "could not write $f"; return 1; }
    chmod 0600 "$f"
    cat "$src" >"$f" || { fail "could not write $f"; rm -f "$f"; return 1; }

    if ! out=$("$CORE_BIN" -c "$f" -check 2>&1); then
        fail "the core rejected this configuration - nothing created"
        core_matches_script || dim "the core is $(core_version) and this script is $PINGIFY_VERSION - update the core"
        printf '%s\n' "$out" | sed 's/^/       /'
        rm -f "$f"
        return 1
    fi
    ok "$(trunc_to "$f" $((UI_W - 30))) accepted by the core"

    # A [TUN] tunnel's ports live in its file so that they travel in the
    # token, and in the forwards state on IRAN so that the firewall has them.
    if [ "$(toml_get "$f" tunnel mode)" = tun ] && [ "$(toml_get "$f" tunnel side)" = iran ] &&
        [ ! -s "$(fwd_file "$name")" ]; then
        local ports
        ports=$(toml_arr "$f" forward ports)
        if [ -n "$ports" ]; then
            if ! forwards_set "$name" "$ports"; then
                warn "the ports in the file could not be kept; set them on the Ports screen"
            elif have iptables; then
                nat_apply "$name" || warn "the ports are kept but not yet in the firewall; set them again on the Ports screen"
            fi
        fi
    fi

    [ -f "$UNIT_DIR/pingify@.service" ] || unit_write

    case $(toml_get "$f" transport type) in
    awg)
        # The AmneziaWG link is the wire this tunnel runs on, so it comes up
        # first. If it will not, the tunnel is not started.
        if ! awg_up "$name"; then
            rm -f "$f"
            return 1
        fi
        ok "the AmneziaWG link $(awg_iface "$name") is up"
        ;;
    rawtcp)
        # Without this the kernel answers our own segments with an RST and
        # the tunnel resets itself every few seconds.
        if ! rawtcp_guard "$(toml_get "$f" transport port)"; then
            fail "could not tell the firewall to stop answering for this port"
            fix "iptables is needed for a raw tcp tunnel"
            rm -f "$f"
            return 1
        fi
        ok "the kernel will not answer on tcp/$(toml_get "$f" transport port)"
        ;;
    esac

    svc_do enable "$name"
}

# ---------------------------------------------------------------------------
# the setup token
#
# Short, so it survives a paste over a phone: the fields of the tunnel joined
# with pipes, text fields wrapped in base64 so a pipe or a space inside one
# cannot split it, a checksum on the end, and the whole thing base64 again
# with PFY3. in front so a paste can be told apart from anything else.
# ---------------------------------------------------------------------------

tok_enc() { printf '%s' "$1" | base64 | tr -d '\n'; }
tok_dec() { printf '%s' "$1" | base64 -d 2>/dev/null; }
setup_token_bad() { SETUP_TOKEN_ERROR=$1; return 1; }

cfg_setup_token() {
    local body sum
    body=$(printf 'p6|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s' \
        "$T_NAME" "$T_TRANSPORT" "$T_MODE" "$T_DIALS" \
        "$(tok_enc "$T_KHAREJ")" "$(tok_enc "$T_IRAN")" "$T_PORT" "$(tok_enc "$T_PATH")" "$T_CONNS" \
        "$(tok_enc "$T_TOKEN")" "$T_PRESET" "$T_LOG" "$T_HEALTH" \
        "$T_OCTET" "$T_TUNIF" "$T_TUNMTU" "$(tok_enc "$T_FORWARDS")" \
        "$T_AWG_IFACE" "$T_AWG_PORT" "$(tok_enc "$T_AWG_IKEY")" "$(tok_enc "$T_AWG_IPUB")" \
        "$(tok_enc "$T_AWG_KKEY")" "$(tok_enc "$T_AWG_KPUB")" \
        "$T_AWG_JC" "$T_AWG_JMIN" "$T_AWG_JMAX" "$T_AWG_S1" "$T_AWG_S2" \
        "$T_AWG_H1" "$T_AWG_H2" "$T_AWG_H3" "$T_AWG_H4" \
        "$T_FEC" "$T_QUEUE" "$PINGIFY_VERSION")
    sum=$(printf '%s' "$body" | wiz_sha256) || return 1
    printf 'PFY3.%s' "$(printf '%s|%s' "$body" "${sum:0:16}" | base64 | tr -d '\n')"
}

# setup_token_read TOKEN - fills the T_* variables from a token printed by
# the other server, and flips the side to this one. The name follows.
setup_token_read() {
    local line raw body sum want fields
    local v name tr mode dials kh ir port path conns tok preset lg health
    local oct tunif mtu fwd aif aport ikey ipub kkey kpub jc jmin jmax s1 s2 h1 h2 h3 h4 fec queue ver
    SETUP_TOKEN_ERROR=
    line=${1//[[:space:]]/}
    case $line in
    PFY3.*) ;;
    PFY2.*) setup_token_read_file "$line"; return $? ;;
    *) setup_token_bad "that is not a Pingify setup token - it starts with PFY3."; return 1 ;;
    esac
    raw=$(tok_dec "${line#PFY3.}") || { setup_token_bad "the token will not decode - copy the whole line"; return 1; }
    case $raw in p6\|*) ;; *) setup_token_bad "the token will not decode - copy the whole line"; return 1 ;; esac
    body=${raw%|*}
    sum=${raw##*|}
    want=$(printf '%s' "$body" | wiz_sha256) || { setup_token_bad "no sha256 tool here, so the token cannot be checked"; return 1; }
    [ "${want:0:16}" = "$sum" ] || { setup_token_bad "the token checksum does not match - copy the whole line"; return 1; }
    fields=$(printf '%s' "$body" | awk -F'|' '{ print NF }')
    [ "$fields" = 36 ] || { setup_token_bad "the token is incomplete"; return 1; }
    IFS='|' read -r v name tr mode dials kh ir port path conns tok preset lg health \
        oct tunif mtu fwd aif aport ikey ipub kkey kpub jc jmin jmax s1 s2 h1 h2 h3 h4 fec queue ver <<<"$body"

    cfg_reset
    T_NAME=$name T_TRANSPORT=$tr T_MODE=$mode T_DIALS=$dials
    T_KHAREJ=$(tok_dec "$kh") || { setup_token_bad "the address field is damaged"; return 1; }
    T_IRAN=$(tok_dec "$ir") || { setup_token_bad "the address field is damaged"; return 1; }
    T_PORT=$port
    T_PATH=$(tok_dec "$path") || T_PATH=
    T_CONNS=${conns:-8}
    T_TOKEN=$(tok_dec "$tok") || { setup_token_bad "the security field is damaged"; return 1; }
    T_PRESET=${preset:-balanced} T_LOG=${lg:-info} T_HEALTH=$health
    T_OCTET=$oct T_TUNIF=$tunif T_TUNMTU=${mtu:-1320}
    T_FORWARDS=$(tok_dec "$fwd") || T_FORWARDS=
    T_AWG_IFACE=$aif T_AWG_PORT=${aport:-51820}
    T_AWG_IKEY=$(tok_dec "$ikey") T_AWG_IPUB=$(tok_dec "$ipub")
    T_AWG_KKEY=$(tok_dec "$kkey") T_AWG_KPUB=$(tok_dec "$kpub")
    T_AWG_JC=$jc T_AWG_JMIN=$jmin T_AWG_JMAX=$jmax T_AWG_S1=$s1 T_AWG_S2=$s2
    T_AWG_H1=$h1 T_AWG_H2=$h2 T_AWG_H3=$h3 T_AWG_H4=$h4
    T_FEC=$fec T_QUEUE=$queue
    TOKEN_VERSION=$ver
    setup_token_check
}

# A token made by a 2.2.0 manager carries the whole file. It is read the
# same way, from a temporary copy, so a pair started on the old manager can
# still be finished on this one.
setup_token_read_file() {
    local line=$1 raw sum body have tmp
    raw=$(tok_dec "${line#PFY2.}") || { setup_token_bad "the token will not decode - copy the whole line"; return 1; }
    sum=${raw%%|*}
    body=${raw#*|}
    [ "$sum" != "$raw" ] || { setup_token_bad "the token will not decode - copy the whole line"; return 1; }
    have=$(printf '%s\n' "$body" | wiz_sha256) || { setup_token_bad "no sha256 tool here"; return 1; }
    [ "$have" = "$sum" ] || { setup_token_bad "the token checksum does not match - copy the whole line"; return 1; }
    local dir keep=$CFG_DIR rc
    dir=$(mktemp -d) || return 1
    tmp=$dir/pasted.toml
    printf '%s
' "$body" >"$tmp"
    CFG_DIR=$dir
    cfg_load pasted
    rc=$?
    CFG_DIR=$keep
    T_NAME=$(toml_get "$tmp" tunnel name)
    T_FORWARDS=$(toml_arr "$tmp" forward ports)
    rm -rf "$dir"
    [ "$rc" = 0 ] || { setup_token_bad "the token did not carry a readable config"; return 1; }
    TOKEN_VERSION=$(sed -n 's/^# Pingify \([0-9.]*\).*/\1/p' <<<"$body" | head -1)
    setup_token_check
}

# setup_token_check refuses a token that describes a tunnel this manager
# cannot build, before a single question is asked about it.
setup_token_check() {
    case $T_TRANSPORT in
    tcp | ws | wss | utls | fallback | icmp | gre | udp | rawtcp | awg) ;;
    *) setup_token_bad "unknown transport $T_TRANSPORT"; return 1 ;;
    esac
    [ "$T_MODE" = "$(mode_of "$T_TRANSPORT")" ] || { setup_token_bad "transport and mode disagree"; return 1; }
    [ "$T_MODE" = tun ] && T_KIND=tun || T_KIND=tcp
    case $T_DIALS in iran | kharej) ;; *) setup_token_bad "the token does not say which end dials"; return 1 ;; esac
    case $T_SIDE in iran | kharej) ;; *) T_SIDE= ;; esac
    [ -n "$T_TOKEN" ] || { setup_token_bad "the security token is empty"; return 1; }
    [ -n "$T_IRAN" ] && [ -n "$T_KHAREJ" ] || { setup_token_bad "an address is missing"; return 1; }
    case $T_TRANSPORT in
    icmp | gre) T_PORT= ;;
    *)
        case $T_PORT in '' | *[!0-9]*) setup_token_bad "the tunnel port is invalid"; return 1 ;; esac
        [ "$T_PORT" -ge 1 ] && [ "$T_PORT" -le 65535 ] || { setup_token_bad "the tunnel port is out of range"; return 1; }
        ;;
    esac
    if [ "$T_MODE" = tun ]; then
        v_octet "$T_OCTET" >/dev/null 2>&1 || { setup_token_bad "the private link is incomplete"; return 1; }
        [ -n "$T_TUNIF" ] || T_TUNIF=pfy0
        v_mtu "$T_TUNMTU" >/dev/null 2>&1 || { setup_token_bad "the private MTU is out of range"; return 1; }
    fi
    if [ "$T_TRANSPORT" = awg ]; then
        [ -n "$T_AWG_IKEY" ] && [ -n "$T_AWG_KKEY" ] && [ -n "$T_AWG_IPUB" ] && [ -n "$T_AWG_KPUB" ] ||
            { setup_token_bad "the AmneziaWG key material is incomplete"; return 1; }
        v_port "$T_AWG_PORT" >/dev/null 2>&1 || { setup_token_bad "the AmneziaWG port is invalid"; return 1; }
    fi
    case $T_PRESET in gaming | balanced | download) ;; *) T_PRESET=balanced ;; esac
    case $T_LOG in debug | info | warn | error) ;; *) T_LOG=info ;; esac
    return 0
}

# ---------------------------------------------------------------------------
# what is said about a transport before it is chosen
# ---------------------------------------------------------------------------

# The public addresses of this server, one to a line. The private ranges are
# struck out, carrier grade NAT included: an address in 100.64/10 is one the
# provider handed out behind a shared public one.
wiz_public_ips() {
    local a found=1
    for a in $(ip -4 -o addr show scope global 2>/dev/null |
        awk '$3 == "inet" { sub("/.*", "", $4); print $4 }'); do
        case $a in
        10.* | 127.* | 192.168.* | 169.254.* | \
            172.1[6-9].* | 172.2[0-9].* | 172.3[01].* | \
            100.6[4-9].* | 100.[7-9][0-9].* | 100.1[01][0-9].* | 100.12[0-7].*) continue ;;
        esac
        printf '%s\n' "$a"
        found=0
    done
    return "$found"
}
wiz_public_ip() {
    local a
    a=$(wiz_public_ips | head -1)
    [ -n "$a" ] || return 1
    printf '%s' "$a"
}

# is_name says "this is a domain and not an address".
is_name() { case $1 in *[a-zA-Z]*) return 0 ;; *) return 1 ;; esac; }

# A path nobody scans for: six hex characters.
wiz_path() {
    local h
    h=$(head -c 3 /dev/urandom 2>/dev/null | od -An -tx1 | tr -d ' \n')
    [ -n "$h" ] || h=$(printf '%06x' $((RANDOM * RANDOM % 16777216)))
    printf '/%s' "$h"
}

# Cloudflare proxies only a handful of ports; a WebSocket on any other one
# is not behind the CDN at all.
cdn_ports() { printf '80 8080 8880 2052 2082 2086 2095 443 2053 2083 2087 2096 8443'; }
cdn_port_warn() {
    case $T_TRANSPORT in ws | wss) ;; *) return 0 ;; esac
    local p ok=0
    for p in $(cdn_ports); do [ "$p" = "$T_PORT" ] && ok=1; done
    [ "$ok" = 1 ] && return 0
    blank
    warn "Cloudflare does not proxy port $T_PORT"
    dim "behind the CDN, use one of: $(cdn_ports)"
    dim "direct, without a CDN, any port works"
}

# ---------------------------------------------------------------------------
# the questions
# ---------------------------------------------------------------------------

ask_side() {
    wiz "Which server is this?"
    choice 1 "IRAN" "clients connect here, and the ports live here"
    choice 2 "KHAREJ" "your panel and inbounds run here"
    choice 3 "Paste a token" "finish this server from the other one"
    blank
    dim "q at any question leaves without building anything"
    blank
    local side
    pick side "select" "" 3 || return 1
    case $side in
    1) T_SIDE=iran ;;
    2) T_SIDE=kharej ;;
    3) T_SIDE=paste ;;
    esac
    return 0
}

ask_transport() {
    wiz "Transport"
    group "FORWARDING - your ports, carried over a connection"
    choice 1 "TCP MUX" "plain TCP, several connections multiplexed"
    choice 2 "WS MUX" "WebSocket on port 80 - a CDN can front it"
    choice 3 "WSS MUX" "WebSocket inside TLS - a domain or Cloudflare"
    choice 4 "TCP UTLS" "TLS that looks like Chrome on the wire"
    choice 5 "TLS FALLBACK" "UTLS, and a real website for anyone probing"
    group "TUN - a private link between the two servers"
    choice 6 "ICMP" "inside ping packets - no port at all"
    choice 7 "GRE" "IP protocol 47 - fast, not hidden, no port"
    choice 8 "UDP" "plain UDP on one port"
    choice 9 "Raw TCP" "TCP-shaped packets, no connection to throttle"
    choice 10 "AmneziaWG" "obfuscated WireGuard - encrypted"
    blank
    local proto
    pick proto "select" "" 10 || return 1
    case $proto in
    1) T_TRANSPORT=tcp ;;
    2) T_TRANSPORT=ws
        blank
        warn "WS is not encrypted by itself - choose WSS when TLS or a CDN is available" ;;
    3) T_TRANSPORT=wss ;;
    4) T_TRANSPORT=utls ;;
    5) T_TRANSPORT=fallback ;;
    6) T_TRANSPORT=icmp
        blank
        dim "This server stops answering ordinary pings while the tunnel runs." ;;
    7) T_TRANSPORT=gre
        blank
        warn "GRE is not encrypted and not hidden - anything on the path can read it"
        confirm_yes "use GRE?" || return 1 ;;
    8) T_TRANSPORT=udp
        blank
        warn "needs UDP to pass between the two servers, which many Iranian lines stop" ;;
    9) T_TRANSPORT=rawtcp ;;
    10) T_TRANSPORT=awg
        blank
        warn "rides on UDP, which many Iranian lines stop"
        awg_install || return 1 ;;
    esac
    cfg_mode
    return 0
}

# Only transports that bind a port have a direction to choose. ICMP has no
# port to be reachable on, GRE is its own protocol, and AmneziaWG names both
# ends itself; on all three IRAN sends first.
# Only transports that bind a port have a direction to choose. ICMP has no
# port to be reachable on, GRE is its own protocol, and AmneziaWG names both
# ends itself; on all three IRAN sends first.
ask_direction() {
    T_DIALS=iran
    case $T_TRANSPORT in icmp | gre | awg) return 0 ;; esac
    wiz "Link direction"
    CHOICE_DEF=1
    choice 1 "Direct" "IRAN connects out to KHAREJ"
    choice 2 "Reverse" "KHAREJ connects in - a CDN in front of IRAN, or NAT"
    CHOICE_DEF=
    blank
    dim "Users and ports stay on IRAN either way; this is only who opens the connection."
    blank
    local dir
    pick dir "select" 1 2 || return 1
    [ "$dir" = 2 ] && T_DIALS=kharej
    return 0
}

# Both addresses, always. The far one is obvious - somebody has to be dialled
# or answered. The near one matters on a server with more than one address:
# a reply that leaves from an address the far end is not expecting is a reply
# the far end throws away.
ask_addresses() {
    local other n i=0 def=
    local -a addrs=()
    other=$(side_label "$(other_side "$T_SIDE")")
    wiz "Addresses"
    while IFS= read -r n; do addrs+=("$n"); done < <(wiz_public_ips)
    case $T_TRANSPORT in
    ws | wss) dim "The public IP of each server, or a domain for the end a CDN fronts." ;;
    *) dim "The public IP of each server." ;;
    esac
    blank
    if [ "${#addrs[@]}" -gt 1 ]; then
        dim "this server answers on more than one address - pick the right one"
        blank
        while [ "$i" -lt "${#addrs[@]}" ]; do
            choice "$((i + 1))" "$(addr_tint "${addrs[i]}")"
            i=$((i + 1))
        done
        choice "$((i + 1))" "Something else" "a domain, or one not listed"
        blank
        pick n "select" "" $((i + 1)) || return 1
        [ "$n" -le "${#addrs[@]}" ] && T_PUBLIC_IP=${addrs[n - 1]}
        blank
    elif [ "${#addrs[@]}" = 1 ]; then
        def=${addrs[0]}
        dim "this machine answers on ${C_OFF}${def}${C_DIM} - press enter to take it"
        blank
    fi
    if [ -z "$T_PUBLIC_IP" ]; then
        if [ "$T_TRANSPORT" = wss ] || [ "$T_TRANSPORT" = ws ]; then
            ask T_PUBLIC_IP "domain or address of this $(side_label "$T_SIDE") server" "$def" v_host || return 1
        else
            ask T_PUBLIC_IP "address of this $(side_label "$T_SIDE") server" "$def" v_host || return 1
        fi
    fi
    blank
    if [ "$T_TRANSPORT" = wss ] || [ "$T_TRANSPORT" = ws ]; then
        ask T_PEER_IP "domain or address of the $other server" "" v_host || return 1
    else
        ask T_PEER_IP "address of the $other server" "" v_host || return 1
    fi
    if [ "$T_SIDE" = iran ]; then T_IRAN=$T_PUBLIC_IP T_KHAREJ=$T_PEER_IP
    else T_KHAREJ=$T_PUBLIC_IP T_IRAN=$T_PEER_IP; fi
    case $T_TRANSPORT in ws | wss) T_PATH=$(wiz_path) ;; esac
    return 0
}

# v_wiz_port refuses a port another tunnel here already carries on, and - on
# the side that waits - one something else already listens on.
v_wiz_port() {
    local who fam
    v_port "$1" || return 1
    fam=$(port_family "$T_TRANSPORT")
    who=$(tunnel_port_owner "$1" "$T_TRANSPORT" "${WIZ_KEEP:-}")
    if [ -n "$who" ]; then
        echo "$1/$fam is already the tunnel port of $who - pick another, or delete that tunnel first"
        return 1
    fi
    if this_side_waits; then
        local bind
        bind=$(cdn_listen_port "$1")
        if ! port_free "$bind" "$fam"; then
            echo "something is already listening on $bind/$fam - check with:  ss -lnp | grep :$bind"
            return 1
        fi
    fi
    return 0
}

# cdn_listen_port is the port the waiting side really binds. Behind a name
# on one of the HTTPS ports, Cloudflare's flexible mode ends the TLS at the
# edge and comes to the origin in plain HTTP on 80 - which is what the core
# binds in that case, so that is the port to check for a clash.
cdn_listen_port() {
    case $T_TRANSPORT in ws | wss) ;; *) printf '%s' "$1"; return ;; esac
    is_name "$T_PUBLIC_IP" || { printf '%s' "$1"; return; }
    case $1 in 443 | 2053 | 2083 | 2087 | 2096 | 8443) printf '80' ;; *) printf '%s' "$1" ;; esac
}

v_awg_port() {
    v_port "$1" || return 1
    if ! port_free "$1" udp; then
        echo "something here already listens on udp/$1 - see: ss -lunp | grep :$1"
        return 1
    fi
    return 0
}

ask_port() {
    local fam def
    case $T_TRANSPORT in
    icmp | gre) T_PORT=; return 0 ;;
    awg)
        wiz "Port" "AmneziaWG listens on this. The same number on both servers."
        ask T_AWG_PORT "UDP port for the tunnel, same on both" "$T_AWG_PORT" v_awg_port || return 1
        dim "leave ${T_AWG_PORT}/udp open in this server's firewall"
        return 0
        ;;
    esac
    fam=$(port_family "$T_TRANSPORT")
    wiz "Port" "The port the two servers meet on. Only the end that waits binds it."
    this_side_waits && show_taken_tunnel_ports
    case $T_TRANSPORT in
    ws) def=80 ;;
    wss) def=443 ;;
    *) def=8443 ;;
    esac
    while [ -n "$(tunnel_port_owner "$def" "$T_TRANSPORT")" ] ||
        { this_side_waits && ! port_free "$def" "$fam"; }; do
        def=$((def + 1))
        [ "$def" -gt 8500 ] && break
    done
    ask T_PORT "port for the tunnel itself, same on both" "$def" v_wiz_port || return 1
    if this_side_waits; then
        if [ "$(cdn_listen_port "$T_PORT")" != "$T_PORT" ]; then
            dim "behind the CDN this end listens on 80 in plain HTTP; leave 80/tcp open here"
        else
            dim "leave ${T_PORT}/${fam} open in this server's firewall"
        fi
    fi
    cdn_port_warn
    return 0
}

v_wiz_octet() {
    local who
    v_octet "$1" || return 1
    who=$(net_owner "10.$1.10" "${WIZ_KEEP:-}")
    if [ -n "$who" ]; then
        echo "10.$1.10.0/24 already belongs to $who - pick another x, or delete that tunnel first"
        return 1
    fi
    if who=$(host_net_owner "$1"); then
        echo "this server already has $who on that network - docker, or another VPN"
        return 1
    fi
    return 0
}

v_wiz_iface() {
    local who
    case $1 in '' | *[!a-zA-Z0-9_-]*) echo "letters, digits, dash and underscore"; return 1 ;; esac
    [ "${#1}" -le 15 ] || { echo "linux stops at 15 characters"; return 1; }
    who=$(iface_owner "$1" "${WIZ_KEEP:-}")
    [ -z "$who" ] || { echo "$1 already belongs to $who"; return 1; }
    host_has_iface "$1" && { echo "this server already has an interface called $1"; return 1; }
    return 0
}

# One question decides the network; both addresses are worked out from it
# and shown rather than re-asked, so a hand edit cannot walk past the checks
# that guarded the question.
ask_link() {
    cfg_needs_link || return 0
    wiz "Private link" "Both servers get an address on a small network of their own."
    show_taken_nets
    local def
    def=$(free_link_octet) || def=
    [ -n "$def" ] || warn "every 10.x.10.0/24 is inside an address on this host"
    ask T_OCTET "range 10.x.10.0/24 - pick x" "$def" v_wiz_octet || return 1
    if [ "$T_SIDE" = iran ]; then
        T_TUNLOCAL="10.$T_OCTET.10.1/24" T_TUNPEER="10.$T_OCTET.10.2/24"
    else
        T_TUNLOCAL="10.$T_OCTET.10.2/24" T_TUNPEER="10.$T_OCTET.10.1/24"
    fi
    blank
    field "IRAN" "$(addr_tint "10.$T_OCTET.10.1/24")"
    field "KHAREJ" "$(addr_tint "10.$T_OCTET.10.2/24")"
    blank
    ask T_TUNIF "device name" "$(free_tun_iface)" v_wiz_iface || return 1
    case $T_TRANSPORT in
    awg) T_TUNMTU=1280 ;;
    *) T_TUNMTU=1320 ;;
    esac
    ask T_TUNMTU "MTU" "$T_TUNMTU" v_mtu || return 1
    return 0
}

# The IRAN side owns the ports. Two tunnels forwarding one port means
# whichever bound it first wins and the other never sees a connection, so
# what is taken is listed and a repeat is refused - and so is a port
# something else on this server already listens on.
ask_forwards() {
    [ "$T_SIDE" = iran ] || return 0
    wiz "Ports" "The ports your clients will connect to, here on IRAN."
    show_taken_ports
    dim "one port 443   a range 8000-8010   udp udp:500   elsewhere 443=8443"
    blank
    local raw clashes
    while :; do
        ask raw "ports, comma separated" "" v_forwards_needed || return 1
        if clashes=$(forwards_clash "" "$raw"); then
            T_FORWARDS=$(fwd_tokens "$raw" | tr '\n' ' ')
            T_FORWARDS=${T_FORWARDS% }
            return 0
        fi
        printf '%s\n' "$clashes" | while read -r line; do [ -n "$line" ] && fail "$line"; done
        dim "pick another port, or free that one first"
        blank
    done
}

v_forwards_needed() {
    [ -n "$1" ] || { echo "at least one port is required - it is what users connect to"; return 1; }
    v_forwards "$1"
}

ask_preset() {
    wiz "Performance" "The shape of your traffic. You can change it later."
    preset_menu
}

ask_logging() {
    wiz "How much to log" "Each level includes the ones above it."
    CHOICE_DEF=3
    choice 1 "error" "only what is broken"
    choice 2 "warn" "and what is wrong but survivable"
    choice 3 "info" "and what a healthy tunnel does"
    choice 4 "debug" "and why each connection and packet did what it did"
    CHOICE_DEF=
    blank
    local lg
    pick lg "select" 3 4 || return 1
    case $lg in
    1) T_LOG=error ;;
    2) T_LOG=warn ;;
    4) T_LOG=debug ;;
    *) T_LOG=info ;;
    esac
    return 0
}

# ---------------------------------------------------------------------------
# the review, and the creation both entrances share
# ---------------------------------------------------------------------------

dials_text() {
    if [ "$T_SIDE" = "$T_DIALS" ]; then
        printf 'direct - connects to %s' "$(addr_tint "$T_PEER_IP")"
    else
        printf 'reverse - accepts from %s' "$(addr_tint "$T_PEER_IP")"
    fi
}

review_panel() {
    local trans
    trans=$(kind_label "$T_TRANSPORT")
    case $T_TRANSPORT in
    awg) trans="$trans, udp/$T_AWG_PORT" ;;
    icmp | gre) ;;
    *) trans="$trans, $(port_family "$T_TRANSPORT")/$T_PORT" ;;
    esac
    panel "$T_NAME"
    panel_field "This server" "$(side_label "$T_SIDE")"
    panel_field "Address" "$(addr_tint "$T_PUBLIC_IP")"
    panel_field "Type" "$trans"
    panel_field "Link" "$(dials_text)"
    [ -n "$T_PATH" ] && panel_field "Web path" "$T_PATH"
    if cfg_needs_link; then
        panel_field "Private link" "$(addr_tint "${T_TUNLOCAL%%/*}") ${G_BOTH} $(addr_tint "${T_TUNPEER%%/*}")   $T_TUNIF   mtu $T_TUNMTU"
    fi
    [ -n "$T_FORWARDS" ] && panel_field "Ports" "$T_FORWARDS"
    panel_field "Token" "$(token_print "$T_TOKEN")"
    panel_field "Tuning" "${T_PRESET^}, queue $(preset_queue "$T_PRESET") packets"
    panel_field "Logging" "$T_LOG"
    panel_end
}

# wiz_create writes the file, starts the tunnel, and reports. Everything
# after the last question, on both entrances.
wiz_create() {
    local tmp
    blank
    tmp=$(mktemp) || { fail "could not make a temporary file"; return 1; }
    cfg_render >"$tmp"
    if ! tunnel_create "$T_NAME" "$tmp"; then
        rm -f "$tmp"
        return 1
    fi
    rm -f "$tmp"
    enable_watchdog quiet
    dim "$(cfg_file "$T_NAME")"
    return 0
}

# ---------------------------------------------------------------------------
# build a new tunnel
# ---------------------------------------------------------------------------

new_tunnel() {
    banner
    head2 "New tunnel"
    wiz_end
    ensure_core || { pause; return 1; }
    cfg_reset
    wiz_reset

    ask_side || { wiz_end; return 0; }
    if [ "$T_SIDE" = paste ]; then
        import_tunnel
        local rc=$?
        wiz_end
        return $rc
    fi

    ask_transport || { wiz_end; return 0; }
    ask_direction || { wiz_end; return 0; }
    ask_addresses || { wiz_end; return 0; }
    ask_port || { wiz_end; return 0; }
    ask_link || { wiz_end; return 0; }
    ask_forwards || { wiz_end; return 0; }
    ask_preset || { wiz_end; return 0; }
    ask_logging || { wiz_end; return 0; }

    # -- the things nobody has to be asked ---------------------------------
    if [ "$T_TRANSPORT" = awg ]; then
        # The carrier inside the link gets a port of its own, worked out from
        # the octet, where nothing outside can reach it.
        T_PORT=$((20900 + T_OCTET))
        T_AWG_IFACE=$(awg_free_iface) || { fail "there is no free awg device left on this host"; pause; wiz_end; return 1; }
        awg_generate || { fail "AmneziaWG would not generate a key here"; pause; wiz_end; return 1; }
    fi
    T_NAME=$(unique_name "$(tunnel_default_name)")
    if ! T_TOKEN=$(wiz_token); then
        warn "no random source here, so the token has to be typed"
        ask T_TOKEN "security token" "" v_token || { wiz_end; return 0; }
    fi
    if [ "$T_MODE" = tun ]; then
        if ! T_HEALTH=$(free_health_port); then
            T_HEALTH=$HEALTH_PORT
            warn "$HEALTH_PORT and the twenty above it are all taken on this server"
            dim "the tunnel will work; its round trip will not be measurable"
        fi
    else
        T_HEALTH=-1
    fi
    if ! T_STATUS=$(pick_status_port); then
        fail "every status port from $STATUS_BASE is taken here"
        pause; wiz_end; return 1
    fi

    # -- review ------------------------------------------------------------
    blank
    ok "this tunnel is called ${C_B}${T_NAME}${C_OFF}"
    ok "security token generated - fingerprint ${C_YEL}$(token_print "$T_TOKEN")${C_OFF}"
    banner
    head2 "Ready to create"
    review_panel
    blank
    if ! confirm_yes "create the tunnel ${C_B}${T_NAME}${C_OFF}?"; then
        warn "cancelled, nothing was written"
        pause; wiz_end
        return 1
    fi

    wiz_create || { pause; wiz_end; return 1; }
    blank

    # -- the other server --------------------------------------------------
    local other
    other=$(side_label "$(other_side "$T_SIDE")")
    head2 "Now the $other server"
    dim "run Pingify there and choose  New tunnel ${BX_ARR} Paste a token"
    blank
    rule
    printf '%s\n' "${C_YEL}$(cfg_setup_token)${C_OFF}"
    rule
    blank
    warn "treat it like a password - it carries the security token"
    blank
    tunnel_status_block "$T_NAME"
    pause
    wiz_end
    return 0
}

# ---------------------------------------------------------------------------
# finish the pair from a token
# ---------------------------------------------------------------------------

v_wiz_paste() {
    local s=${1//[[:space:]]/}
    case $s in
    '') echo "paste the whole line the other server printed"; return 1 ;;
    PFY3.* | PFY2.*) return 0 ;;
    esac
    echo "that is not a Pingify token - the line starts with PFY3."
    return 1
}

import_tunnel() {
    banner
    head2 "Paste the setup token"
    dim "Printed by the other server when its tunnel was made. It carries the"
    dim "whole config, so there is nothing left to answer."
    blank
    local token
    ask token "token" "" v_wiz_paste || return 1
    if ! setup_token_read "$token"; then
        fail "$SETUP_TOKEN_ERROR"
        pause; return 1
    fi
    if [ -n "${TOKEN_VERSION:-}" ] && [ "$TOKEN_VERSION" != "$PINGIFY_VERSION" ]; then
        warn "that token came from Pingify $TOKEN_VERSION and this is $PINGIFY_VERSION"
        dim "the two servers should run the same version; update the other one after this"
    fi

    # The side in the token is the other server's. This flip is the entire
    # second installation, and the name goes with it.
    local from
    from=$(printf '%s' "$T_NAME" | cut -d- -f1)
    case $from in
    iran) T_SIDE=kharej ;;
    kharej) T_SIDE=iran ;;
    *) fail "that token does not say which server made it"; pause; return 1 ;;
    esac
    T_NAME=$(name_for_side "$T_NAME" "$T_SIDE")
    if [ "$T_SIDE" = iran ]; then T_PUBLIC_IP=$T_IRAN T_PEER_IP=$T_KHAREJ
    else T_PUBLIC_IP=$T_KHAREJ T_PEER_IP=$T_IRAN; fi
    if cfg_needs_link; then
        if [ "$T_SIDE" = iran ]; then T_TUNLOCAL="10.$T_OCTET.10.1/24" T_TUNPEER="10.$T_OCTET.10.2/24"
        else T_TUNLOCAL="10.$T_OCTET.10.2/24" T_TUNPEER="10.$T_OCTET.10.1/24"; fi
    fi
    [ "$T_TRANSPORT" = awg ] && { awg_install || { pause; return 1; }; }

    blank
    head2 "This server"
    dim "the token came from $(side_label "$(other_side "$T_SIDE")"), so this is the $(side_label "$T_SIDE") side"
    blank

    # -- what is in the way here -------------------------------------------
    local clash=0 own
    if [ -e "$(cfg_file "$T_NAME")" ]; then
        warn "a tunnel named $T_NAME already exists on this server"
        if confirm "replace it?"; then
            svc_do stop "$T_NAME" >/dev/null 2>&1
            systemctl disable "pingify@$T_NAME" >/dev/null 2>&1
            nat_drop "$T_NAME" >/dev/null 2>&1 || true
            awg_down "$T_NAME" >/dev/null 2>&1 || true
            rm -f "$(cfg_file "$T_NAME")" "$(fwd_file "$T_NAME")"
        else
            clash=1
        fi
    fi
    if cfg_needs_link; then
        own=$(net_owner "10.$T_OCTET.10")
        if [ -n "$own" ]; then
            fail "10.$T_OCTET.10.0/24 is already used here by $own"
            dim "change the range on the first server, and paste again"
            clash=1
        elif own=$(host_net_owner "$T_OCTET"); then
            fail "this server already has $own on 10.$T_OCTET.10.0/24"
            dim "change the range on the first server, and paste again"
            clash=1
        fi
        if [ -n "$(iface_owner "$T_TUNIF")" ] || host_has_iface "$T_TUNIF"; then
            local alt
            alt=$(free_tun_iface)
            warn "the device $T_TUNIF is in use here; this side will use $alt"
            dim "the device name is local to each server, so the two may differ"
            T_TUNIF=$alt
        fi
    fi
    if [ "$T_TRANSPORT" = awg ]; then
        if ! port_free "$T_AWG_PORT" udp; then
            fail "something here already listens on udp/$T_AWG_PORT"
            dim "ss -lunp | grep :$T_AWG_PORT   shows what has it"
            clash=1
        fi
        T_AWG_IFACE=$(awg_free_iface) || { fail "no free awg device here"; clash=1; }
    elif [ -n "$T_PORT" ] && this_side_waits; then
        local fam
        fam=$(port_family "$T_TRANSPORT")
        own=$(tunnel_port_owner "$T_PORT" "$T_TRANSPORT")
        if [ -n "$own" ]; then
            fail "${T_PORT}/$fam is already $own's tunnel port here"
            dim "change the port on the first server, and paste again"
            clash=1
        elif ! port_free "$T_PORT" "$fam"; then
            fail "something here already listens on ${T_PORT}/$fam"
            dim "ss -lnp | grep :$T_PORT   shows what has it"
            clash=1
        fi
    fi
    if [ "$clash" = 1 ]; then
        blank
        dim "nothing was created"
        pause
        return 1
    fi
    if [ "$T_MODE" = tun ] && [ "$T_HEALTH" != -1 ] && health_bound "${T_HEALTH:-$HEALTH_PORT}"; then
        warn "something here already holds port ${T_HEALTH:-$HEALTH_PORT} on every address"
        dim "the tunnel works; its round trip will not be measurable from the other end"
    fi
    if ! T_STATUS=$(pick_status_port); then
        fail "every status port from $STATUS_BASE is taken here"
        pause; return 1
    fi
    [ -n "$T_PORT" ] && this_side_waits && dim "leave ${T_PORT}/$(port_family "$T_TRANSPORT") open in this server's firewall"
    [ "$T_TRANSPORT" = awg ] && dim "leave ${T_AWG_PORT}/udp open in this server's firewall"

    banner
    head2 "Ready to create"
    review_panel
    blank
    confirm_yes "create the tunnel ${C_B}${T_NAME}${C_OFF}?" || { warn "cancelled"; pause; return 1; }

    wiz_create || { pause; return 1; }
    blank
    head2 "Both servers are set up"
    dim "this end was built from the other server's token, so there is nothing to carry back"
    dim "give it a few seconds and look at it under Manage tunnels"
    blank
    tunnel_status_block "$T_NAME"
    pause
    return 0
}

# The names the menus and the tests reach the wizard by.
wizard_new() { new_tunnel; }
screen_new() { new_tunnel; return 0; }
#!/usr/bin/env bash
#
# Manage tunnels: the list, one tunnel's screen, and the things that can be
# changed on it. Everything a screen reports comes from two sources and no
# third: systemd says whether the unit is running, and the core's own status
# endpoint says whether it is carrying anything. Nothing reads the log.

# ---------------------------------------------------------------------------
# where the other end is
# ---------------------------------------------------------------------------

# peer_addr is the other end of the private link, without its prefix.
peer_addr() {
    local f side a
    f=$(cfg_file "$1")
    side=$(toml_get "$f" tunnel side)
    if [ "$side" = iran ]; then a=$(toml_get "$f" tun kharej); else a=$(toml_get "$f" tun iran); fi
    printf '%s' "${a%%/*}"
}

my_addr() {
    local f side a
    f=$(cfg_file "$1")
    side=$(toml_get "$f" tunnel side)
    if [ "$side" = iran ]; then a=$(toml_get "$f" tun iran); else a=$(toml_get "$f" tun kharej); fi
    printf '%s' "${a%%/*}"
}

# peer_public is the other server's public address, from the file.
peer_public() {
    local f side
    f=$(cfg_file "$1")
    side=$(toml_get "$f" tunnel side)
    if [ "$side" = iran ]; then toml_get "$f" transport kharej; else toml_get "$f" transport iran; fi
}

# tun_rtt is the round trip to the other end, in whole milliseconds, or
# nothing when it cannot be measured.
#
# A forward tunnel measures itself with a ping record every ten seconds and
# reports it. A private link is measured on the far end's health port: one
# TCP handshake across the link, which is one round trip and nothing else.
# Not with ping - an ICMP tunnel on either server mutes echo for every link
# on it, and a ping that waits a second for a reply that is never coming,
# once per tunnel, is why a list of nine took thirteen seconds to draw.
tun_rtt() {
    local name=$1 f out hp peer
    f=$(cfg_file "$name")
    if [ "$(toml_get "$f" tunnel mode)" = forward ]; then
        tun_stats "$name" || return 0
        case $ST_FAR_RTT in '' | 0 | *[!0-9.]*) return 0 ;; esac
        LC_ALL=C awk -v t="$ST_FAR_RTT" 'BEGIN { printf "%.0f", t }'
        return 0
    fi
    have curl || return 0
    hp=$(health_port_of "$name")
    peer=$(peer_addr "$name")
    [ -n "$peer" ] && [ "$hp" -gt 0 ] 2>/dev/null || return 0
    out=$(LC_ALL=C curl -s -o /dev/null --max-time 1 -w '%{time_connect}' "http://$peer:$hp/healthz" 2>/dev/null) || return 0
    case $out in '' | 0 | 0.000000) return 0 ;; esac
    LC_ALL=C awk -v t="$out" 'BEGIN { printf "%.0f", t * 1000 }'
}

# ---------------------------------------------------------------------------
# status rendering
# ---------------------------------------------------------------------------

# tunnel_status_block is the few lines under a tunnel's name: the service,
# the token's fingerprint, and what the core says it is doing.
tunnel_status_block() {
    local name=$1 f state colour
    f=$(cfg_file "$name")
    [ -f "$f" ] || { fail "no such tunnel: $name"; return 1; }
    state=$(svc_state "$name")
    colour=$C_RED
    [ "$state" = active ] && colour=$C_GRN
    printf '  %s%s%s  service %s%s%s   token %s%s%s\n' \
        "$C_B" "$name" "$C_OFF" "$colour" "$state" "$C_OFF" \
        "$C_YEL" "$(token_print "$(toml_get "$f" security token)")" "$C_OFF"
    if [ "$state" != active ]; then
        dim "not running - nothing to report"
        return 0
    fi
    if ! tun_stats "$name"; then
        dim "starting up, or the status port is not answering yet"
        return 0
    fi
    local link
    if [ "$ST_UP" = true ] && [ "${ST_INB:-0}" != 0 ]; then
        link="${C_GRN}up${C_OFF} for $(human_secs "$ST_UPTIME"), the other server has been heard from"
    elif [ "$ST_UP" = true ]; then
        link="${C_YEL}up${C_OFF} for $(human_secs "$ST_UPTIME"), nothing from the other server yet"
    else
        link="${C_YEL}waiting${C_OFF} for the other server, $(human_secs "$ST_UPTIME") so far"
    fi
    dim "$link"
    dim "carrying $(round1 "$ST_IN") Mbit/s in, $(round1 "$ST_OUT") out"
    if [ "${ST_LOST:-0}" -gt 0 ] 2>/dev/null; then
        dim "the path has lost $ST_LOST packets in ${ST_GAPS:-0} runs, ${ST_LATE:-0} arrived late"
    fi
    local rtt
    rtt=$(tun_rtt "$name")
    [ -n "$rtt" ] && dim "round trip $(rtt_tint "${rtt}ms") to the other server"
    return 0
}

# One line per tunnel, for the overview table. NAME SIDE PROTO LINK RTT MBIT
tunnel_row() {
    local name=$1 nw=${2:-13} f side proto state dot link rtt=- rate=-
    f=$(cfg_file "$name")
    side=$(side_label "$(toml_get "$f" tunnel side)")
    proto=$(transport_label "$(toml_get "$f" transport type)")
    state=$(svc_state "$name")
    dot="$C_GRY$BX_OFF$C_OFF" link=-
    case $state in
    active)
        if tun_stats "$name"; then
            if [ "$ST_UP" = true ] && [ "${ST_INB:-0}" != 0 ]; then
                dot="$C_GRN$BX_ON$C_OFF" link=up
            else
                dot="$C_YEL$BX_ON$C_OFF" link=alone
            fi
            rate="$(round1 "$ST_IN")/$(round1 "$ST_OUT")"
            rtt=$(tun_rtt "$name")
            [ -n "$rtt" ] && rtt="${rtt}ms" || rtt=-
        else
            dot="$C_YEL$BX_ON$C_OFF" link=starting
        fi
        ;;
    stopped) dot="$C_YEL$BX_OFF$C_OFF" link=stopped ;;
    *) dot="$C_GRY$BX_OFF$C_OFF" link=disabled ;;
    esac
    printf '  %s %s %s %s %s %s%s%s %s\n' \
        "$dot" \
        "$(pad_to "${C_B}${name}${C_OFF}" "$nw")" \
        "$(pad_to "$side" 7)" \
        "$(pad_to "$proto" 13)" \
        "$(pad_to "$link" 9)" \
        "$(rtt_colour "$rtt")" "$(pad_to "$rtt" 6)" "$C_OFF" \
        "$rate"
}

list_tunnels() {
    local names w=13 n
    names=$(cfg_list)
    if [ -z "$names" ]; then
        dim "no tunnels configured yet - pick New tunnel to make one"
        return 1
    fi
    for n in $names; do
        [ "${#n}" -gt "$w" ] && w=${#n}
    done
    printf '    %s%s %s %s %s %s %s%s\n' "$C_DIM" \
        "$(pad_to NAME "$w")" "$(pad_to SIDE 7)" "$(pad_to PROTO 13)" \
        "$(pad_to LINK 9)" "$(pad_to RTT 6)" "MBIT/S in/out" "$C_OFF"
    # Every row at once, each in its own subshell, and printed in order:
    # a row asks the far end for its round trip, and nine of those one
    # after another is nine round trips before the screen appears.
    local tmp i=0
    tmp=$(mktemp -d) || { for n in $names; do tunnel_row "$n" "$w"; done; return 0; }
    for n in $names; do
        i=$((i + 1))
        tunnel_row "$n" "$w" >"$tmp/$i" 2>&1 &
    done
    wait
    i=0
    for n in $names; do
        i=$((i + 1))
        cat "$tmp/$i"
    done
    rm -rf "$tmp"
    return 0
}

# ---------------------------------------------------------------------------
# manage tunnels
# ---------------------------------------------------------------------------

pick_tunnel() {
    local names i=0 n sel
    names=$(cfg_list)
    [ -n "$names" ] || { dim "no tunnels configured yet"; return 1; }
    blank
    for n in $names; do
        i=$((i + 1))
        item "$i" "$n" "$(svc_state "$n")"
    done
    item 0 "Back"
    blank
    menu_key sel || return 1
    case $sel in '' | 0 | *[!0-9]*) return 1 ;; esac
    PICKED=$(printf '%s\n' $names | sed -n "${sel}p")
    [ -n "$PICKED" ]
}

manage_tunnels() {
    while :; do
        banner
        head2 "Manage tunnels"
        list_tunnels || { pause; return 0; }
        pick_tunnel || return 0
        tunnel_menu "$PICKED"
    done
}
screen_tunnels() { manage_tunnels; }

tunnel_menu() {
    local name=$1 f c side mode
    f=$(cfg_file "$name")
    while :; do
        [ -f "$f" ] || return 0
        side=$(toml_get "$f" tunnel side)
        mode=$(toml_get "$f" tunnel mode)
        banner
        head2 "Tunnel: $name"
        tunnel_status_block "$name"
        rule
        group "Service"
        item 1 "Restart"
        item 2 "Stop"
        item 3 "Start"
        item 4 "Delete this tunnel" "here only - the other server keeps its copy"
        group "Check"
        item 5 "Health check" "what is wrong, and what to do about it"
        item 6 "Live status" "the numbers, once a second"
        item 7 "Live log" "follow the core as it runs"
        group "Settings"
        if [ "$side" = iran ]; then
            item 8 "Ports" "$(ports_of "$name")"
        else
            item 8 "Ports" "IRAN forwards them, not this side"
        fi
        item 9 "Tuning" "profile, queue, mtu, direction, logging"
        item 10 "Scheduled restart"
        blank
        item 0 "Back"
        blank
        menu_key c || return 0
        case $c in
        1) blank; svc_do restart "$name"; sleep 1 ;;
        2) blank; svc_do stop "$name"; sleep 1 ;;
        3) blank; svc_do start "$name"; sleep 1 ;;
        4) delete_tunnel "$name" && return 0 ;;
        5) health_check "$name"; pause ;;
        6) screen_live "$name" ;;
        7) live_log "$name" ;;
        8) if [ "$side" = iran ]; then screen_ports "$name"
           else blank; warn "the port list lives on the IRAN server; this is the KHAREJ end"; pause; fi ;;
        9) tuning_menu "$name" ;;
        10) recycle_menu "$name" ;;
        0 | '') return 0 ;;
        *) blank; warn "there is nothing on $c"; sleep 1 ;;
        esac
    done
}
screen_tunnel() { tunnel_menu "$1"; }

# journald puts its own timestamp, the hostname and unit[pid] in front of
# every line; -o cat prints only what the core wrote. ctrl-c goes to every
# process in the foreground group, so it is caught here and journalctl takes
# the signal, and the menu comes back instead of a shell prompt.
live_log() {
    local name=$1
    banner
    head2 "Live log: $name"
    dim "ctrl-c to stop following"
    blank
    trap ':' INT
    journalctl -u "pingify@$name" -n 60 -f --no-pager -o cat 2>/dev/null || true
    trap - INT
}

show_log() {
    banner
    head2 "Log: $1"
    journalctl -u "pingify@$1" -n 40 --no-pager -o cat 2>/dev/null | sed 's/^/    /' ||
        dim "there is no journal for this tunnel yet"
    pause
}

# ---------------------------------------------------------------------------
# tuning
#
# Every number that shapes a tunnel, on one screen, split by the only
# distinction that matters when two servers disagree: the settings that have
# to match, and the ones that are nobody's business but this machine's.
# ---------------------------------------------------------------------------

# A profile is three lines in the file, not one: the depth and the receive
# queue it chooses are written as numbers, and an explicit number wins over
# the profile in the core, so changing the word alone would change nothing.
_edit_profile() {
    toml_set "$1" tuning profile "$PROFILE_WANT" &&
        toml_set "$1" tuning queue_packets "$(preset_queue "$PROFILE_WANT")" &&
        toml_set "$1" tuning rcvbuf_kb "$(preset_rcvbuf "$PROFILE_WANT")"
}
_edit_queue() { toml_set "$1" tuning queue_packets "$QUEUE_WANT"; }
_edit_mtu() { toml_set "$1" tun mtu "$MTU_WANT"; }
_edit_level() { toml_set "$1" logging level "$LEVEL_WANT"; }
_edit_fec() { toml_set "$1" tuning fec "$FEC_WANT"; }
_edit_dials() { toml_set "$1" transport dials "$DIALS_WANT"; }
_edit_path() { toml_set "$1" transport path "$PATH_WANT"; }
_edit_health_port() { toml_set "$1" status health_port "$HEALTH_WANT"; }
_edit_status_port() { toml_set "$1" status port "$STATUS_WANT"; }
_edit_conns() { toml_set "$1" transport connections "$CONNS_WANT"; }
_edit_keepalive() { toml_set "$1" transport keepalive_sec "$KEEPALIVE_WANT"; }

fec_label() {
    local n
    n=$(toml_get "$1" tuning fec)
    case $n in
    '' | 0) printf 'off' ;;
    *) printf '1 per %s, about %d%% more traffic' "$n" $((100 / n)) ;;
    esac
}

v_fec() {
    case $1 in 0) return 0 ;; '' | *[!0-9]*) echo "a number: 0 turns it off, otherwise 4 to 32"; return 1 ;; esac
    { [ "$1" -ge 4 ] && [ "$1" -le 32 ]; } || { echo "4 to 32, or 0 to turn it off"; return 1; }
}
v_path() { case $1 in /*) return 0 ;; esac; echo "a path starts with a slash"; return 1; }
v_hport() {
    case $1 in -1) return 0 ;; '' | *[!0-9]*) echo "a port, or -1 to turn it off"; return 1 ;; esac
    { [ "$1" -ge 1 ] && [ "$1" -le 65535 ]; } || { echo "a port is between 1 and 65535"; return 1; }
}
v_level() { case $1 in debug | info | warn | error) return 0 ;; esac; echo "debug, info, warn or error"; return 1; }
v_queue() {
    case $1 in '' | *[!0-9]*) echo "a number of packets"; return 1 ;; esac
    { [ "$1" -ge 200 ] && [ "$1" -le 20000 ]; } || { echo "200 to 20000 - below that the queue refuses work the link could carry"; return 1; }
}
v_conns() {
    case $1 in '' | *[!0-9]*) echo "a number of connections"; return 1 ;; esac
    { [ "$1" -ge 1 ] && [ "$1" -le 32 ]; } || { echo "1 to 32"; return 1; }
}
v_keepalive() {
    case $1 in '' | *[!0-9]*) echo "seconds"; return 1 ;; esac
    { [ "$1" -ge 1 ] && [ "$1" -le 300 ]; } || { echo "1 to 300 seconds"; return 1; }
}
v_dials() { case $1 in iran | kharej) return 0 ;; esac; echo "iran or kharej"; return 1; }
v_status_port() {
    local who
    v_port "$1" || return 1
    who=$(status_owner "$1" "${WIZ_KEEP:-}")
    [ -z "$who" ] || { echo "port $1 is already $who's status port"; return 1; }
    return 0
}

tuning_menu() {
    local name=$1 f c v
    f=$(cfg_file "$name")
    while :; do
        cfg_load "$name" || return 1
        WIZ_KEEP=$name
        banner
        head2 "Tuning: $name"
        panel "IDENTITY"
        panel_field "Token" "$(token_print "$T_TOKEN")" "Type" "$(kind_label "$T_TRANSPORT")"
        panel_field "Link" "$(dials_text)"
        panel_end
        blank
        panel "PERFORMANCE - KEEP BOTH SERVERS THE SAME"
        panel_field "Profile" "$T_PRESET" "Queue" "${T_QUEUE:-$(preset_queue "$T_PRESET")} packets"
        if [ "$T_MODE" = tun ]; then
            panel_field "MTU" "$T_TUNMTU" "Parity" "$(fec_label "$f")"
        else
            panel_field "Connections" "$T_CONNS" "Keepalive" "$(toml_get "$f" transport keepalive_sec | sed 's/^$/10/') s"
        fi
        [ -n "$T_PATH" ] && panel_field "Web path" "$T_PATH"
        panel_end
        blank
        panel "LOCAL TO THIS SERVER"
        panel_field "Logging" "$T_LOG" "Status port" "127.0.0.1:$T_STATUS"
        [ "$T_MODE" = tun ] && panel_field "Health port" "$T_HEALTH on $(my_addr "$name")"
        panel_end
        blank
        dim "Read the top box on the other server and make it read the same."
        dim "Every change here restarts the tunnel, which costs a second of traffic."
        rule
        item 1 "Profile" "$T_PRESET - the shape of the queues"
        item 2 "Queue depth" "${T_QUEUE:-from the profile} - set directly only if you measured your path"
        if [ "$T_MODE" = tun ]; then
            item 3 "MTU" "$T_TUNMTU - Find the MTU under Diagnostics measures it"
            case $T_TRANSPORT in
            gre) ;;
            *) item 4 "Parity" "$(fec_label "$f") - repairs a lost packet without a round trip" ;;
            esac
        else
            item 3 "Connections" "$T_CONNS parallel TCP connections, 1 to 32"
            item 4 "Keepalive" "seconds between keepalives on every connection"
        fi
        case $T_TRANSPORT in icmp | gre | awg) ;; *) item 5 "Link direction" "$(dials_text)" ;; esac
        case $T_TRANSPORT in ws | wss) item 6 "Web path" "$T_PATH - must match" ;; esac
        item 7 "Logging" "$T_LOG"
        item 8 "Status port" "127.0.0.1:$T_STATUS - local, where the manager asks"
        [ "$T_MODE" = tun ] && item 9 "Health port" "$T_HEALTH - the same on both, on the link's own address"
        item 10 "Show the config file"
        item 0 "Back"
        blank
        menu_key c || { WIZ_KEEP=; return 0; }
        case $c in
        1) blank; preset_menu && { PROFILE_WANT=$T_PRESET; cfg_apply "$name" _edit_profile yes; }; pause ;;
        2) blank
            dim "This comes from the profile and is the one number a profile moves."
            dim "gaming 600, balanced 900, download 1500."
            ask v "packets" "${T_QUEUE:-$(preset_queue "$T_PRESET")}" v_queue && { QUEUE_WANT=$v; cfg_apply "$name" _edit_queue yes; }
            pause ;;
        3) blank
            if [ "$T_MODE" = tun ]; then
                ask v "mtu" "$T_TUNMTU" v_mtu && { MTU_WANT=$v; cfg_apply "$name" _edit_mtu yes && dim "set the same on the other server"; }
            else
                ask v "parallel connections" "$T_CONNS" v_conns && { CONNS_WANT=$v; cfg_apply "$name" _edit_conns yes; }
            fi
            pause ;;
        4) blank
            if [ "$T_MODE" = tun ]; then
                [ "$T_TRANSPORT" = gre ] && { warn "GRE's payload has to stay a well formed packet, so it never gets parity"; pause; continue; }
                dim "One extra packet per N, made of the N before it. Lose any one of"
                dim "them and this end rebuilds it at once, with no round trip. It costs"
                dim "one packet in N of bandwidth; 10 is a good start on a lossy path."
                ask v "one parity per (0 off, 4 to 32)" "${T_FEC:-0}" v_fec && { FEC_WANT=$v; cfg_apply "$name" _edit_fec yes; }
            else
                ask v "keepalive seconds" "$(toml_get "$f" transport keepalive_sec | sed 's/^$/10/')" v_keepalive && { KEEPALIVE_WANT=$v; cfg_apply "$name" _edit_keepalive yes; }
            fi
            pause ;;
        5) case $T_TRANSPORT in icmp | gre | awg) blank; warn "this transport has no direction to choose"; pause; continue ;; esac
            blank
            dim "direct: IRAN connects out (iran).  reverse: KHAREJ connects in (kharej)."
            dim "Set the same on both servers."
            ask v "which end opens it (iran or kharej)" "$T_DIALS" v_dials && { DIALS_WANT=$v; cfg_apply "$name" _edit_dials yes && dim "now set the same on the other server"; }
            pause ;;
        6) case $T_TRANSPORT in ws | wss) ;; *) blank; warn "only a WebSocket tunnel has a path"; pause; continue ;; esac
            blank
            dim "What the WebSocket handshake asks for; anything else gets a 404."
            ask v "path" "$T_PATH" v_path && { PATH_WANT=$v; cfg_apply "$name" _edit_path yes && dim "set the same on the other server"; }
            pause ;;
        7) blank
            dim "This is local. The two servers may log at different levels."
            ask v "level (error, warn, info, debug)" "$T_LOG" v_level && { LEVEL_WANT=$v; cfg_apply "$name" _edit_level yes; }
            pause ;;
        8) blank
            dim "Bound to 127.0.0.1, so nothing outside this server can reach it."
            dim "One per tunnel, always: two processes cannot bind one port."
            show_taken_status "$name"
            ask v "port" "$T_STATUS" v_status_port && { STATUS_WANT=$v; cfg_apply "$name" _edit_status_port yes; }
            pause ;;
        9) [ "$T_MODE" = tun ] || { blank; warn "a forward tunnel has no private address to answer on"; pause; continue; }
            blank
            dim "The port the other server is asked on, over the private link. Both"
            dim "servers must use the same number; changing it here changes it here."
            ask v "port (-1 turns it off)" "$T_HEALTH" v_hport && { HEALTH_WANT=$v; cfg_apply "$name" _edit_health_port yes; }
            pause ;;
        10) blank; sed 's/^/    /' "$f"; pause ;;
        0 | '') WIZ_KEEP=; return 0 ;;
        *) blank; warn "there is nothing on $c"; sleep 1 ;;
        esac
    done
}

# ---------------------------------------------------------------------------
# scheduled restart
# ---------------------------------------------------------------------------

recycle_menu() {
    local name=$1 hours
    blank
    if systemctl is-enabled --quiet "pingify-recycle@$name.timer" 2>/dev/null; then
        dim "a scheduled restart is currently active"
        if confirm "turn it off?"; then
            systemctl disable --now "pingify-recycle@$name.timer" >/dev/null 2>&1
            rm -f "$UNIT_DIR/pingify-recycle@$name.timer"
            systemctl daemon-reload 2>/dev/null
            ok "scheduled restart removed"
        fi
        pause
        return 0
    fi
    dim "Some Iranian ISPs quietly degrade long-lived connections. A periodic"
    dim "restart costs a second of downtime and clears that up."
    blank
    ask hours "restart every N hours (0 to cancel)" "6" v_number || return 0
    [ "$hours" = 0 ] && return 0
    [ -f "$UNIT_DIR/pingify-recycle@.service" ] || unit_write
    cat >"$UNIT_DIR/pingify-recycle@$name.timer" <<TIMER
[Unit]
Description=Pingify scheduled restart of tunnel $name

[Timer]
OnBootSec=${hours}h
OnUnitActiveSec=${hours}h
RandomizedDelaySec=120
Unit=pingify-recycle@$name.service

[Install]
WantedBy=timers.target
TIMER
    systemctl daemon-reload 2>/dev/null
    systemctl enable --now "pingify-recycle@$name.timer" >/dev/null 2>&1
    ok "the tunnel will restart every ${hours}h"
    pause
}

# ---------------------------------------------------------------------------
# delete
# ---------------------------------------------------------------------------

delete_tunnel() {
    local name=$1 f
    f=$(cfg_file "$name")
    blank
    warn "this removes the tunnel $name from this server"
    dim "the other server keeps its own copy until you remove it there too"
    blank
    confirm "delete $name?" n || return 1

    svc_do stop "$name" 2>/dev/null || true
    systemctl disable "pingify@$name" >/dev/null 2>&1 || true
    systemctl disable --now "pingify-recycle@$name.timer" >/dev/null 2>&1 || true
    rm -f "$UNIT_DIR/pingify-recycle@$name.timer"
    nat_drop "$name" 2>/dev/null || true
    awg_down "$name" 2>/dev/null || true
    [ "$(toml_get "$f" transport type)" = rawtcp ] &&
        rawtcp_unguard "$(toml_get "$f" transport port)" 2>/dev/null
    rm -f "$f" "$f.bak" "$STATE_DIR/$name.forwards" "$STATE_DIR/$name.fail"
    systemctl daemon-reload 2>/dev/null
    ok "$name is gone"
    pause
    return 0
}
#!/usr/bin/env bash
#
# Health: the watchdog that keeps a tunnel up, the check that says what is
# wrong and what to do about it, the live view, and the two measurements
# worth taking when nothing is wrong.
#
# Every failure carries a fix. A report that lists problems and stops leaves
# you exactly where you started. Grey is a verdict: red means "this is
# broken", never "this could not be measured" - an ICMP tunnel switches off
# echo replies on both servers while it runs, so a ping across it is answered
# by nobody, which is the design working and not the link failing.

# ---------------------------------------------------------------------------
# the watchdog
#
# The core already reconnects on its own and systemd restarts a process that
# dies. This is the outer layer: a process that is alive and carrying nothing
# - the far end gone quiet, a path that took the connection and then dropped
# it - is restarted after three strikes, ninety seconds, and the pass is
# logged so the health log says what happened and when.
# ---------------------------------------------------------------------------

HEALTH_STRIKES=3

run_health_check() {
    mkdir -p "$STATE_DIR" 2>/dev/null
    local n f fails mode seen strike
    while IFS= read -r n; do
        [ -n "$n" ] || continue
        systemctl is-enabled --quiet "pingify@$n" 2>/dev/null || continue
        f=$(cfg_file "$n")

        if ! systemctl is-active --quiet "pingify@$n"; then
            echo "pingify: $n is not running, starting it"
            systemctl restart "pingify@$n"
            echo 0 >"$STATE_DIR/$n.fail"
            continue
        fi

        strike=0
        mode=$(toml_get "$f" tunnel mode)
        [ -n "$mode" ] || mode=tun
        if ! tun_stats "$n"; then
            strike=1
        elif [ "${ST_UPTIME:-0}" -lt 60 ]; then
            # Too young to judge: the far end has a minute to show up.
            strike=0
        elif [ "$mode" = forward ]; then
            [ "$ST_UP" = true ] || strike=1
            seen=${ST_FAR_SEEN%%.*}
            case $seen in '' | *[!0-9]*) ;; *) [ "$seen" -gt 45 ] && strike=1 ;; esac
        else
            # The far end, asked across the link. Its answering proves a packet
            # crossed both ways, which no counter on this machine can.
            far_report "$n" >/dev/null 2>&1 || strike=1
        fi

        # Only a tunnel that has heard from the other server is restarted for
        # losing it. One that has never heard from it gains nothing from a
        # restart every ninety seconds - the core keeps trying by itself -
        # and the health log would say nothing but that.
        [ "${ST_INB:-0}" != 0 ] || strike=0
        if [ "$strike" = 0 ]; then
            echo 0 >"$STATE_DIR/$n.fail"
            continue
        fi
        fails=$(cat "$STATE_DIR/$n.fail" 2>/dev/null || echo 0)
        case $fails in '' | *[!0-9]*) fails=0 ;; esac
        fails=$((fails + 1))
        echo "$fails" >"$STATE_DIR/$n.fail"
        echo "pingify: $n cannot reach the other server (strike $fails of $HEALTH_STRIKES)"
        if [ "$fails" -ge "$HEALTH_STRIKES" ]; then
            echo "pingify: restarting $n"
            systemctl restart "pingify@$n"
            echo 0 >"$STATE_DIR/$n.fail"
        fi
    done < <(cfg_list)
}

enable_watchdog() {
    [ -f "$UNIT_DIR/pingify-health.timer" ] || unit_write
    systemctl enable --now pingify-health.timer >/dev/null 2>&1
    [ "${1:-}" = quiet ] || ok "watchdog enabled (checks every 30s)"
}

disable_watchdog() {
    systemctl disable --now pingify-health.timer >/dev/null 2>&1
    ok "watchdog disabled"
}

watchdog_state() {
    if systemctl is-enabled --quiet pingify-health.timer 2>/dev/null; then printf 'on'
    else printf 'off'; fi
}

# ---------------------------------------------------------------------------
# collecting a verdict
#
# health_check buffers its result rather than printing as it goes, so the
# screen and --json are one pass rendered twice.
# ---------------------------------------------------------------------------

CHK_STATE=() CHK_ID=() CHK_TEXT=() CHK_FIX=()
CHK_NBAD=0 CHK_NWARN=0
HC_BAD=0 HC_WARN=0

chk_reset() {
    CHK_STATE=() CHK_ID=() CHK_TEXT=() CHK_FIX=()
    CHK_NBAD=0 CHK_NWARN=0
}

# chk_add STATE ID TEXT [FIX...] - STATE is ok, warn, bad or note. A note is
# grey: something worth saying that is not a fault, and never counted.
chk_add() {
    local state=$1 id=$2 text=$3 joined= one
    shift 3
    for one in "$@"; do joined=$joined$one$'\n'; done
    CHK_STATE+=("$state")
    CHK_ID+=("$id")
    CHK_TEXT+=("$text")
    CHK_FIX+=("$joined")
    case $state in
    bad) CHK_NBAD=$((CHK_NBAD + 1)) ;;
    warn) CHK_NWARN=$((CHK_NWARN + 1)) ;;
    esac
}

hc_ok() { chk_add ok "${2:-x}" "$1"; }
hc_bad() { chk_add bad "${2:-x}" "$1"; }
hc_warn() { chk_add warn "${2:-x}" "$1"; }

count_word() {
    case $1 in 1) printf 'one' ;; 2) printf 'two' ;; 3) printf 'three' ;; *) printf '%s' "$1" ;; esac
}
plural_s() { [ "$1" = 1 ] || printf 's'; }

chk_tally() {
    local out=
    [ "$CHK_NBAD" = 0 ] && [ "$CHK_NWARN" = 0 ] && { printf 'nothing wrong on this server'; return; }
    [ "$CHK_NBAD" -gt 0 ] && out="$(count_word "$CHK_NBAD") problem$(plural_s "$CHK_NBAD")"
    if [ "$CHK_NWARN" -gt 0 ]; then
        [ -n "$out" ] && out="$out, "
        out="$out$(count_word "$CHK_NWARN") warning$(plural_s "$CHK_NWARN")"
    fi
    printf '%s' "$out"
}

chk_render() {
    local name=$1 i line
    head2 "Health check: $name"
    for ((i = 0; i < ${#CHK_ID[@]}; i++)); do
        case ${CHK_STATE[i]} in
        ok) ok "${CHK_TEXT[i]}" ;;
        warn) warn "${CHK_TEXT[i]}" ;;
        bad) fail "${CHK_TEXT[i]}" ;;
        *) dim "  ${CHK_TEXT[i]}" ;;
        esac
        if [ -n "${CHK_FIX[i]}" ]; then
            while IFS= read -r line; do
                [ -n "$line" ] && fix "$line"
            done <<<"${CHK_FIX[i]}"
        fi
    done
    blank
    rule
    if [ "$CHK_NBAD" = 0 ] && [ "$CHK_NWARN" = 0 ]; then
        ok "nothing wrong on this server"
        dim "if the tunnel still misbehaves, run this on the other one too"
    elif [ "$CHK_NBAD" = 0 ]; then
        warn "$(chk_tally) worth looking at"
    else
        fail "$(chk_tally)"
        dim "each one has a fix under it"
    fi
    blank
}

json_esc() {
    local s=$1
    s=${s//\\/\\\\}
    s=${s//\"/\\\"}
    s=${s//$'\t'/ }
    printf '%s' "$s"
}

chk_json() {
    local name=$1 i last first line
    last=$((${#CHK_ID[@]} - 1))
    printf '{\n'
    printf '  "tunnel": "%s",\n' "$(json_esc "$name")"
    printf '  "problems": %s,\n' "$CHK_NBAD"
    printf '  "warnings": %s,\n' "$CHK_NWARN"
    printf '  "checks": [\n'
    for ((i = 0; i <= last; i++)); do
        printf '    {"id": "%s", "state": "%s", "text": "%s", "fixes": [' \
            "$(json_esc "${CHK_ID[i]}")" "${CHK_STATE[i]}" "$(json_esc "${CHK_TEXT[i]}")"
        first=1
        if [ -n "${CHK_FIX[i]}" ]; then
            while IFS= read -r line; do
                [ -n "$line" ] || continue
                [ "$first" = 1 ] || printf ', '
                printf '"%s"' "$(json_esc "$line")"
                first=0
            done <<<"${CHK_FIX[i]}"
        fi
        printf ']}'
        [ "$i" -lt "$last" ] && printf ','
        printf '\n'
    done
    printf '  ]\n}\n'
}

# ---------------------------------------------------------------------------
# reading a tunnel's own idea of itself, once, into CK_*
# ---------------------------------------------------------------------------

chk_load() {
    local name=$1
    CK_FILE=$(cfg_file "$name")
    [ -f "$CK_FILE" ] || return 1
    CK_SIDE=$(toml_get "$CK_FILE" tunnel side)
    CK_TRANSPORT=$(toml_get "$CK_FILE" transport type)
    CK_MODE=$(toml_get "$CK_FILE" tunnel mode)
    [ -n "$CK_MODE" ] || CK_MODE=tun
    CK_PORT=$(toml_get "$CK_FILE" transport port)
    CK_KHAREJ=$(toml_get "$CK_FILE" transport kharej)
    CK_IRAN=$(toml_get "$CK_FILE" transport iran)
    CK_DEV=$(toml_get "$CK_FILE" tun name)
    CK_MTU=$(toml_get "$CK_FILE" tun mtu)
    [ -n "$CK_TRANSPORT" ] || CK_TRANSPORT=udp
    [ -n "$CK_DEV" ] || CK_DEV=pfy0
    [ -n "$CK_MTU" ] || CK_MTU=1320
    if [ "$CK_SIDE" = iran ]; then
        CK_MINE=$(toml_get "$CK_FILE" tun iran)
        CK_THEIRS=$(toml_get "$CK_FILE" tun kharej)
    else
        CK_MINE=$(toml_get "$CK_FILE" tun kharej)
        CK_THEIRS=$(toml_get "$CK_FILE" tun iran)
    fi
    CK_PEER=${CK_THEIRS%%/*}
    CK_DIALS=$(toml_get "$CK_FILE" transport dials)
    [ -n "$CK_DIALS" ] || CK_DIALS=kharej
    if [ "$CK_DIALS" = iran ]; then CK_WAITS=KHAREJ CK_WAIT_ADDR=$CK_KHAREJ
    else CK_WAITS=IRAN CK_WAIT_ADDR=$CK_IRAN; fi
    if [ "$CK_SIDE" = iran ]; then CK_FAR=KHAREJ; else CK_FAR=IRAN; fi
    return 0
}

# link_rtt pings the other end of the private link, bound to the tun device,
# and prints the round trip in milliseconds. Nothing on an ICMP tunnel.
link_rtt() {
    local dev=$1 peer=$2 out
    out=$(ping -n -c1 -W1 -I "$dev" "$peer" 2>/dev/null) || return 1
    case $out in
    *time=*) out=${out#*time=}; printf '%s' "${out%% *}" ;;
    *) return 1 ;;
    esac
}

tcp_reach() {
    local host=$1 port=$2
    if timeout 2 bash -c "exec 3<>/dev/tcp/$host/$port" 2>/dev/null; then return 0; fi
    have nc && nc -z -w2 "$host" "$port" >/dev/null 2>&1
}
tcp_probe() { tcp_reach "$1" "$2"; }

# ---------------------------------------------------------------------------
# health_check NAME [--json] - one pass, in the order things fail. Exit 0
# clean, 1 warnings, 2 problems, so `pingify --check NAME` works from cron.
# ---------------------------------------------------------------------------

health_check() {
    local name=$1 mode=${2:-}
    local core_ver out st since addr fl live_mtu lpm heard cc
    local spec proto lo hi rhost rport total missing unknown

    chk_reset
    if ! chk_load "$name"; then
        chk_add bad config "there is no tunnel called $name" "run pingify with no arguments to see the list"
        chk_finish "$name" "$mode"
        return 2
    fi

    # 1. the core itself
    if [ ! -x "$CORE_BIN" ]; then
        chk_add bad core "the core is not installed at $CORE_BIN" "main menu ${BX_ARR} Update Pingify"
        chk_add note core-rest "nothing below could be checked without it"
        chk_finish "$name" "$mode"
        return 2
    fi
    if core_ver=$(core_version); then
        if [ "$core_ver" = "$PINGIFY_VERSION" ]; then
            chk_add ok core "core and script are both $PINGIFY_VERSION"
        else
            chk_add warn core "core $core_ver against script $PINGIFY_VERSION" \
                "they read the same config file, so a mismatch rejects tunnels" \
                "main menu ${BX_ARR} Update Pingify"
        fi
    else
        chk_add bad core "$CORE_BIN will not run" "it may be built for another architecture" "main menu ${BX_ARR} Update Pingify"
    fi

    # 2. the config, judged by the only judge that counts
    if out=$("$CORE_BIN" -c "$CK_FILE" -check 2>&1); then
        chk_add ok config "the config is valid"
    else
        chk_add bad config "the core rejects it: $(trunc_to "${out%%$'\n'*}" $((UI_W - 26)))" \
            "Manage ${BX_ARR} $name ${BX_ARR} Tuning, or edit $CK_FILE" \
            "the same change is needed on both servers"
    fi

    # 3. the service
    st=$(svc_state "$name")
    case $st in
    active)
        since=$(systemctl show -p ActiveEnterTimestamp --value "pingify@$name" 2>/dev/null)
        chk_add ok service "the service is running since ${since:-a moment ago}"
        ;;
    stopped)
        chk_add bad service "the service is stopped" "systemctl start pingify@$name" "journalctl -u pingify@$name -n 30 --no-pager -o cat"
        ;;
    *)
        chk_add bad service "the service is neither running nor enabled" "systemctl enable --now pingify@$name"
        ;;
    esac

    # 4. the private link, or the port list of a forward tunnel
    if [ "$CK_MODE" = forward ]; then
        local nports
        nports=$(toml_get "$CK_FILE" forward ports | tr ',' '\n' | grep -c '"')
        if [ "$CK_SIDE" = iran ] && [ "${nports:-0}" = 0 ]; then
            chk_add warn ports "no ports are forwarded yet" "Manage ${BX_ARR} $name ${BX_ARR} Ports"
        else
            chk_add ok link "forward tunnel, ${nports:-0} port$(plural_s "${nports:-0}") on IRAN"
        fi
    elif [ ! -d "/sys/class/net/$CK_DEV" ]; then
        if [ "$st" = active ]; then
            chk_add bad link "the private link $CK_DEV does not exist" \
                "the core makes it at start, so it never started" \
                "journalctl -u pingify@$name -n 30 --no-pager -o cat"
        else
            chk_add note link "the private link $CK_DEV is not up, because the service is not running"
        fi
    else
        fl=$(cat "/sys/class/net/$CK_DEV/flags" 2>/dev/null)
        addr=$(ip -4 -o addr show dev "$CK_DEV" 2>/dev/null | awk '{print $4; exit}')
        live_mtu=$(cat "/sys/class/net/$CK_DEV/mtu" 2>/dev/null)
        if [ $((${fl:-0} & 1)) -ne 1 ]; then
            chk_add bad link "$CK_DEV exists but is down" "systemctl restart pingify@$name"
        elif [ -z "$addr" ]; then
            chk_add bad link "$CK_DEV is up but has no address" "systemctl restart pingify@$name"
        elif [ "$addr" != "$CK_MINE" ]; then
            chk_add bad link "$CK_DEV carries $addr, not $CK_MINE" "something else set it; restart the tunnel"
        else
            chk_add ok link "private link $CK_DEV is up, $addr, mtu ${live_mtu:-?}"
        fi
        if [ -n "$live_mtu" ] && [ "$live_mtu" != "$CK_MTU" ]; then
            chk_add warn mtu "device mtu $live_mtu, the config says $CK_MTU" \
                "a hand-set mtu is lost on the next restart" "put the number in the config instead"
        fi
    fi

    # 5. has the far end been heard from
    if [ "$st" = active ] && tun_stats "$name"; then
        heard=$ST_UP
        case $ST_INB in '' | 0) [ "${ST_UPTIME:-0}" -ge 20 ] && heard=false ;; esac
        case $heard in
        true)
            if [ "${ST_INB:-0}" = 0 ]; then
                chk_add note peer "started $(human_secs "$ST_UPTIME") ago; nothing back yet"
            else
                chk_add ok peer "the other server has been heard from - this tunnel has run $(human_secs "$ST_UPTIME")"
            fi
            ;;
        *)
            if [ "$ST_UP" = true ]; then
                chk_add bad dial "the connection was made and then carried nothing" \
                    "some networks take a connection from outside and carry nothing on it" \
                    "switch which end opens it: Manage ${BX_ARR} $name ${BX_ARR} Tuning ${BX_ARR} Link direction, on both servers"
            fi
            case $CK_TRANSPORT in
            icmp)
                chk_add bad peer "the other server has never been seen" \
                    "on $CK_FAR:  systemctl status pingify@$name" \
                    "watch there:  tcpdump -ni any icmp" \
                    "if nothing arrives at all, the route drops ICMP - try TCP UTLS or Raw TCP"
                ;;
            awg)
                chk_add bad peer "the other server has never been seen inside the link" \
                    "the line below says whether the link itself is up" \
                    "if it handshook, the path is dropping udp once it flows" \
                    "on $CK_FAR:  systemctl status pingify@$name"
                ;;
            gre)
                chk_add bad peer "the other server has never been seen" \
                    "on $CK_FAR:  systemctl status pingify@$name" \
                    "watch there:  tcpdump -ni any proto gre" \
                    "some networks drop ip protocol 47 outright; try TCP or ICMP"
                ;;
            tcp | utls | fallback | ws | wss | rawtcp)
                if [ "${CK_SIDE^^}" = "$CK_WAITS" ]; then
                    chk_add bad peer "the other server has never been seen" \
                        "this end is the one that waits, so start with it:  ss -ltn | grep :$CK_PORT" \
                        "open it here:  ufw allow $CK_PORT/tcp" \
                        "on $CK_FAR:  systemctl status pingify@$name"
                elif tcp_reach "$CK_WAIT_ADDR" "$CK_PORT"; then
                    chk_add bad peer "tcp/$CK_PORT is open there, but nothing pingify sent has come back" \
                        "the token differs between the two servers - compare the fingerprints" \
                        "or something else is answering on that port there"
                else
                    chk_add bad peer "the other server has never been seen" \
                        "on $CK_FAR:  systemctl status pingify@$name" \
                        "open it there:  ufw allow $CK_PORT/tcp" \
                        "from here:  nc -zv $CK_WAIT_ADDR $CK_PORT"
                fi
                ;;
            *)
                chk_add bad peer "the other server has never been seen" \
                    "on $CK_FAR:  systemctl status pingify@$name" \
                    "udp/$CK_PORT has to be open on $CK_WAITS:  nc -uzv $CK_WAIT_ADDR $CK_PORT" \
                    "most Iranian lines stop inbound UDP after a few packets; ICMP or Raw TCP is the usual answer"
                ;;
            esac
            ;;
        esac

        if [ "$CK_TRANSPORT" = awg ]; then
            local iface age
            iface=$(awg_iface "$name")
            if [ -z "$iface" ] || ! ip link show "$iface" >/dev/null 2>&1; then
                chk_add bad awg "the AmneziaWG link ${iface:-for this tunnel} is not up" \
                    "systemctl status awg-quick@${iface:-awg0}" "nothing below this can work without it"
            elif age=$(awg_handshake "$iface"); then
                if [ "$age" -lt 180 ]; then
                    chk_add ok awg "AmneziaWG handshook $(human_secs "$age") ago on $iface"
                else
                    chk_add warn awg "the last AmneziaWG handshake was $(human_secs "$age") ago" \
                        "the far end may be down, or the path stopped carrying udp" "awg show $iface"
                fi
            else
                chk_add bad awg "AmneziaWG on $iface has never handshaken" \
                    "the two servers have not agreed on keys" \
                    "open udp/$(toml_get "$CK_FILE" awg port) on both servers" "awg show $iface"
            fi
        fi

        # The far end, asked through the tunnel: the one question whose
        # answer comes from the other server.
        if [ "$heard" = true ] && [ "$CK_MODE" = tun ]; then
            local far fv fp mine_p
            if far=$(far_report "$name") && [ -n "$far" ]; then
                chk_add ok link-end "the other server answers on the private link"
                fv=$(json_field "$far" version)
                if [ -n "$fv" ] && [ -n "$core_ver" ] && [ "$fv" != "$core_ver" ]; then
                    chk_add warn far-version "the other server runs core $fv, this one runs $core_ver" \
                        "presets and wire records move together - update BOTH servers"
                fi
                fp=$(json_field "$far" profile)
                mine_p=$(toml_get "$CK_FILE" tuning profile)
                if [ -n "$fp" ] && [ -n "$mine_p" ] && [ "$fp" != "$mine_p" ]; then
                    chk_add warn far-profile "the other server is on $fp, this one on $mine_p" \
                        "pick one on both: Manage ${BX_ARR} $name ${BX_ARR} Tuning"
                fi
            else
                chk_add warn link-end "the other server does not answer on the private link" \
                    "the carrier is up, so this is the link and not the path" \
                    "on the other server:  pingify --status" \
                    "if packets arrived and then stopped, switch the link direction on both servers"
            fi
        fi
    elif [ "$st" = active ]; then
        if have curl; then
            chk_add bad status "no answer on 127.0.0.1:$(status_port "$name")" \
                "systemctl status pingify@$name" "status.port 0 in the config turns it off"
        else
            chk_add warn status "curl is missing, so nothing could ask it" "apt-get install -y curl"
        fi
    fi

    # 6. loss, as a rate
    if [ "$st" = active ] && [ "${ST_UP:-}" = true ] && [ -n "${ST_UPTIME:-}" ]; then
        lpm=$(awk -v l="${ST_LOST:-0}" -v s="$ST_UPTIME" 'BEGIN { if (s + 0 < 30) print "early"; else printf "%.1f", l * 60 / s }')
        case $lpm in
        early) chk_add note loss "too early to say anything about loss yet" ;;
        *)
            local fec_advice=
            case $CK_TRANSPORT in
            tcp | ws | wss | utls | fallback | gre) ;;
            *) [ "$(toml_get "$CK_FILE" tuning fec)" -gt 0 ] 2>/dev/null ||
                fec_advice="turn on Parity: Manage ${BX_ARR} $name ${BX_ARR} Tuning" ;;
            esac
            if [ "${lpm%%.*}" -ge 60 ]; then
                chk_add bad loss "the path is losing $lpm packets a minute" \
                    "run Find the MTU; a large mtu loses big packets" \
                    ${fec_advice:+"$fec_advice"} "if the mtu is right, the path is congested"
            elif [ "${lpm%%.*}" -ge 5 ]; then
                chk_add warn loss "the path is losing $lpm packets a minute" \
                    "run Find the MTU: a slightly large mtu does this" ${fec_advice:+"$fec_advice"}
            else
                chk_add ok loss "loss is $lpm a minute, ${ST_LATE:-0} arrived late"
            fi
            ;;
        esac
    fi

    # 7. the forwarded ports, and whether anything is behind them. IRAN only.
    if [ "$CK_SIDE" = iran ]; then
        spec=$(ports_of "$name")
        if [ -z "$spec" ]; then
            chk_add warn ports "no ports are forwarded from this server" "Manage ${BX_ARR} $name ${BX_ARR} Ports"
        else
            total=0 missing=0 unknown=0
            if [ "$CK_MODE" = tun ] && have iptables; then
                local rules
                rules=$(iptables -w 2 -t nat -S PINGIFY_NAT 2>/dev/null)
            fi
            while read -r proto lo hi rhost rport; do
                [ -n "$proto" ] || continue
                [ "$rhost" = - ] && rhost=$CK_PEER
                total=$((total + 1))
                if [ "$CK_MODE" = tun ] && have iptables && [ -n "${rules:-}" ] &&
                    ! printf '%s' "$rules" | grep -q -- "--dport $lo"; then
                    chk_add bad "rule-$lo" "no forwarding rule for :$lo in the kernel" \
                        "Manage ${BX_ARR} $name ${BX_ARR} Ports, and set the list again"
                    missing=$((missing + 1))
                    continue
                fi
                if [ "$proto" != tcp ]; then
                    unknown=$((unknown + 1))
                    continue
                fi
                if [ "$CK_MODE" = forward ]; then
                    port_free "$lo" tcp && {
                        chk_add bad "port-$lo" "nothing is listening on :$lo here" "systemctl restart pingify@$name"
                        missing=$((missing + 1))
                    }
                    continue
                fi
                if [ "$st" = active ] && [ "${ST_UP:-}" = true ] && ! tcp_reach "$rhost" "$rport"; then
                    missing=$((missing + 1))
                    chk_add warn "port-$lo" "$lo/tcp goes to $rhost:$rport, nothing there" \
                        "on KHAREJ, listen on $rhost:$rport" "from here:  nc -zv $rhost $rport"
                fi
            done < <(forward_specs "$spec" 2>/dev/null)
            if [ "$total" = 0 ]; then
                chk_add warn ports "the forwarded port list parsed to nothing" "Manage ${BX_ARR} $name ${BX_ARR} Ports, and set them again"
            elif [ "$missing" = 0 ]; then
                if [ "$CK_MODE" = tun ]; then
                    chk_add ok ports "$total forwarded port$(plural_s "$total"), each one has its rule and answers"
                else
                    chk_add ok ports "$total forwarded port$(plural_s "$total"), each one is bound here"
                fi
            fi
            [ "$unknown" -gt 0 ] && chk_add note ports-udp "$unknown are udp and cannot be tested here"
        fi
    fi

    # A stream carrier on a lossy path lives or dies by the congestion
    # control: measured here, bbr carried 348 Mbit/s where cubic carried 31.
    case $CK_TRANSPORT in
    tcp | ws | wss | utls | fallback)
        cc=$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)
        if [ -n "$cc" ] && [ "$cc" != bbr ]; then
            chk_add warn bbr "a tcp tunnel, and this kernel is on $cc" \
                "measured here: bbr carried 348 Mbit/s where cubic carried 31" \
                "main menu ${BX_ARR} Optimize ${BX_ARR} Enable BBR - on both servers"
        fi
        ;;
    esac

    if [ "$(watchdog_state)" != on ]; then
        chk_add warn watchdog "the watchdog is off - a tunnel that goes quiet will not be restarted" \
            "main menu ${BX_ARR} Health ${BX_ARR} Enable the watchdog"
    fi

    if [ "$CK_TRANSPORT" = icmp ]; then
        chk_add note icmp "ping gets no answer across this link by design; the round trip is measured on the health port"
    fi

    chk_finish "$name" "$mode"
    HC_BAD=$CHK_NBAD HC_WARN=$CHK_NWARN
    [ "$CHK_NBAD" -gt 0 ] && return 2
    [ "$CHK_NWARN" -gt 0 ] && return 1
    return 0
}

chk_finish() {
    case ${2:-} in
    json | --json) chk_json "$1" ;;
    *) chk_render "$1" ;;
    esac
}

# ---------------------------------------------------------------------------
# the live views
# ---------------------------------------------------------------------------

live_dashboard() {
    local key
    while :; do
        banner
        head2 "Live status"
        list_tunnels
        rule
        say "  ${C_DIM}watchdog: $(watchdog_state)   $(uptime 2>/dev/null | sed 's/^ *//')${C_OFF}"
        blank
        dim "refreshing every 2s - enter or q to go back"
        # Nobody at a keyboard means one frame, not a loop that redraws for
        # ever into a pipe.
        [ -t 0 ] || return 0
        if read -rsn1 -t 2 key; then
            case $key in q | Q | 0 | "") return ;; esac
        fi
    done
}

LIVE_STOP=0
live_cursor_on() { printf '\033[?25h'; }

# spark_bar is one column of the round-trip history. A reply that never came
# is drawn as the failure glyph, not as a low bar.
spark_bar() {
    local ms=$1 bars i
    case $ms in '' | *[!0-9.]*) printf '%s' "$MK_NO"; return ;; esac
    if [ "$UI_GLYPH" = utf8 ]; then bars='▁▂▃▄▅▆▇█'; else bars='._-=+*#@'; fi
    ms=${ms%%.*}
    if [ "$ms" -lt 60 ]; then i=0
    elif [ "$ms" -lt 80 ]; then i=1
    elif [ "$ms" -lt 100 ]; then i=2
    elif [ "$ms" -lt 130 ]; then i=3
    elif [ "$ms" -lt 170 ]; then i=4
    elif [ "$ms" -lt 220 ]; then i=5
    elif [ "$ms" -lt 300 ]; then i=6
    else i=7; fi
    printf '%s' "${bars:i:1}"
}

# screen_live repaints a fixed block in place about once a second, without
# clearing the screen: the scrollback above is where you look when the
# connection stutters.
screen_live() {
    local name=$1
    local -a lines
    local painted=0 spark= rtt= key rxp txp last_rx= last_tx= din dout w

    chk_load "$name" || { fail "there is no tunnel called $name"; return 1; }
    banner
    head2 "Live status: $name"
    if [ ! -t 0 ] || [ ! -t 1 ]; then
        live_frame "$name" '' ''
        return 0
    fi
    w=$((UI_W - 34))
    [ "$w" -lt 10 ] && w=10
    LIVE_STOP=0
    trap 'LIVE_STOP=1' INT
    trap 'live_cursor_on' EXIT
    printf '\033[?25l'
    while :; do
        rxp=$(cat "/sys/class/net/$CK_DEV/statistics/rx_packets" 2>/dev/null)
        txp=$(cat "/sys/class/net/$CK_DEV/statistics/tx_packets" 2>/dev/null)
        din= dout=
        if [ -n "$last_rx" ] && [ -n "$rxp" ]; then
            din=$((rxp - last_rx))
            dout=$((txp - last_tx))
        fi
        last_rx=$rxp last_tx=$txp
        rtt=
        if [ "$CK_MODE" = tun ] && [ "$CK_TRANSPORT" != icmp ]; then
            rtt=$(link_rtt "$CK_DEV" "$CK_PEER") || rtt=
            spark=$spark$(spark_bar "$rtt")
            [ "${#spark}" -gt "$w" ] && spark=${spark: -w}
        else
            rtt=$(tun_rtt "$name")
        fi
        lines=()
        while IFS= read -r key; do lines+=("$key"); done < <(live_frame "$name" "$spark" "$rtt" "$din" "$dout")
        [ "$painted" -gt 0 ] && printf '\033[%dA' "$painted"
        for key in "${lines[@]}"; do printf '\r\033[K%s\n' "$key"; done
        painted=${#lines[@]}
        [ "$LIVE_STOP" = 1 ] && break
        key=
        read -rsn1 -t 1 key
        [ -n "$key" ] && break
        [ "$LIVE_STOP" = 1 ] && break
    done
    trap - INT
    trap - EXIT
    live_cursor_on
    blank
    return 0
}

live_frame() {
    local name=$1 spark=$2 rtt=$3 din=${4:-} dout=${5:-} state=unknown carrying losses packets
    if tun_stats "$name"; then
        if [ "$ST_UP" = true ] && [ "${ST_INB:-0}" != 0 ]; then state=running; else state=idle; fi
    else
        [ "$(svc_state "$name")" = active ] && state=idle || state=stopped
    fi
    carrying="$(round1 "$ST_IN") Mbit/s in, $(round1 "$ST_OUT") out"
    losses="${ST_LOST:-0} lost, ${ST_LATE:-0} late, ${ST_GAPS:-0} gap$(plural_s "${ST_GAPS:-0}")"
    if [ -n "$din" ]; then packets="$din in, $dout out in the last second"; else packets="counting"; fi
    printf '  %s %s%s%s  %s\n' "$(state_dot "$state")" "$C_B" "$name" "$C_OFF" "$state"
    field "Carrying" "$carrying"
    if [ -n "$rtt" ]; then
        field "Round trip" "$(printf '%s%s ms%s  %s' "$(rtt_colour "$rtt")" "$rtt" "$C_OFF" "$spark")"
    elif [ "$CK_TRANSPORT" = icmp ]; then
        field "Round trip" "${C_DIM}measured on the health port, when the far end answers${C_OFF}"
    else
        field "Round trip" "${C_DIM}no answer${C_OFF}  $spark"
    fi
    field "Losses" "$losses"
    [ "$CK_MODE" = tun ] && field "Packets" "$packets"
    field "Uptime" "$(human_secs "$ST_UPTIME")"
    dim "any key to leave"
}

# ---------------------------------------------------------------------------
# finding the MTU instead of guessing it
#
# A binary search for the largest packet that crosses the private link
# intact. `ping -M do` sets don't-fragment, so a packet too big for the path
# is dropped rather than quietly cut in half. The device's own mtu is the
# ceiling, so this measures whether the configured mtu is honest.
# ---------------------------------------------------------------------------

MTU_WANT=
mtu_editor() { toml_set "$1" tun mtu "$MTU_WANT"; }

mtu_probe() {
    local dev=$1 peer=$2 total=$3
    ping -n -c1 -W2 -M do -s $((total - 28)) -I "$dev" "$peer" >/dev/null 2>&1
}

measure_mtu() {
    local name=$1 lo hi mid best=0 tries=0
    chk_load "$name" || { fail "there is no tunnel called $name"; return 1; }
    banner
    head2 "MTU: $name"
    if [ "$CK_MODE" = forward ]; then
        dim "This tunnel carries ports, not packets - it has no MTU of its own."
        dim "The connections inside it use whatever the two servers negotiate."
        return 0
    fi
    if [ "$CK_TRANSPORT" = icmp ]; then
        dim "This cannot be measured on an ICMP tunnel: the core stops both kernels"
        dim "answering echo while one runs, so a probe is answered by nobody."
        blank
        say "  Use a number instead of a measurement:"
        field "1320" "the default, and right on a 1500 path"
        field "1280" "survives PPPoE, mobile, double tunnels"
        blank
        if [ "$CK_MTU" != 1280 ] && confirm "set the mtu to 1280?" n; then
            MTU_WANT=1280
            cfg_apply "$name" mtu_editor yes && ok "mtu 1280 - set the same number on $CK_FAR"
        fi
        return 0
    fi
    if [ ! -d "/sys/class/net/$CK_DEV" ]; then
        fail "$CK_DEV does not exist, so there is nothing to measure"
        fix "start the tunnel:  systemctl start pingify@$name"
        return 1
    fi
    panel_open "measuring"
    panel_field "Transport" "$(kind_label "$CK_TRANSPORT")" "Set now" "$CK_MTU"
    panel_field "To" "$(addr_tint "$CK_PEER") over $CK_DEV"
    panel_close
    dim "Sends pings that may not be fragmented, one per size. A few seconds."
    blank
    lo=576 hi=$CK_MTU
    while [ "$lo" -le "$hi" ]; do
        mid=$(((lo + hi) / 2))
        tries=$((tries + 1))
        if mtu_probe "$CK_DEV" "$CK_PEER" "$mid"; then
            dim "$(printf '%5s  crosses' "$mid")"
            best=$mid
            lo=$((mid + 1))
        else
            dim "$(printf '%5s  does not' "$mid")"
            hi=$((mid - 1))
        fi
    done
    blank
    if [ "$best" = 0 ]; then
        fail "nothing crossed at any size: not an mtu problem"
        fix "check the tunnel first:  Health check"
        fix "echo may be blocked on the other server; the mtu was left alone"
        return 2
    fi
    if [ "$best" -ge "$CK_MTU" ]; then
        ok "$CK_MTU crosses intact, in $tries probes"
        dim "The device mtu is the ceiling, so more may work."
        return 0
    fi
    warn "the largest that crosses is $best, the config says $CK_MTU"
    dim "the difference is lost as whole packets - what makes a tunnel connect"
    dim "and then stall on anything large"
    blank
    if confirm "set the mtu to $best?" y; then
        MTU_WANT=$best
        cfg_apply "$name" mtu_editor yes && { ok "mtu $best"; dim "set the same on $CK_FAR"; }
    fi
    return 1
}

mtu_menu() {
    pick_tunnel || return 0
    measure_mtu "$PICKED"
    pause
}

# ---------------------------------------------------------------------------
# the speed test
#
# Honest, or nothing. A real test needs a listener at the other end: iperf3
# -s there, sixteen streams from here, six seconds, so the answer compares
# with the table the profiles were measured at.
# ---------------------------------------------------------------------------

IPERF_PORT=5201

iperf_install() {
    have iperf3 && return 0
    blank
    dim "installing iperf3"
    if have apt-get; then
        apt_install iperf3
    elif have dnf; then dnf install -y iperf3 >/dev/null 2>&1
    elif have yum; then yum install -y iperf3 >/dev/null 2>&1
    elif have apk; then apk add --no-cache iperf3 >/dev/null 2>&1
    fi
    have iperf3 && { ok "iperf3 installed"; return 0; }
    fail "iperf3 could not be installed here"
    fix "apt install -y iperf3"
    return 1
}

speed_listen() {
    iperf_install || { pause; return 0; }
    banner
    head2 "Listener"
    dim "iperf3 -s, answering on every address this server has - the tunnel's"
    dim "private address included. Now run the test from the other server."
    dim "ctrl-c when it is finished."
    blank
    trap ':' INT
    iperf3 -s -p "$IPERF_PORT" 2>&1 | sed 's/^/  /'
    trap - INT
    blank
    ok "listener stopped"
    pause
}

speed_test() {
    local name=$1 out rc ref target
    chk_load "$name" || { fail "there is no tunnel called $name"; return 1; }
    banner
    head2 "Speed test: $name"
    if [ "$(svc_state "$name")" != active ]; then
        fail "the tunnel is not running: nothing to push"
        fix "systemctl start pingify@$name"
        return 1
    fi
    if tun_stats "$name" && [ "$ST_UP" != true ]; then
        fail "the other server has not been seen; nothing is there"
        fix "run the Health check first"
        return 1
    fi
    say "  What the link is carrying right now:"
    field "in" "$(round1 "$ST_IN") Mbit/s"
    field "out" "$(round1 "$ST_OUT") Mbit/s"
    blank
    iperf_install || return 1
    if [ "$CK_MODE" = tun ]; then
        target=$CK_PEER
    else
        # A forward tunnel has no private address; the test goes through the
        # first forwarded tcp port, which is what a user gets.
        local spec p
        spec=$(ports_of "$name")
        p=$(forward_specs "$spec" 2>/dev/null | awk '$1 == "tcp" { print $2; exit }')
        if [ "$CK_SIDE" != iran ] || [ -z "$p" ]; then
            fail "a forward tunnel is measured from IRAN, through a forwarded tcp port"
            fix "forward $IPERF_PORT to KHAREJ, run iperf3 -s there, and test from IRAN"
            return 1
        fi
        target=127.0.0.1
        IPERF_PORT=$p
        dim "through forwarded port $p; the listener on KHAREJ must be on what it goes to"
    fi
    dim "This needs a listener there. On $CK_FAR, run:"
    say "       Diagnostics ${BX_ARR} iperf3 ${BX_ARR} Hold the listener     (or: iperf3 -s)"
    blank
    confirm "is it running there?" y || { dim "nothing measured"; return 1; }
    blank
    dim "16 streams for six seconds, matching the numbers the profiles were measured at."
    blank
    out=$(iperf3 -c "$target" -p "$IPERF_PORT" -t 6 -P 16 2>&1)
    rc=$?
    printf '%s\n' "$out" | grep -E 'SUM|error|refused|route' | tail -4 | sed 's/^/       /'
    blank
    if [ "$rc" -ne 0 ]; then
        fail "iperf3 did not finish"
        case $out in
        *"onnection refused"*) fix "nothing on $target:$IPERF_PORT - hold the listener there" ;;
        *"o route to host"* | *"imed out"*) fix "the link is up but nothing crosses it - run the Health check" ;;
        *) fix "read the message above, then run the Health check" ;;
        esac
        return 1
    fi
    case ${ST_PROFILE:-$(toml_get "$CK_FILE" tuning profile)} in
    gaming) ref="gaming measured 397 Mbit/s over 16 streams" ;;
    download) ref="download measured 466 Mbit/s over 16 streams" ;;
    *) ref="balanced measured 448 Mbit/s over 16 streams" ;;
    esac
    ok "done"
    dim "$ref on the reference path, Tehran to Frankfurt."
    dim "A slower path abroad reads lower; that is the path. Take it more than once."
    return 0
}

speed_menu() {
    local c
    while :; do
        banner
        head2 "iperf3"
        dim "Real bandwidth between your two servers. Sixteen parallel streams, six"
        dim "seconds - one stream on a 90 ms path runs out of its own window long"
        dim "before the path runs out of room."
        blank
        item 1 "Hold the listener" "on the other server, first"
        item 2 "Run the test" "on this server, after that"
        item 0 "Back"
        blank
        menu_key c || return 0
        case $c in
        1) speed_listen ;;
        2) pick_tunnel && { speed_test "$PICKED"; pause; } ;;
        0 | '') return 0 ;;
        esac
    done
}

# ---------------------------------------------------------------------------
# the menu
# ---------------------------------------------------------------------------

health_menu() {
    local c n
    while :; do
        banner
        head2 "Health"
        list_tunnels
        rule
        item 1 "Health check" "what is wrong, and what to do about it"
        item 2 "Live status dashboard"
        item 3 "Enable the watchdog" "restarts a tunnel that goes quiet"
        item 4 "Disable the watchdog"
        item 5 "Recent health log"
        item 6 "Restart every tunnel"
        item 0 "Back"
        blank
        menu_key c || return 0
        case $c in
        1) pick_tunnel && { banner; health_check "$PICKED"; pause; } ;;
        2) live_dashboard ;;
        3) blank; enable_watchdog; pause ;;
        4) blank; disable_watchdog; pause ;;
        5) blank; journalctl -u pingify-health.service -n 40 --no-pager -o cat 2>/dev/null | sed 's/^/  /'; pause ;;
        6) blank; for n in $(cfg_list); do svc_do restart "$n"; done; pause ;;
        0 | '') return 0 ;;
        esac
    done
}

# screen_health runs the check over every tunnel; the worst answer is kept.
screen_health() {
    local n rc=0 one any=0
    banner
    for n in $(cfg_list); do
        any=1
        health_check "$n" || { one=$?; [ "$one" -gt "$rc" ] && rc=$one; }
    done
    [ "$any" = 1 ] || warn "there are no tunnels to check yet"
    pause
    return "$rc"
}
#!/usr/bin/env bash
#
# Ports, from the IRAN server to whatever is listening abroad.
#
# The core does not forward anything any more: it carries a private /24 and
# nothing else. This file is the whole of what stands between a user on the
# internet and a panel running on the other server.
#
# The state file is the truth and iptables is a copy of it. Every change
# writes the list under the state directory and then rebuilds the chains from
# every tunnel's list. Nothing edits a live rule in place, so the rules cannot
# end up describing something nobody asked for - which is what happens when a
# tool adds and deletes single rules and one of the deletes quietly fails.
#
# The copy is in memory and nothing survives a reboot, so the premise needs a
# path that makes the copy again at start-up. It has one now: nat_apply_all,
# behind a oneshot unit. Without it the state files and the Ports screen went
# on listing forwarded ports after every reboot and not one of them carried a
# packet, which is the worst shape a fault can take - the machine agreeing
# with you about what it is supposed to be doing.
#
# Two faults of the old script, both named where they are fixed below. A port
# range in iptables is written with a colon, 8000:8010; the old code wrote a
# hyphen and ran it under 2>/dev/null, so every range anyone ever entered was
# accepted, stored, listed back, and never carried a packet. And five places
# parsed the port list, disagreeing about =HOST:PORT. There is one parser
# here, forward_specs, and everything goes through it.
#
# All of this is IRAN-only. KHAREJ is where the panel runs and has no ports to
# take, so the functions check the side rather than trust the caller.
# --------------------------------------------------------------------------

NAT_CHAIN=PINGIFY_NAT
NAT_POST=PINGIFY_SNAT
NAT_SYSCTL=/etc/sysctl.d/99-pingify-forward.conf
NAT_UNIT=pingify-nat.service

# Every iptables call goes through here so the lock wait cannot be forgotten.
# systemd, docker and this script can all want xtables at the same moment, and
# without -w the call fails with "another app is currently holding the xtables
# lock" - in a rebuild loop that is one rule of six missing, and nothing says
# which one.
ipt() { iptables -w 2 "$@"; }

# Keeping the kernel out of a conversation it is not part of.
#
# The raw TCP carrier builds its own segments, so the kernel has no socket for
# the port they arrive on - and its answer to a segment for a port nothing is
# listening on is an RST. That RST tears down the far end's idea of the
# conversation and tells anybody watching that nothing is there, which is the
# opposite of the point.
#
# One rule, in its own chain so it can be found and removed, and the carrier
# will not start without it.
RAWTCP_CHAIN=PINGIFY_RAWTCP

rawtcp_guard() {
    local port=$1
    ipt -t filter -N "$RAWTCP_CHAIN" 2>/dev/null
    ipt -C OUTPUT -j "$RAWTCP_CHAIN" 2>/dev/null ||
        ipt -I OUTPUT 1 -j "$RAWTCP_CHAIN" || return 1
    ipt -C "$RAWTCP_CHAIN" -p tcp --sport "$port" --tcp-flags RST RST -j DROP 2>/dev/null ||
        ipt -A "$RAWTCP_CHAIN" -p tcp --sport "$port" --tcp-flags RST RST -j DROP || return 1
    return 0
}

rawtcp_unguard() {
    local port=$1
    ipt -D "$RAWTCP_CHAIN" -p tcp --sport "$port" --tcp-flags RST RST -j DROP 2>/dev/null
    # The chain goes when the last tunnel using it does.
    if [ "$(ipt -S "$RAWTCP_CHAIN" 2>/dev/null | wc -l)" -le 1 ]; then
        ipt -D OUTPUT -j "$RAWTCP_CHAIN" 2>/dev/null
        ipt -X "$RAWTCP_CHAIN" 2>/dev/null
    fi
    return 0
}

# Rejections are plain, unmarked, and on stderr. Plain because `ask` puts its
# own mark in front of whatever a validator says, and two marks on one line
# read as two problems. On stderr because stdout carries the tuples, and a
# caller capturing those must not capture the complaints with them.
fwd_no() { printf '  %s: %s\n' "$1" "$2" >&2; }

# Where a tunnel's list is kept. This name is the file's own business: another
# part that spells the path out for itself is a second definition, and the
# health check had one - it read "$STATE_DIR/$1.ports", never found a file, and
# reported "no ports are forwarded" about a tunnel forwarding six of them.
# Read the list with forwards_of, or the parsed tuples with forward_specs_for.
fwd_file() { printf '%s/%s.forwards' "$STATE_DIR" "$1"; }

fwd_range() {
    if [ "$1" = "$2" ]; then printf '%s' "$1"; else printf '%s-%s' "$1" "$2"; fi
}

# Do lo1..hi1 and lo2..hi2 share a port.
fwd_overlap() { [ "$1" -le "$4" ] && [ "$3" -le "$2" ]; }

# fwd_tokens splits a list the way somebody writes one: commas, spaces or
# both, in one argument or several. The unquoted expansion here is the only
# one in the file, and the IFS above it is the entire reason for it.
fwd_tokens() {
    local arg tok
    local IFS=$', \t\n'
    for arg in "$@"; do
        for tok in $arg; do printf '%s\n' "$tok"; done
    done
}

fwd_port_ok() {
    case $2 in
    '') fwd_no "$1" "there is no port number in it"; return 1 ;;
    *[!0-9]*) fwd_no "$1" "$2 is not a number, and a port is a number"; return 1 ;;
    esac
    [ "$2" -ge 1 ] && [ "$2" -le 65535 ] && return 0
    fwd_no "$1" "$2 is not a port - they run from 1 to 65535"
    return 1
}

# --------------------------------------------------------------------------
# the one parser
# --------------------------------------------------------------------------
#
#   443                 tcp 443, straight across
#   udp:500             udp instead
#   443=8443            arrives on 443, delivered to 8443
#   8000-8010           a range, delivered on the same ports
#   443=10.99.10.5:443  delivered to a particular machine behind the far end
#
# Prints one tuple per line: "proto lo hi dsthost dstport". dsthost is `-`
# when the token did not name one, meaning the far end of this tunnel: the
# parser is given specs and not a tunnel, so it has nothing to resolve that
# against and does not pretend to. nat_rules_for fills it in.
#
# tcp is the default because udp: exists - if a bare port meant both, nobody
# would ever need to write the prefix.
#
# Nothing is printed unless every token is good. A half applied list is worse
# than none: the ports that did work make the ones that did not look like
# somebody else's fault.
forward_specs() {
    local tok spec dest proto lo hi dsth dstp herr wide dup i refused=0
    local -a out=() sp=() slo=() shi=()

    while read -r tok; do
        [ -n "$tok" ] || continue
        case $tok in
        *=) fwd_no "$tok" "there is nothing after the ="; refused=$((refused + 1)); continue ;;
        esac

        spec=$tok dest= proto=tcp
        case $spec in *=*) dest=${spec#*=}; spec=${spec%%=*} ;; esac
        case $spec in *:*) proto=${spec%%:*}; spec=${spec#*:} ;; esac
        case $proto in
        tcp | TCP) proto=tcp ;;
        udp | UDP) proto=udp ;;
        *) fwd_no "$tok" "iptables forwards tcp and udp; $proto is neither"
           refused=$((refused + 1)); continue ;;
        esac

        case $spec in
        *-*) lo=${spec%%-*}; hi=${spec#*-} ;;
        *) lo=$spec; hi=$spec ;;
        esac
        fwd_port_ok "$tok" "$lo" || { refused=$((refused + 1)); continue; }
        fwd_port_ok "$tok" "$hi" || { refused=$((refused + 1)); continue; }
        if [ "$lo" -gt "$hi" ]; then
            fwd_no "$tok" "the range runs backwards - $lo comes after $hi"
            refused=$((refused + 1)); continue
        fi
        # 512 is not a technical limit. It is the width at which a typo stops
        # looking like a range: 1-9999 is somebody who meant 1999, and opening
        # ten thousand ports on their behalf is not a favour.
        wide=$((hi - lo + 1))
        if [ "$wide" -gt 512 ]; then
            fwd_no "$tok" "that is $wide ports; the most in one range is 512"
            refused=$((refused + 1)); continue
        fi

        dsth=- dstp=$lo
        if [ -n "$dest" ]; then
            case $dest in
            *:*) dsth=${dest%:*}; dstp=${dest##*:} ;;
            *[!0-9]*) dsth=$dest ;;
            *) dstp=$dest ;;
            esac
            # v_host already knows what an address is and already has the
            # wording for what it is not. A second opinion here would in time
            # become a different opinion.
            if [ "$dsth" != - ] && ! herr=$(v_host "$dsth" 2>&1); then
                fwd_no "$tok" "$herr"
                refused=$((refused + 1)); continue
            fi
            fwd_port_ok "$tok" "$dstp" || { refused=$((refused + 1)); continue; }
            if [ "$lo" != "$hi" ] && [ "$dstp" != "$lo" ]; then
                # Kept short on purpose. fwd_no prints with a bare printf and
                # nothing on this path truncates, so a sentence of advice here
                # wrapped past a hundred columns on a sixty column terminal.
                fwd_no "$tok" "a range cannot go to one port"
                refused=$((refused + 1)); continue
            fi
        fi

        # The same port twice is a list somebody is still editing. Better said
        # here than left as two iptables rules, the second of which is dead
        # weight nobody can see.
        dup=0
        for ((i = 0; i < ${#sp[@]}; i++)); do
            [ "${sp[i]}" = "$proto" ] || continue
            fwd_overlap "$lo" "$hi" "${slo[i]}" "${shi[i]}" || continue
            fwd_no "$tok" "this list already has $proto $(fwd_range "${slo[i]}" "${shi[i]}") in it"
            refused=$((refused + 1)) dup=1
            break
        done
        [ "$dup" = 1 ] && continue

        sp+=("$proto") slo+=("$lo") shi+=("$hi")
        out+=("$proto $lo $hi $dsth $dstp")
    done < <(fwd_tokens "$@")

    [ "$refused" -gt 0 ] && return 1
    [ "${#out[@]}" -gt 0 ] && printf '%s\n' "${out[@]}"
    return 0
}

# --------------------------------------------------------------------------
# what a tunnel forwards, and what would collide with it
# --------------------------------------------------------------------------

# The state file holds the tokens as they were typed, one per line, not the
# parsed tuples: that is what the ports screen shows back, and what somebody
# reading /var/lib/pingify by hand expects to find.
forwards_of() {
    local f
    f=$(fwd_file "$1")
    [ -f "$f" ] || return 0
    cat "$f"
}

forwards_set() {
    local name=$1 f
    shift
    forward_specs "$@" >/dev/null || return 1
    ensure_dirs
    f=$(fwd_file "$name")
    fwd_tokens "$@" >"$f" || return 1
    chmod 0600 "$f"
}

peer_tun_addr() {
    local f a
    f=$(cfg_file "$1")
    [ -f "$f" ] || return 0
    a=$(toml_get "$f" tun kharej)
    printf '%s' "${a%%/*}"
}

# tun_dev_of prints nothing once the config has gone rather than guessing
# pfy0. The guess would be used to delete a firewall rule, and deleting one
# that belongs to another tunnel is worse than leaving one behind.
tun_dev_of() {
    local f d
    f=$(cfg_file "$1")
    [ -f "$f" ] || return 0
    d=$(toml_get "$f" tun name)
    printf '%s' "${d:-pfy0}"
}

# forward_specs_for is the parser bound to a tunnel: the same tuples, with the
# `-` in the dsthost column already replaced by that tunnel's far end.
#
# It exists because the placeholder was escaping. forward_specs is handed
# specs and not a tunnel, so it cannot resolve `-` itself and does not pretend
# to; the health check took the tuples straight from it and probed the literal
# host `-`, which cannot answer, so every plain `443` forward was reported as
# a dead backend. Anything outside this file that wants a tunnel's tuples
# wants these, and it should ask for them by tunnel name rather than spell out
# where the state file lives.
forward_specs_for() {
    local name=$1 peer tuples proto lo hi dsth dstp
    tuples=$(forward_specs "$(forwards_of "$name")") || return 1
    [ -n "$tuples" ] || return 0
    peer=$(peer_tun_addr "$name")
    while read -r proto lo hi dsth dstp; do
        [ -n "$proto" ] || continue
        if [ "$dsth" = - ]; then
            # No address for the far end and a token that needs one. Printing
            # the tuple anyway would hand an empty host to whatever consumes
            # it, and an empty host in a DNAT target is a rule iptables takes.
            [ -n "$peer" ] || return 1
            dsth=$peer
        fi
        printf '%s %s %s %s %s\n' "$proto" "$lo" "$hi" "$dsth" "$dstp"
    done <<<"$tuples"
}

# fwd_listeners prints "proto port who" for everything bound on this host.
#
# Loopback-only listeners are left out on purpose: PREROUTING takes the packet
# long before it reaches 127.0.0.1, so such a service never saw the outside
# traffic and calling it a clash is a false alarm - and false alarms are how
# people learn to ignore a collision check.
#
# The whole of 127.0.0.0/8 is loopback, not the one address. Matching only
# 127.0.0.1 meant systemd-resolved on 127.0.0.53:53 was reported as a clash on
# every Ubuntu host, which is precisely the false alarm this filter exists to
# prevent.
fwd_listeners() {
    have ss || return 0
    ss -lntup 2>/dev/null | awk '
        NR > 1 {
            addr = $5
            n = split(addr, p, ":")
            port = p[n]
            host = substr(addr, 1, length(addr) - length(port) - 1)
            if (host ~ /^127\./ || host == "[::1]") next
            who = "something"
            i = index($0, "users:((\"")
            if (i > 0) {
                rest = substr($0, i + 9)
                q = index(rest, "\"")
                if (q > 1) who = substr(rest, 1, q - 1)
            }
            print $1, port, who
        }'
}

# forwards_clash prints every clash it can find, one per line, and returns
# non-zero when there was one. Every clash, not the first: somebody given one
# reason at a time will fix it, be handed a new one, and reasonably decide the
# tool is playing with them.
#
# Two sources. Another tunnel's forwards, this tunnel's own excluded so that
# re-submitting an unchanged list is not a clash with itself. And whatever is
# bound here per ss, because a DNAT in PREROUTING takes the packet before the
# local service sees it, which looks from that service exactly like the port
# going dead for no reason.
forwards_clash() {
    local name=$1
    shift
    local tuples listeners proto lo hi dsth dstp other op olo ohi oport who
    local hits=0

    tuples=$(forward_specs "$@") || return 1
    [ -n "$tuples" ] || return 0
    listeners=$(fwd_listeners)

    # A tunnel whose stored list no longer parses contributes no tuples, and
    # the parse ran under 2>/dev/null inside a process substitution, so both
    # its complaint and its exit status went into the dark. The port it is
    # holding was then handed out as free. Said once per tunnel, here, rather
    # than once per port being checked.
    while read -r other; do
        [ -n "$other" ] || continue
        [ "$other" = "$name" ] && continue
        forward_specs "$(forwards_of "$other")" >/dev/null 2>&1 && continue
        printf '%s: its list cannot be read\n' "$other"
        hits=$((hits + 1))
    done < <(cfg_list)

    while read -r proto lo hi dsth dstp; do
        [ -n "$proto" ] || continue
        while read -r other; do
            [ -n "$other" ] || continue
            [ "$other" = "$name" ] && continue
            while read -r op olo ohi _ _; do
                [ -n "$op" ] || continue
                [ "$op" = "$proto" ] || continue
                fwd_overlap "$lo" "$hi" "$olo" "$ohi" || continue
                printf '%s %s is already forwarded by the tunnel %s\n' \
                    "$op" "$(fwd_range "$olo" "$ohi")" "$other"
                hits=$((hits + 1))
            done < <(forward_specs "$(forwards_of "$other")" 2>/dev/null)
        done < <(cfg_list)
        while read -r op oport who; do
            [ -n "$op" ] || continue
            [ "$op" = "$proto" ] || continue
            fwd_overlap "$lo" "$hi" "$oport" "$oport" || continue
            printf '%s %s is already open here, held by %s\n' "$op" "$oport" "$who"
            hits=$((hits + 1))
        done <<<"$listeners"
    done <<<"$tuples"

    [ "$hits" = 0 ]
}

# The reasons are joined onto one line because `ask` prints a validator's
# answer as one line. The full list, one per line, is what forward_specs
# prints when the screen calls it directly.
v_forwards() {
    local err
    # Empty is a legal answer. It is how somebody says "none of them".
    [ -z "$1" ] && return 0
    if err=$(forward_specs "$1" 2>&1 >/dev/null); then return 0; fi
    printf '%s' "$err" | tr '\n' ';'
    return 1
}

# --------------------------------------------------------------------------
# turning the state into iptables
# --------------------------------------------------------------------------
#
# Two chains, and not for tidiness. DNAT is only valid on the PREROUTING hook
# and MASQUERADE only on POSTROUTING, and the kernel works out which hooks a
# user chain is reachable from when the jump is added - so one chain hooked
# into both is refused outright, and one chain hooked into either cannot hold
# the other's rule.

nat_hook() {
    local chain=$1 target=$2
    ipt -t nat -C "$chain" -j "$target" 2>/dev/null && return 0
    ipt -t nat -I "$chain" 1 -j "$target"
}

# The FORWARD accepts are two plain rules rather than a chain of our own: the
# host part owns Pingify's filter chains, and two owners flushing one chain is
# how each loses the other's work. They matter, because on any machine that
# has run docker the FORWARD policy is DROP, and without them the DNAT
# succeeds and the packet dies one hop later - indistinguishable, from the
# outside, from the far end being down.
nat_forward_hook() {
    local how=$1 dev=$2
    # shellcheck disable=SC2054
    local -a back=(-i "$dev" -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT)
    [ -n "$dev" ] || return 0
    case $how in
    add)
        ipt -C FORWARD -o "$dev" -j ACCEPT 2>/dev/null ||
            ipt -I FORWARD 1 -o "$dev" -j ACCEPT || return 1
        # Only replies come back the other way. The far end is not a route to
        # the rest of the internet through this server.
        ipt -C FORWARD "${back[@]}" 2>/dev/null ||
            ipt -I FORWARD 1 "${back[@]}" || return 1
        ;;
    del)
        while ipt -C FORWARD -o "$dev" -j ACCEPT 2>/dev/null; do
            ipt -D FORWARD -o "$dev" -j ACCEPT || break
        done
        while ipt -C FORWARD "${back[@]}" 2>/dev/null; do
            ipt -D FORWARD "${back[@]}" || break
        done
        ;;
    esac
}

# An owned drop-in, so that removing Pingify removes Pingify's change to this
# machine and nobody else's.
nat_ip_forward() {
    local now
    mkdir -p /etc/sysctl.d 2>/dev/null
    if [ ! -s "$NAT_SYSCTL" ]; then
        cat >"$NAT_SYSCTL" <<'SYSCTL'
# Written by Pingify. A forwarded port is a packet that arrives for one
# address and leaves for another, and the kernel drops that unless this is on.
net.ipv4.ip_forward = 1
SYSCTL
    fi
    sysctl -q -w net.ipv4.ip_forward=1 >/dev/null 2>&1 ||
        printf '1\n' >/proc/sys/net/ipv4/ip_forward 2>/dev/null
    now=$(cat /proc/sys/net/ipv4/ip_forward 2>/dev/null)
    [ "$now" = 1 ] && return 0
    bad "the kernel is not forwarding packets, so nothing arrives"
    fix "sysctl -w net.ipv4.ip_forward=1"
    return 1
}

# nat_rules_for appends one tunnel's rules to the already flushed chains. A
# tunnel whose stored list no longer parses is skipped with a complaint rather
# than aborting the rebuild: the rebuild is doing the other tunnels' work too,
# and one bad state file must not take their ports down with it.
nat_rules_for() {
    local name=$1 f side dev tuples proto lo hi dsth dstp dport target
    f=$(cfg_file "$name")
    [ -f "$f" ] || return 0
    side=$(toml_get "$f" tunnel side)
    [ "$side" = iran ] || return 0

    # forward_specs_for resolves the `-` placeholder against this tunnel, so
    # it also fails when a token needs the far end and the config names none.
    tuples=$(forward_specs_for "$name") || return 1
    [ -n "$tuples" ] || return 0
    dev=$(tun_dev_of "$name")
    [ -n "$dev" ] || return 1

    while read -r proto lo hi dsth dstp; do
        [ -n "$proto" ] || continue
        if [ "$lo" = "$hi" ]; then
            dport=$lo target=$dsth:$dstp
        else
            # The colon. iptables writes a range as 8000:8010 and refuses a
            # hyphen; the old script wrote the hyphen and threw the refusal
            # away, so ranges were stored, listed back, and never forwarded.
            # A range keeps its own ports, so the target names none.
            dport=$lo:$hi target=$dsth
        fi
        # Not packets arriving out of the tunnel: without this, a connection
        # made from the far end to this port is sent straight back out again.
        ipt -t nat -A "$NAT_CHAIN" ! -i "$dev" -p "$proto" --dport "$dport" \
            -j DNAT --to-destination "$target" || return 1
    done <<<"$tuples"

    # One MASQUERADE for the device, so the far end sees the traffic coming
    # from this end of the private link and answers back down it. Without it
    # the reply is addressed to the original client and leaves through the far
    # server's own default route, where it is dropped as a stranger.
    ipt -t nat -A "$NAT_POST" -o "$dev" -j MASQUERADE || return 1
    nat_forward_hook add "$dev"
}

# nat_rebuild writes every tunnel's stored list into the freshly flushed
# chains. Everything, because the chains are shared: flushing them to write one
# tunnel's rules and not writing the others back is how a second tunnel
# silently loses its ports.
#
# The argument is the tunnel the caller is about to report on, or empty to mean
# every tunnel matters. It returns non-zero when that tunnel's rules did not go
# in. This used to be inside nat_apply, which threw the result away: a DNAT the
# kernel refused, or a config with no device or no far end, was warned about
# and then reported as a success on the very next line, with a count read from
# the state file rather than from what iptables had accepted.
nat_rebuild() {
    local want=$1 t dev rc=0
    have iptables || {
        warn "iptables is not installed, so nothing can be forwarded"
        fix "apt-get install -y iptables"
        return 1
    }
    ensure_dirs
    nat_ip_forward || return 1

    ipt -t nat -n -L "$NAT_CHAIN" >/dev/null 2>&1 || ipt -t nat -N "$NAT_CHAIN" || return 1
    ipt -t nat -n -L "$NAT_POST" >/dev/null 2>&1 || ipt -t nat -N "$NAT_POST" || return 1
    ipt -t nat -F "$NAT_CHAIN" || return 1
    ipt -t nat -F "$NAT_POST" || return 1
    nat_hook PREROUTING "$NAT_CHAIN" || return 1
    nat_hook POSTROUTING "$NAT_POST" || return 1

    while read -r t; do
        [ -n "$t" ] || continue
        # A tunnel that has stopped forwarding kept its FORWARD accepts:
        # nat_rules_for returns before it adds them and nothing ever took them
        # away again, so `-o pfy0 -j ACCEPT` sat there permitting that device
        # with no DNAT left behind it. The nat chains are flushed above; these
        # two rules live in filter and have to be removed by name.
        if [ -z "$(forwards_of "$t")" ]; then
            dev=$(tun_dev_of "$t")
            nat_forward_hook del "$dev"
            continue
        fi
        nat_rules_for "$t" && continue
        warn "$t: its stored ports could not be applied"
        if [ -z "$want" ] || [ "$t" = "$want" ]; then rc=1; fi
    done < <(cfg_list)
    return "$rc"
}

# nat_apply rebuilds everything, then reports on the one tunnel it was called
# for. The report is the outcome, not a wish: it is only printed when the
# rebuild said that tunnel's rules went in.
nat_apply() {
    local name=$1 n peer word
    nat_rebuild "$name" || {
        bad "$name: its ports are not forwarded"
        fix "read the warnings above, then set the list again"
        return 1
    }
    nat_unit_write || {
        warn "the boot unit is not written, so a reboot loses these"
        fix "check that $UNIT_DIR can be written"
    }

    n=$(forwards_of "$name" | grep -c .) || n=0
    peer=$(peer_tun_addr "$name")
    word=ports
    [ "$n" = 1 ] && word=port
    if [ "$n" = 0 ]; then
        ok "$name forwards nothing now"
    elif [ -n "$peer" ]; then
        ok "$name sends $n $word to $peer"
    else
        # Every token named its own destination, so there is no far end to
        # name here. The old line ended "to " with nothing after it.
        ok "$name sends $n $word across the tunnel"
    fi
    return 0
}

# nat_apply_all is the boot path, and the reason the unit below exists.
#
# iptables keeps its rules in memory alone. Nothing replayed them at start-up,
# so every forwarded port died at the first reboot while the state files and
# the Ports screen went on saying the ports were forwarded - the one failure
# with no symptom anywhere on the machine except that no packet arrives.
nat_apply_all() {
    [ "$(cfg_count)" -gt 0 ] || return 0
    nat_rebuild "" || return 1
    ok "the forwarded ports are back in the kernel"
}

# The unit re-enters this same script rather than repeating the rules, so the
# boot path cannot drift from the interactive one. It sources the manager with
# PINGIFY_NO_MAIN set, which is what stops a sourced copy opening the menu, and
# calls the one function - there is no command line flag for this and adding
# one would put a second entry point on the same work.
nat_unit_write() {
    mkdir -p "$UNIT_DIR" 2>/dev/null
    # The write is checked. A unit that was never written is the reboot fault
    # again, and it would be reported under the same green tick as before.
    cat >"$UNIT_DIR/$NAT_UNIT" <<UNIT || return 1
[Unit]
Description=Pingify forwarded ports
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/bin/bash -c 'PINGIFY_NO_MAIN=1 . $PINGIFY_BIN && nat_apply_all'

[Install]
WantedBy=multi-user.target
UNIT
    systemctl daemon-reload >/dev/null 2>&1 || true
    systemctl enable "$NAT_UNIT" >/dev/null 2>&1 || true
}

# nat_drop removes one tunnel's forwarding. Call it before the config file is
# deleted: the tun device name comes out of the config, and without it the
# FORWARD rules for that device can never be found again.
nat_drop() {
    local name=$1 dev t left=0
    rm -f "$(fwd_file "$name")"
    # The state file has gone either way, so say so. Returning in silence here
    # left the menu item printing nothing at all after the confirmation, which
    # reads as a key that did not work.
    have iptables || { ok "$name forwards nothing now"; return 0; }
    dev=$(tun_dev_of "$name")
    nat_forward_hook del "$dev"

    while read -r t; do
        [ -n "$t" ] || continue
        [ -s "$(fwd_file "$t")" ] && left=1
    done < <(cfg_list)

    if [ "$left" = 1 ]; then
        nat_apply "$name"
        return
    fi
    nat_teardown
    ok "$name forwards nothing, and the chains have gone with it"
}

# nat_teardown is what the last tunnel and the uninstall both call. The loops
# around the unhooking are there because an older version inserted the jump on
# every run: a single -D would leave the duplicates pointing at a chain that
# is about to be deleted.
nat_teardown() {
    # The boot unit goes first and always, iptables or not: a unit left behind
    # would replay chains at the next reboot that nothing on this machine now
    # asks for.
    systemctl disable --now "$NAT_UNIT" >/dev/null 2>&1 || true
    rm -f "$UNIT_DIR/$NAT_UNIT"
    systemctl daemon-reload >/dev/null 2>&1 || true

    have iptables || return 0
    while ipt -t nat -C PREROUTING -j "$NAT_CHAIN" 2>/dev/null; do
        ipt -t nat -D PREROUTING -j "$NAT_CHAIN" || break
    done
    while ipt -t nat -C POSTROUTING -j "$NAT_POST" 2>/dev/null; do
        ipt -t nat -D POSTROUTING -j "$NAT_POST" || break
    done
    ipt -t nat -F "$NAT_CHAIN" 2>/dev/null
    ipt -t nat -X "$NAT_CHAIN" 2>/dev/null
    ipt -t nat -F "$NAT_POST" 2>/dev/null
    ipt -t nat -X "$NAT_POST" 2>/dev/null
    # The drop-in goes, so a reboot comes up without it. The running kernel
    # keeps ip_forward=1 until then, deliberately: something else here may be
    # relying on it and it was not ours to switch off.
    rm -f "$NAT_SYSCTL"
    return 0
}

# --------------------------------------------------------------------------
# the screen
# --------------------------------------------------------------------------

screen_ports() {
    local name=$1 f side peer cur tuples proto lo hi dsth dstp key
    f=$(cfg_file "$name")
    [ -f "$f" ] || { bad "there is no tunnel called $name"; return 1; }
    screen_top

    while :; do
        side=$(toml_get "$f" tunnel side)
        blank
        rule "Ports $G_CUR $name"
        blank
        if [ "$side" != iran ]; then
            warn "this is the KHAREJ side; nothing is forwarded here"
            fix "run this on the IRAN server, where users connect"
            blank
            return 0
        fi

        peer=$(peer_tun_addr "$name")
        # Short because dim prints with a bare printf: the sentence this
        # replaces came to 72 columns against a 60 column floor and wrapped.
        if [ "$(toml_get "$f" tunnel mode)" = forward ]; then
            dim "users connect here; each port goes to the service it names on KHAREJ"
        else
            dim "these ports go to $peer across the tunnel"
        fi
        blank
        cur=$(forwards_of "$name" | tr '\n' ' ')
        cur=${cur% }
        if [ -z "$cur" ]; then
            dim "nothing is forwarded yet"
        elif ! tuples=$(forward_specs "$cur"); then
            warn "the stored list cannot be read, so nothing is forwarded"
            fix "choose 1 and enter the ports again"
        else
            UI_COLS=(14 7 30)
            row "PORT" "PROTO" "GOES TO"
            while read -r proto lo hi dsth dstp; do
                [ -n "$proto" ] || continue
                [ "$dsth" = - ] && dsth=$peer
                if [ "$lo" = "$hi" ]; then
                    row "$lo" "$proto" "$dsth:$dstp"
                else
                    row "$lo-$hi" "$proto" "$dsth, the same ports"
                fi
            done <<<"$tuples"
        fi

        blank
        item "1" "Set the list"
        item "2" "Forward nothing"
        item "0" "Back"
        blank
        menu_key key || return 0
        case $key in
        1) screen_ports_set "$name" ;;
        2) confirm "stop forwarding every port for $name?" n && nat_drop "$name" ;;
        0 | '') return 0 ;;
        esac
    done
}

screen_ports_set() {
    local name=$1 cur answer clashes
    cur=$(forwards_of "$name" | tr '\n' ' ')
    cur=${cur% }
    blank
    dim "one port  443     a range  8000-8010     udp  udp:500"
    dim "somewhere else  443=8443  or  443=10.99.10.5:443"
    blank
    # The clash report is a re-ask, not a refusal: the answer is still on the
    # screen above and the next one is usually one character different.
    while :; do
        ask answer "ports, comma separated" "$cur" v_forwards || return 0
        clashes=$(forwards_clash "$name" "$answer") && break
        blank
        bad "something else already has one of those:"
        printf '%s\n' "$clashes" | sed 's/^/       /'
        fix "pick other ports, or stop what is holding these"
        blank
    done
    forwards_set "$name" "$answer" || return 1
    # A forward tunnel carries its ports itself: the list goes into the file
    # both servers share and the core binds them. A [TUN] tunnel forwards
    # them over its link with NAT, as it always has.
    if [ "$(toml_get "$(cfg_file "$name")" tunnel mode)" = forward ]; then
        fwd_apply_forward "$name"
    else
        nat_apply "$name"
    fi
}

# fwd_apply_forward writes the stored list into [forward] ports and restarts
# the tunnel, which is how the core learns it. The other server gets the same
# list the next time the file is shared, and does not need it to work: only
# IRAN binds anything.
fwd_apply_forward() {
    local name=$1 f list t first=1
    f=$(cfg_file "$name")
    for t in $(forwards_of "$name"); do
        [ "$first" = 1 ] || list="$list, "
        list="$list\"$t\""
        first=0
    done
    grep -q '^\[forward\]' "$f" || printf '\n[forward]\n' >>"$f"
    toml_set "$f" forward ports "[$list]" no || {
        bad "could not write the port list into $f"
        return 1
    }
    svc_do restart "$name"
}
#!/usr/bin/env bash
#
# Update, remove, and the diagnostics screen: one command that answers "is
# this thing working, and if not, which part is broken" - in the order the
# failures actually happen, so the first red line is the one to fix.

RAW_BASE="https://raw.githubusercontent.com/${PINGIFY_REPO}/main"

restart_all() {
    local n any=0
    for n in $(cfg_list); do any=1; svc_do restart "$n"; done
    [ "$any" = 1 ] && ok "${1:-done}; every tunnel was restarted" || ok "${1:-done}"
}

# ---------------------------------------------------------------------------
# update
#
# The script and the core share a config format, so they move together. The
# new script is fetched, checked to be a script of ours, installed, and then
# handed the rest: it rebuilds its own core and restarts every tunnel.
# ---------------------------------------------------------------------------

update_pingify() {
    local tmp rc=1 url newver
    banner
    head2 "Update Pingify"
    have curl || have wget || {
        fail "neither curl nor wget is here, so there is nothing to fetch with"
        fix "apt install curl"
        pause; return 1
    }
    tmp=$(mktemp) || return 1
    for url in \
        "https://github.com/$PINGIFY_REPO/releases/latest/download/Pingify.sh" \
        "$RAW_BASE/Pingify.sh"; do
        dim "trying $url"
        if fetch "$url" "$tmp" 60; then rc=0; break; fi
    done
    if [ "$rc" != 0 ]; then
        rm -f "$tmp"
        fail "nothing could be fetched from either place"
        dim "on an Iranian server this often fails; fetch it on the Kharej box and copy it across"
        pause; return 1
    fi
    if ! head -1 "$tmp" | grep -q '^#!.*bash'; then
        rm -f "$tmp"
        fail "what came back is not a shell script - something on the way answered instead"
        pause; return 1
    fi
    if ! bash -n "$tmp" 2>/dev/null; then
        rm -f "$tmp"
        fail "what came back does not parse, so it arrived incomplete"
        fix "try again - a truncated script is worse than an old one"
        pause; return 1
    fi
    newver=$(grep -m1 '^PINGIFY_VERSION=' "$tmp" | cut -d'"' -f2)
    if [ -z "$newver" ]; then
        rm -f "$tmp"
        fail "that script would not tell us its version, so it is not one of ours"
        pause; return 1
    fi
    if [ "$newver" = "$PINGIFY_VERSION" ] && core_matches_script; then
        rm -f "$tmp"
        ok "already on $PINGIFY_VERSION - nothing to do"
        pause; return 0
    fi
    blank
    panel_open "VERSIONS"
    panel_field "installed" "$PINGIFY_VERSION" "core" "$(core_version 2>/dev/null || printf 'none')"
    panel_field "available" "$newver"
    panel_close
    dim "the core is rebuilt to match, and every running tunnel is restarted"
    blank
    if ver_ge "$newver" "$PINGIFY_VERSION"; then
        confirm "update to $newver?" y || { rm -f "$tmp"; return 1; }
    else
        warn "$newver is older than the $PINGIFY_VERSION on this server"
        confirm "go back to $newver?" n || { rm -f "$tmp"; return 1; }
    fi
    install -m 0755 "$tmp" "$PINGIFY_BIN" || { rm -f "$tmp"; fail "could not write $PINGIFY_BIN"; pause; return 1; }
    rm -f "$tmp"
    ok "the manager is now $newver"
    blank
    info "handing over to the new script to build its core"
    sleep 1
    exec "$PINGIFY_BIN" --rebuild-core
}

# rebuild_core is what the new script does when the old one hands over.
rebuild_core() {
    local n
    unit_write
    if ensure_core; then
        while IFS= read -r n; do
            systemctl is-enabled --quiet "pingify@$n" 2>/dev/null && svc_do restart "$n"
        done < <(cfg_list)
        ok "everything is on $PINGIFY_VERSION"
        return 0
    fi
    fail "the manager was updated but its core could not be built"
    fix "run pingify and choose Update Pingify once the reason is fixed"
    return 1
}

# ---------------------------------------------------------------------------
# remove
# ---------------------------------------------------------------------------

remove_menu() {
    local c n
    banner
    head2 "Remove"
    item 1 "Remove the core only" "tunnels and configs stay"
    item 2 "Remove every tunnel" "configs and services, core stays"
    item 3 "Full uninstall" "every tunnel, unit, rule and file it wrote"
    item 0 "Back"
    blank
    menu_key c || return 0
    case $c in
    1) blank
        confirm "remove $CORE_BIN?" || return 0
        for n in $(cfg_list); do systemctl stop "pingify@$n" >/dev/null 2>&1; done
        rm -f "$CORE_BIN"
        rm -rf "$SRC_DIR"
        ok "core removed; the next run builds it again"
        pause ;;
    2) blank
        confirm "delete every tunnel on this server?" || return 0
        for n in $(cfg_list); do
            svc_do stop "$n" >/dev/null 2>&1
            systemctl disable "pingify@$n" >/dev/null 2>&1
            systemctl disable --now "pingify-recycle@$n.timer" >/dev/null 2>&1
            rm -f "$UNIT_DIR/pingify-recycle@$n.timer"
            nat_drop "$n" >/dev/null 2>&1 || true
            awg_down "$n" >/dev/null 2>&1 || true
            rm -f "$(cfg_file "$n")" "$STATE_DIR/$n.forwards" "$STATE_DIR/$n.fail"
        done
        systemctl daemon-reload 2>/dev/null
        ok "all tunnels removed"
        pause ;;
    3) full_uninstall ;;
    0 | '') return 0 ;;
    esac
}

# Everything this tool ever wrote, in one pass. The firewall rules matter
# most: a DNAT rule pointing at an address that no longer exists swallows
# every packet for that port silently.
full_uninstall() {
    local n unit rc=0 units=0 keep=yes
    blank
    warn "this removes, on this server:"
    blank
    dim "    every tunnel's service, and their configs in $CFG_DIR if you say so"
    dim "    the systemd units, the watchdog timer and the boot-time firewall units"
    dim "    the forwarding rules (iptables chains PINGIFY_NAT, PINGIFY_SNAT)"
    dim "    the blocking rules (chains PINGIFY_IN, PINGIFY_OUT) and the hosts lines"
    dim "    every AmneziaWG interface it created"
    dim "    the core binary, the state directory and this script"
    blank
    confirm "go ahead?" n || { dim "nothing was removed"; return 2; }
    confirm "delete the configs in $CFG_DIR as well?" n && keep=no
    blank
    for n in $(cfg_list); do
        nat_drop "$n" >/dev/null 2>&1 || true
        awg_down "$n" >/dev/null 2>&1 || true
        svc_do stop "$n"
        svc_do disable "$n"
        systemctl disable --now "pingify-recycle@$n.timer" >/dev/null 2>&1
    done
    systemctl disable --now pingify-health.timer >/dev/null 2>&1
    nat_teardown || rc=1
    remove_blocking || rc=1
    if have iptables; then
        iptables -w 2 -D OUTPUT -j PINGIFY_RAWTCP 2>/dev/null
        iptables -w 2 -F PINGIFY_RAWTCP 2>/dev/null
        iptables -w 2 -X PINGIFY_RAWTCP 2>/dev/null
    fi
    for unit in "$UNIT_DIR"/pingify@.service "$UNIT_DIR"/pingify-*.service "$UNIT_DIR"/pingify-*.timer; do
        [ -e "$unit" ] || continue
        systemctl disable --now "${unit##*/}" >/dev/null 2>&1
        rm -f "$unit"
        [ -e "$unit" ] && { units=1; rc=1; }
    done
    systemctl daemon-reload >/dev/null 2>&1
    [ "$units" = 0 ] && ok "services stopped and removed" || fail "some units are still in $UNIT_DIR"
    if confirm "also revert the sysctl and file-limit tuning?" n; then revert_tuning; fi
    rm -rf "$CORE_DIR" "$STATE_DIR"
    if [ "$keep" = no ]; then rm -rf "$CFG_DIR"; ok "tunnels deleted"; else ok "tunnels left in $CFG_DIR"; fi
    rmdir "$BASE_DIR" 2>/dev/null
    if [ "$(cat /proc/sys/net/ipv4/icmp_echo_ignore_all 2>/dev/null)" = 1 ]; then
        sysctl -qw net.ipv4.icmp_echo_ignore_all=0 >/dev/null 2>&1 && ok "this server answers pings again"
    fi
    blank
    if [ "$rc" = 0 ]; then
        ok "every rule and unit is gone; nothing of Pingify is left running"
        dim "check for yourself:  iptables -t nat -S | grep PINGIFY   (should print nothing)"
    else
        fail "Pingify is off, but the lines above say what is left"
    fi
    blank
    ok "removing the manager itself now"
    rm -f "$PINGIFY_BIN"
    blank
    exit "$rc"
}
uninstall_all() { full_uninstall; }

# ---------------------------------------------------------------------------
# diagnostics
# ---------------------------------------------------------------------------

diag_full() {
    local n any=0 rc=0 one
    banner
    head2 "Full check"
    printf '  %s%s%s\n' "$C_B" "This server" "$C_OFF"
    if [ -x "$CORE_BIN" ]; then
        if core_matches_script; then ok "core $(core_version)"; else warn "core $(core_version), script $PINGIFY_VERSION - update"; fi
    else
        fail "the core is not installed"
    fi
    if have timedatectl && timedatectl show -p NTPSynchronized --value 2>/dev/null | grep -q yes; then
        ok "clock is synchronised"
    else
        warn "clock may be off - see Optimize ${BX_ARR} Sync the clock"
    fi
    if [ "$(watchdog_state)" = on ]; then ok "watchdog is on"; else warn "watchdog is off - a tunnel that goes quiet will not be restarted"; fi
    for n in $(cfg_list); do
        any=1
        health_check "$n" || { one=$?; [ "$one" -gt "$rc" ] && rc=$one; }
    done
    [ "$any" = 1 ] || { blank; warn "no tunnels configured"; }
    pause
    return "$rc"
}

diag_ping() {
    pick_tunnel || return 0
    local host
    host=$(peer_public "$PICKED")
    blank
    [ -n "$host" ] || ask host "address to ping" "" v_host || return 0
    blank
    dim "the raw path to $host, outside the tunnel"
    if have ping; then
        ping -c 5 -W 2 "$host" 2>&1 | sed 's/^/    /'
        dim "an ICMP tunnel on the other server stops it answering pings - the tunnel is fine"
    else
        warn "ping is not installed"
    fi
    pause
}

# show_nat - every rule Pingify has put in the firewall, and nothing else.
show_nat() {
    blank
    if ! have iptables; then
        warn "iptables is not installed on this server"
        dim "a TCP tunnel does not need it; a TUN tunnel's ports could not be forwarded without it"
        return
    fi
    local any=0 out
    out=$(iptables -w 2 -t nat -S PINGIFY_NAT 2>/dev/null | grep -v '^-N ')
    if [ -n "$out" ]; then
        any=1
        head2 "Forwarding"
        dim "sends a port on this server across the private link"
        printf '%s\n' "$out" | sed 's/^/    /' | cut -c "1-$((UI_TERM - 2))"
        iptables -w 2 -t nat -S PINGIFY_SNAT 2>/dev/null | grep -v '^-N ' | sed 's/^/    /'
    fi
    out=$(iptables -w 2 -S PINGIFY_RAWTCP 2>/dev/null | grep -v '^-N ')
    if [ -n "$out" ]; then
        any=1
        head2 "Raw TCP"
        dim "keeps the kernel from answering our own segments with a reset"
        printf '%s\n' "$out" | sed 's/^/    /'
    fi
    out="$(iptables -w 2 -S PINGIFY_IN 2>/dev/null | grep -v '^-N ')$(iptables -w 2 -S PINGIFY_OUT 2>/dev/null | grep -v '^-N ')"
    if [ -n "$out" ]; then
        any=1
        head2 "Blocking"
        dim "the switches under Blocking in the main menu"
        iptables -w 2 -S PINGIFY_IN 2>/dev/null | grep -v '^-N ' | sed 's/^/    /' | cut -c "1-$((UI_TERM - 2))"
        iptables -w 2 -S PINGIFY_OUT 2>/dev/null | grep -v '^-N ' | sed 's/^/    /' | cut -c "1-$((UI_TERM - 2))"
    fi
    if [ "$any" = 0 ]; then
        ok "Pingify has no firewall rules on this server"
        dim "Which is normal. Rules appear when a TUN tunnel forwards ports, when"
        dim "a Raw TCP tunnel runs, or when something under Blocking is on."
    fi
}

diag_system() {
    banner
    head2 "System"
    detect_os
    panel "MACHINE"
    panel_field "OS" "$OS_PRETTY"
    panel_field "Kernel" "$(uname -r)" "Arch" "$ARCH"
    panel_field "CPU" "$(nproc 2>/dev/null || echo ?) cores" "Memory" "$(free -h 2>/dev/null | awk '/^Mem:/{print $3" of "$2}')"
    panel_end
    panel "NETWORK"
    srv_info
    panel_field "Public IP" "$SRV_IP"
    panel_field "Congestion" "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)" "Qdisc" "$(sysctl -n net.core.default_qdisc 2>/dev/null)"
    panel_field "Blocking" "$(block_summary)" "Open files" "$(ulimit -n)"
    panel_end
    panel "PINGIFY"
    panel_field "Script" "$PINGIFY_VERSION" "Core" "$(core_version 2>/dev/null || printf 'none')"
    panel_field "Directory" "$BASE_DIR"
    panel_field "Watchdog" "$(state_badge "$(watchdog_state)")" "Time" "$(date -u '+%Y-%m-%d %H:%M UTC')"
    panel_end
    pause
}

diagnostics_menu() {
    local c
    while :; do
        banner
        head2 "Diagnostics"
        group "Check"
        item 1 "Full check" "this server, then every tunnel"
        item 2 "Live log" "follow a tunnel as it runs"
        group "Measure"
        item 3 "iperf3" "real bandwidth between your two servers"
        item 4 "Find the MTU" "measure the path instead of guessing at it"
        item 5 "Ping the other end" "raw latency, outside the tunnel"
        group "Show"
        item 6 "Firewall rules" "the iptables rules Pingify installed, if any"
        item 7 "System summary"
        blank
        item 0 "Back"
        blank
        menu_key c || return 0
        case $c in
        1) diag_full ;;
        2) pick_tunnel && live_log "$PICKED" ;;
        3) speed_menu ;;
        4) mtu_menu ;;
        5) diag_ping ;;
        6) show_nat; pause ;;
        7) diag_system ;;
        0 | '') return 0 ;;
        esac
    done
}
#!/usr/bin/env bash
#
# Things done to the machine rather than to a tunnel: kernel tuning, and
# blocking. Everything this file changes, it owns outright and can take back.
#
# The kernel settings are one drop-in file, so revert is deleting one file,
# and the file carries its own state in two comment lines. The firewall rules
# are two chains of our own, hooked into INPUT and OUTPUT at position 1 and
# rebuilt from empty on every apply; the state files are the truth.
#
# One sysctl is deliberately absent. net.ipv4.icmp_echo_ignore_all belongs to
# the ICMP carrier: the core sets it while an ICMP tunnel runs, because both
# ends send echo requests and a kernel that answers them doubles every packet
# on the wire, and the manager gives it back when the last one stops.

HOST_SYSCTL=/etc/sysctl.d/99-pingify.conf
HOST_LIMITS=/etc/security/limits.d/99-pingify.conf
SYSCTL_FILE=$HOST_SYSCTL

SPEEDTEST_HOSTS="speedtest.net ooklaserver.net speedtestcustom.com fast.com
nperf.com speedof.me openspeedtest.com speedcheck.org librespeed.org
speedtest.cn"
HOSTS_MARK='# --- pingify speedtest block ---'
HOSTS_END='# --- end pingify ---'

# ---------------------------------------------------------------------------
# host tuning
# ---------------------------------------------------------------------------

host_profile() {
    awk '/^# profile: /{ sub(/^# profile: /, ""); print; exit }' "$HOST_SYSCTL" 2>/dev/null
}
host_tuning_label() {
    local p
    p=$(host_profile)
    printf '%s' "${p:-default}"
}

host_bbr_state() {
    local s
    s=$(awk '/^# bbr: /{ sub(/^# bbr: /, ""); print; exit }' "$HOST_SYSCTL" 2>/dev/null)
    printf '%s' "${s:-off}"
}

host_bbr_available() {
    modprobe tcp_bbr 2>/dev/null || true
    local avail
    avail=$(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null)
    # shellcheck disable=SC2086
    list_has bbr $avail
}

# host_write_sysctl writes the whole drop-in from scratch. The three profiles
# differ in one idea: how much the kernel may hold for a socket, and how long
# it may spend draining the card in one go. The ceiling is not for one stream
# - it is for the sixteen that arrive at once when a household starts using
# the link.
host_write_sysctl() {
    local profile=$1 bbr=$2 sockbuf defbuf udpmin backlog budget budget_us
    case $profile in
    gaming)
        sockbuf=33554432 defbuf=524288 udpmin=131072
        backlog=100000 budget=300 budget_us=2000 ;;
    download | throughput)
        profile=download
        sockbuf=134217728 defbuf=4194304 udpmin=524288
        backlog=300000 budget=1200 budget_us=8000 ;;
    *)
        profile=balanced
        sockbuf=67108864 defbuf=1048576 udpmin=262144
        backlog=200000 budget=600 budget_us=4000 ;;
    esac
    cat >"$HOST_SYSCTL" <<SYSCTL || { fail "could not write $HOST_SYSCTL"; return 1; }
# Written by Pingify $PINGIFY_VERSION. Delete this file, run "sysctl --system",
# and the distribution's own settings are what is left.
# profile: $profile
# bbr: $bbr

# Room in flight. A long path with real loss needs far more than a datacentre
# LAN, which is what the stock numbers are sized for.
net.core.rmem_max = $sockbuf
net.core.wmem_max = $sockbuf
net.core.rmem_default = $defbuf
net.core.wmem_default = $defbuf
net.core.optmem_max = 4194304
net.ipv4.tcp_rmem = 4096 $defbuf $sockbuf
net.ipv4.tcp_wmem = 4096 $defbuf $sockbuf
net.ipv4.udp_rmem_min = $udpmin
net.ipv4.udp_wmem_min = $udpmin

# Behave on a long path.
net.ipv4.tcp_mtu_probing = 1
net.ipv4.tcp_slow_start_after_idle = 0
net.ipv4.tcp_no_metrics_save = 1
net.ipv4.tcp_notsent_lowat = 131072
net.ipv4.tcp_fastopen = 3
net.ipv4.tcp_window_scaling = 1
net.ipv4.tcp_sack = 1

# Drain the card's bursts without starving everything else.
net.core.netdev_max_backlog = $backlog
net.core.netdev_budget = $budget
net.core.netdev_budget_usecs = $budget_us

# Connection churn, and the descriptors it needs.
net.core.somaxconn = 65535
net.ipv4.tcp_max_syn_backlog = 32768
net.ipv4.tcp_syncookies = 1
net.ipv4.tcp_fin_timeout = 15
net.ipv4.tcp_tw_reuse = 1
net.ipv4.tcp_keepalive_time = 300
net.ipv4.tcp_keepalive_intvl = 30
net.ipv4.tcp_keepalive_probes = 5
net.ipv4.ip_local_port_range = 10240 65535
fs.file-max = 2097152
fs.nr_open = 2097152
vm.swappiness = 10
SYSCTL
    if [ "$bbr" = on ]; then
        cat >>"$HOST_SYSCTL" <<'SYSCTL' || { fail "could not add the BBR lines"; return 1; }

# fq is the queue discipline BBR is designed against.
net.core.default_qdisc = fq
net.ipv4.tcp_congestion_control = bbr
SYSCTL
    fi
    if ! sysctl --system >/dev/null 2>&1; then
        warn "the kernel would not take some of those settings"
        fix "sysctl --system   prints the line it refused"
        return 1
    fi
    return 0
}

apply_tuning() {
    local profile=${1:-balanced}
    host_write_sysctl "$profile" "$(host_bbr_state)" || return 1
    ok "$(host_profile) host tuning applied"
    dim "congestion control is a separate switch - see Enable BBR"
    host_limits quiet
}

choose_tuning_profile() {
    blank
    head2 "Host tuning profile"
    CHOICE_DEF=1
    choice 1 "Balanced" "recommended - video, browsing and games together"
    choice 2 "Gaming" "smaller queues and shorter NIC work cycles"
    choice 3 "Download" "large packet batches and a 128 MB socket ceiling"
    CHOICE_DEF=
    blank
    dim "This sets the kernel's socket buffer sizes and backlog, for everything"
    dim "this server does. A tunnel's own profile is a different thing with the"
    dim "same three names; it lives on that tunnel's Tuning screen."
    blank
    local c
    pick c "select" 1 3 || return 1
    case $c in
    2) apply_tuning gaming ;;
    3) apply_tuning download ;;
    *) apply_tuning balanced ;;
    esac
}

# host_limits raises the descriptor ceiling for logins. systemd units get
# theirs from the unit; this is for the shell you ssh in with.
host_limits() {
    cat >"$HOST_LIMITS" <<'LIMITS' || { fail "could not write $HOST_LIMITS"; return 1; }
# Written by Pingify. Delete this file to undo it.
*    soft  nofile  1048576
*    hard  nofile  1048576
root soft  nofile  1048576
root hard  nofile  1048576
LIMITS
    [ "${1:-}" = quiet ] && return 0
    ok "descriptor limit raised to 1048576"
    dim "PAM reads this at login, so this shell keeps the $(ulimit -n) it started with"
}

enable_bbr() {
    blank
    if ! host_bbr_available; then
        fail "this kernel does not offer BBR"
        dim "kernel $(uname -r); a 4.9 or newer kernel with tcp_bbr is needed"
        return 1
    fi
    host_write_sysctl "$(host_profile)" on || return 1
    ok "BBR enabled with the fq queue discipline"
    dim "now: $(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null) / $(sysctl -n net.core.default_qdisc 2>/dev/null)"
}

disable_bbr() {
    blank
    host_write_sysctl "$(host_profile)" off || return 1
    sysctl -qw net.ipv4.tcp_congestion_control=cubic net.core.default_qdisc=fq_codel >/dev/null 2>&1
    ok "back to $(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)"
}

enable_forwarding() {
    nat_ip_forward && ok "IPv4 forwarding is on, and stays on after a reboot"
}

revert_tuning() {
    rm -f "$HOST_SYSCTL" "$HOST_LIMITS" "$NAT_SYSCTL" /etc/sysctl.d/98-pingify-bbr.conf \
        /etc/modules-load.d/pingify.conf /etc/sysctl.d/97-pingify-forward.conf
    sysctl --system >/dev/null 2>&1 || true
    ok "Pingify's tuning and limits files are gone; the distribution defaults are back"
    dim "a value we raised stays raised until this machine reboots, because nothing"
    dim "recorded what the kernel held before; a reboot makes absolutely sure"
}

show_net_settings() {
    blank
    printf '  %-34s %s\n' "Pingify profile" "$(host_tuning_label)"
    printf '  %-34s %s\n' "congestion control" "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)"
    printf '  %-34s %s\n' "available" "$(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null)"
    printf '  %-34s %s\n' "default qdisc" "$(sysctl -n net.core.default_qdisc 2>/dev/null)"
    printf '  %-34s %s\n' "rmem_max" "$(sysctl -n net.core.rmem_max 2>/dev/null)"
    printf '  %-34s %s\n' "wmem_max" "$(sysctl -n net.core.wmem_max 2>/dev/null)"
    printf '  %-34s %s\n' "tcp_rmem" "$(sysctl -n net.ipv4.tcp_rmem 2>/dev/null)"
    printf '  %-34s %s\n' "tcp_wmem" "$(sysctl -n net.ipv4.tcp_wmem 2>/dev/null)"
    printf '  %-34s %s\n' "mtu probing" "$(sysctl -n net.ipv4.tcp_mtu_probing 2>/dev/null)"
    printf '  %-34s %s\n' "packet backlog" "$(sysctl -n net.core.netdev_max_backlog 2>/dev/null)"
    printf '  %-34s %s / %s us\n' "packet budget" "$(sysctl -n net.core.netdev_budget 2>/dev/null)" "$(sysctl -n net.core.netdev_budget_usecs 2>/dev/null)"
    printf '  %-34s %s\n' "ip_forward" "$(sysctl -n net.ipv4.ip_forward 2>/dev/null)"
    printf '  %-34s %s\n' "icmp_echo_ignore_all" "$(sysctl -n net.ipv4.icmp_echo_ignore_all 2>/dev/null)"
    printf '  %-34s %s\n' "open file limit" "$(ulimit -n)"
    printf '  %-34s %s\n' "Pingify tuning file" "$([ -f "$HOST_SYSCTL" ] && echo present || echo absent)"
    blank
}

manage_swap() {
    blank
    local cur mb
    cur=$(free -m 2>/dev/null | awk '/^Swap:/{print $2}')
    dim "current swap: ${cur:-0} MB"
    if [ "${cur:-0}" -gt 0 ] 2>/dev/null && [ -f /swapfile ]; then
        if confirm "remove the existing Pingify swap file?"; then
            swapoff /swapfile 2>/dev/null || true
            sed_i '\#^/swapfile #d' /etc/fstab
            rm -f /swapfile
            ok "swap file removed"
            pause; return
        fi
    fi
    ask mb "swap size in MB (0 to cancel)" "1024" v_number || return
    [ "$mb" = 0 ] && return
    swapoff /swapfile 2>/dev/null || true
    rm -f /swapfile
    info "creating a ${mb}MB swap file"
    if ! fallocate -l "${mb}M" /swapfile 2>/dev/null; then
        dd if=/dev/zero of=/swapfile bs=1M count="$mb" status=none 2>/dev/null || { fail "could not create it"; pause; return; }
    fi
    chmod 600 /swapfile
    mkswap /swapfile >/dev/null 2>&1
    swapon /swapfile || { fail "swapon failed"; pause; return; }
    grep -q '^/swapfile ' /etc/fstab 2>/dev/null || echo '/swapfile none swap sw 0 0' >>/etc/fstab
    sysctl -qw vm.swappiness=10 >/dev/null 2>&1
    ok "swap ready"
    pause
}

sync_clock() {
    blank
    info "current time: $(date -u '+%Y-%m-%d %H:%M:%S UTC')"
    if have timedatectl; then
        timedatectl set-ntp true 2>/dev/null && ok "NTP synchronisation enabled"
        timedatectl status 2>/dev/null | sed 's/^/  /'
    else
        warn "timedatectl is missing; install systemd-timesyncd or chrony"
    fi
}

optimize_menu() {
    local c
    while :; do
        banner
        head2 "Optimize"
        panel "CURRENT"
        panel_field "Congestion" "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)" \
            "Qdisc" "$(sysctl -n net.core.default_qdisc 2>/dev/null)"
        panel_field "Tuning" "$(host_tuning_label)" "Open files" "$(ulimit -n)"
        panel_field "BBR" "$(state_badge "$(host_bbr_state)")" "Forwarding" "$(sysctl -n net.ipv4.ip_forward 2>/dev/null | sed 's/^1$/on/; s/^0$/off/')"
        panel_end
        blank
        item 1 "Apply host tuning" "Balanced, Gaming or Download"
        item 2 "Enable BBR" "congestion control and fq - measured: 348 Mbit/s where cubic carried 31"
        item 3 "Disable BBR" "back to the kernel default"
        blank
        item 4 "Enable IP forwarding" "a TUN tunnel's ports need it; the manager turns it on itself"
        item 5 "Swap file"
        item 6 "Sync the clock"
        blank
        item 7 "Show all settings"
        item 8 "Revert everything Pingify changed"
        item 0 "Back"
        blank
        menu_key c || return 0
        case $c in
        1) choose_tuning_profile; pause ;;
        2) enable_bbr; pause ;;
        3) disable_bbr; pause ;;
        4) blank; enable_forwarding; pause ;;
        5) manage_swap ;;
        6) sync_clock; pause ;;
        7) show_net_settings; pause ;;
        8) blank; confirm "revert the sysctl and limits changes?" && revert_tuning; pause ;;
        0 | '') return 0 ;;
        esac
    done
}
screen_host() { optimize_menu; }

# ---------------------------------------------------------------------------
# blocking
#
# Three switches people running a tunnel keep reaching for: stop the server
# answering pings, keep clients off benchmark sites, and reject QUIC so
# browsers fall back to TCP. Everything goes in Pingify's own chains, so
# nothing here touches rules you or your panel put in place, and a boot unit
# re-applies the state files, because iptables rules do not survive a reboot.
# ---------------------------------------------------------------------------

block_ipt() { iptables -w 2 "$@" 2>/dev/null; }
block_state() { [ -f "$STATE_DIR/block-$1" ] && printf 'on' || printf 'off'; }

block_summary() {
    local out=
    [ "$(block_state icmp)" = on ] && out="${out}icmp "
    [ "$(block_state speedtest)" = on ] && out="${out}speedtest "
    [ "$(block_state quic)" = on ] && out="${out}quic "
    [ -n "$out" ] && printf '%s' "${out% }" || printf 'none'
}

block_toggle() {
    local what=$1
    ensure_dirs
    if [ -f "$STATE_DIR/block-$what" ]; then rm -f "$STATE_DIR/block-$what"
    else : >"$STATE_DIR/block-$what"; fi
}

# block_tun_ifaces is every private-link device this server has or will have.
block_tun_ifaces() {
    local n d out= p
    for n in $(cfg_list); do
        d=$(toml_get "$(cfg_file "$n")" tun name)
        [ -n "$d" ] || continue
        # shellcheck disable=SC2086
        list_has "$d" $out || out="$out $d"
    done
    for p in /sys/class/net/pfy*; do
        [ -e "$p" ] || continue
        d=${p##*/}
        # shellcheck disable=SC2086
        list_has "$d" $out || out="$out $d"
    done
    printf '%s' "${out# }"
}

block_icmp_tunnel() {
    local n
    for n in $(cfg_list); do
        [ "$(toml_get "$(cfg_file "$n")" transport type)" = icmp ] && return 0
    done
    return 1
}

block_carrier_443() {
    local n f
    while IFS= read -r n; do
        f=$(cfg_file "$n")
        [ "$(toml_get "$f" transport type)" = udp ] || continue
        [ "$(toml_get "$f" transport port)" = 443 ] || continue
        printf '%s' "$n"
        return 0
    done < <(cfg_list)
    return 1
}

# block_carrier_accept puts this server's own carrier out of reach of the
# string match, which would otherwise reject the packet carrying a customer's
# request for speedtest.net through the tunnel.
block_carrier_accept() {
    local n f t p rc=0 icmp_done=0
    while IFS= read -r n; do
        f=$(cfg_file "$n")
        t=$(toml_get "$f" transport type)
        if [ "$t" = icmp ]; then
            [ "$icmp_done" = 1 ] && continue
            icmp_done=1
            block_ipt -A PINGIFY_OUT -p icmp -j ACCEPT || rc=1
            continue
        fi
        [ "$t" = gre ] && { block_ipt -A PINGIFY_OUT -p gre -j ACCEPT || rc=1; continue; }
        p=$(toml_get "$f" transport port)
        [ "$t" = awg ] && p=$(toml_get "$f" awg port)
        case $p in '' | *[!0-9]*) continue ;; esac
        case $(port_family "$t") in
        udp) block_ipt -A PINGIFY_OUT -p udp --dport "$p" -j ACCEPT || rc=1
             block_ipt -A PINGIFY_OUT -p udp --sport "$p" -j ACCEPT || rc=1 ;;
        tcp) block_ipt -A PINGIFY_OUT -p tcp --dport "$p" -j ACCEPT || rc=1
             block_ipt -A PINGIFY_OUT -p tcp --sport "$p" -j ACCEPT || rc=1 ;;
        esac
    done < <(cfg_list)
    return "$rc"
}

block_reset_chains() {
    local c
    for c in PINGIFY_IN PINGIFY_OUT; do
        block_ipt -N "$c" || block_ipt -F "$c" || return 1
    done
    block_ipt -C INPUT -j PINGIFY_IN || block_ipt -I INPUT 1 -j PINGIFY_IN
    block_ipt -C OUTPUT -j PINGIFY_OUT || block_ipt -I OUTPUT 1 -j PINGIFY_OUT
    return 0
}

block_drop_chains() {
    local c i rc=0
    for i in 1 2 3 4 5; do block_ipt -D INPUT -j PINGIFY_IN || break; done
    for i in 1 2 3 4 5; do block_ipt -D OUTPUT -j PINGIFY_OUT || break; done
    for i in 1 2 3; do block_ipt -D FORWARD -j PINGIFY_FWD || break; done
    for c in PINGIFY_IN PINGIFY_OUT PINGIFY_FWD; do
        block_ipt -F "$c"
        block_ipt -X "$c"
    done
    for c in PINGIFY_IN PINGIFY_OUT; do
        block_ipt -S "$c" >/dev/null 2>&1 && rc=1
    done
    return "$rc"
}

hosts_block_off() {
    grep -qF "$HOSTS_MARK" /etc/hosts 2>/dev/null || return 0
    local tmp
    tmp=$(mktemp)
    awk -v a="$HOSTS_MARK" -v b="$HOSTS_END" '
        $0 == a { skip = 1; next }
        $0 == b { skip = 0; next }
        !skip
    ' /etc/hosts >"$tmp" && cat "$tmp" >/etc/hosts
    rm -f "$tmp"
}

hosts_block_on() {
    hosts_block_off
    {
        printf '%s\n' "$HOSTS_MARK"
        local h
        for h in $SPEEDTEST_HOSTS; do
            case $h in *[!a-zA-Z0-9.-]*) continue ;; esac
            printf '127.0.0.1 %s\n127.0.0.1 www.%s\n' "$h" "$h"
        done
        printf '%s\n' "$HOSTS_END"
    } >>/etc/hosts
}

# apply_blocking is the only thing that writes rules, and it writes all of
# them every time from the state files.
apply_blocking() {
    local quiet=${1:-} ifc h any rc=0 carrier
    have iptables || {
        [ "$quiet" = quiet ] || warn "iptables is not installed, so nothing was applied"
        return 1
    }
    ensure_dirs
    block_reset_chains || {
        [ "$quiet" = quiet ] || fail "iptables would not give us our chains"
        return 1
    }

    if [ "$(block_state icmp)" = on ]; then
        # The private link first: a ping across it is the one test the
        # operator has, and it is the far end's INPUT chain that answers it.
        for ifc in $(block_tun_ifaces); do
            block_ipt -A PINGIFY_IN -i "$ifc" -p icmp --icmp-type echo-request -j ACCEPT || rc=1
        done
        # Where a tunnel on this host uses the icmp transport, the blanket
        # drop is left out: the carrier's own echo requests arrive on the
        # public interface, INPUT is traversed before a raw socket is fed,
        # and the core has already stopped the kernel answering pings anyway.
        if block_icmp_tunnel; then
            [ "$quiet" = quiet ] || dim "an ICMP tunnel is configured, so the blanket drop is left out - the core has already stopped this host answering pings"
        else
            block_ipt -A PINGIFY_IN -p icmp --icmp-type echo-request -j DROP || rc=1
        fi
    fi

    if [ "$(block_state quic)" = on ]; then
        if carrier=$(block_carrier_443); then
            [ "$quiet" = quiet ] || dim "$carrier carries on udp 443, so the QUIC rules are left out"
        else
            block_ipt -A PINGIFY_OUT -p udp --dport 443 -j REJECT --reject-with icmp-port-unreachable || rc=1
            block_ipt -A PINGIFY_IN -p udp --dport 443 -j DROP || rc=1
        fi
    fi

    if [ "$(block_state speedtest)" = on ]; then
        hosts_block_on
        block_carrier_accept || rc=1
        any=0
        for h in $SPEEDTEST_HOSTS; do
            case $h in *[!a-zA-Z0-9.-]*) continue ;; esac
            block_ipt -A PINGIFY_OUT -m string --string "$h" --algo bm -j REJECT && any=1
        done
        if [ "$any" = 0 ] && [ "$quiet" != quiet ]; then
            warn "this kernel has no string match, so only the hosts file is blocking"
        fi
    else
        hosts_block_off
    fi

    firewall_unit_write || rc=1
    if [ "$rc" != 0 ]; then
        [ "$quiet" = quiet ] || { fail "some of those rules would not go in"; fix "iptables -S PINGIFY_OUT   shows what did"; }
        return 1
    fi
    [ "$quiet" = quiet ] || ok "blocking rules applied"
    return 0
}

# iptables forgets everything at reboot, so one oneshot unit replays the
# state files by calling back into this same script.
firewall_unit_write() {
    local unit=$UNIT_DIR/pingify-firewall.service
    cat >"$unit" <<UNIT || { fail "could not write the boot unit $unit"; return 1; }
[Unit]
Description=Pingify blocking rules
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=$PINGIFY_BIN --apply-firewall

[Install]
WantedBy=multi-user.target
UNIT
    systemctl daemon-reload >/dev/null 2>&1 || true
    systemctl enable pingify-firewall.service >/dev/null 2>&1 || true
}
write_firewall_unit() { firewall_unit_write; }

remove_blocking() {
    local rc=0
    rm -f "$STATE_DIR"/block-icmp "$STATE_DIR"/block-quic "$STATE_DIR"/block-speedtest
    hosts_block_off
    have iptables && { block_drop_chains || rc=1; }
    systemctl disable --now pingify-firewall.service >/dev/null 2>&1 || true
    rm -f "$UNIT_DIR/pingify-firewall.service"
    systemctl daemon-reload >/dev/null 2>&1 || true
    if [ "$rc" != 0 ]; then
        fail "the PINGIFY chains are still in the kernel"
        fix "iptables -S PINGIFY_IN   shows what points at it"
        return 1
    fi
    return 0
}

blocking_menu() {
    local c
    while :; do
        banner
        head2 "Blocking"
        panel "RULES"
        panel_row "$(pad_to "${C_DIM}Ping / ICMP${C_OFF}" 22)$(state_badge "$(block_state icmp)")"
        panel_row "$(pad_to "${C_DIM}Speedtest sites${C_OFF}" 22)$(state_badge "$(block_state speedtest)")"
        panel_row "$(pad_to "${C_DIM}UDP 443${C_OFF}" 22)$(state_badge "$(block_state quic)")"
        panel_end
        blank
        item 1 "Ping / ICMP" "stop this server answering pings from the internet"
        item 2 "Speedtest sites" "block benchmark sites - on the KHAREJ server, where the proxy talks to them"
        item 3 "Block UDP 443" "rejects QUIC, so browsers fall back to TCP through the tunnel"
        blank
        item 4 "Show the live rules"
        item 5 "Clear everything"
        item 0 "Back"
        blank
        menu_key c || return 0
        case $c in
        1) blank
            if [ "$(block_state icmp)" != on ]; then
                dim "Safe with an ICMP tunnel running: the core has already stopped the"
                dim "kernel answering echoes, and pings inside the private link are"
                dim "accepted first. This only stops other people's pings."
                blank
            fi
            block_toggle icmp
            apply_blocking
            if [ "$(block_state icmp)" = on ]; then ok "this server no longer answers pings"
            else ok "this server answers pings again, unless an ICMP tunnel is running"; fi
            pause ;;
        2) blank
            dim "This works on traffic leaving in the clear, so it belongs on the"
            dim "KHAREJ server - that is where the proxy talks to the site."
            blank
            block_toggle speedtest; apply_blocking; pause ;;
        3) blank; block_toggle quic; apply_blocking; pause ;;
        4) show_nat; pause ;;
        5) blank
            confirm "remove every blocking rule?" && { remove_blocking && ok "cleared"; }
            pause ;;
        0 | '') return 0 ;;
        esac
    done
}
screen_firewall() { blocking_menu; }
#!/usr/bin/env bash
#
# The front door: getting the manager onto the machine, working out what the
# command line asked for, and the one screen everything else hangs off. It
# is last so that everything it dispatches to is already defined when the
# guard at the bottom calls main.

# ---------------------------------------------------------------------------
# installation of the manager itself
# ---------------------------------------------------------------------------

# install_self copies this script over /usr/local/bin/pingify when the copy
# sitting there is not this one. The new copy is renamed into place rather
# than written over the destination: bash reads a script as it runs, so
# truncating the file it is still reading turns the rest of the run into
# whatever lands at that offset.
install_self() {
    local src=${BASH_SOURCE[0]} dir tmp stamp
    if [ ! -f "$src" ]; then
        warn "the pingify command was not installed - this script has no file on disk"
        fix "save it first:  curl -fsSLo Pingify.sh <url> && bash Pingify.sh"
        return 1
    fi
    if ! cmp -s "$src" "$PINGIFY_BIN"; then
        dir=${PINGIFY_BIN%/*}
        tmp=$(mktemp "$dir/.pingify.XXXXXX") || return 1
        if ! { cat "$src" >"$tmp" && chmod 0755 "$tmp" && mv -f "$tmp" "$PINGIFY_BIN"; }; then
            rm -f "$tmp"
            warn "could not write $PINGIFY_BIN"
            return 1
        fi
    fi
    # The units change with the script and never with a tunnel, so they are
    # written on a version change and not on every tunnel creation.
    stamp=$STATE_DIR/script.version
    if [ "$(cat "$stamp" 2>/dev/null)" != "$PINGIFY_VERSION" ]; then
        if unit_write && [ -s "$UNIT_DIR/pingify@.service" ]; then
            printf '%s\n' "$PINGIFY_VERSION" >"$stamp"
        else
            warn "could not write $UNIT_DIR/pingify@.service"
            return 1
        fi
    fi
    return 0
}

usage() {
    cat <<USAGE
Pingify $PINGIFY_VERSION - tunnel manager for Iran <-> Kharej server pairs

  pingify                    open the menu
  pingify --new              straight to building a tunnel
  pingify --status [name]    print tunnel status and exit
  pingify --check name       health check; exits 0 clean, 1 warnings, 2 problems
  pingify --json             with --status or --check, machine readable
  pingify --health-check     run the watchdog pass once (used by the timer)
  pingify --apply-firewall   re-apply the forwarding and blocking rules (used at boot)
  pingify --update           fetch a newer script and core
  pingify --uninstall        take Pingify off this server
  pingify --install          install the command and the systemd units
  pingify --version          print the version
  pingify --help             this text

Files: $BASE_DIR
USAGE
}

# ---------------------------------------------------------------------------
# front page
# ---------------------------------------------------------------------------

info_panel() {
    local name up=0 total=0 core_txt tun_txt side=
    for name in $(cfg_list); do
        total=$((total + 1))
        tunnel_is_up "$name" && up=$((up + 1))
        [ -n "$side" ] || side=$(toml_get "$(cfg_file "$name")" tunnel side)
    done
    srv_info
    panel "SERVER"
    panel_field "IP" "$(addr_tint "$SRV_IP")"
    panel_field "Location" "$SRV_LOC"
    panel_field "Datacenter" "$(printf '%.44s' "$SRV_ORG")"
    case $side in
    iran) panel_field "Side" "IRAN - users connect here" ;;
    kharej) panel_field "Side" "KHAREJ - your panel is here" ;;
    esac
    panel_end
    if [ ! -x "$CORE_BIN" ]; then
        core_txt="${C_RED}not installed${C_OFF}"
    elif core_matches_script; then
        core_txt=$(core_version)
    else
        core_txt="${C_RED}$(core_version) - does not match the script${C_OFF}"
    fi
    if [ "$total" = 0 ]; then
        tun_txt="${C_GRY}${BX_OFF}${C_OFF} none configured"
    elif [ "$up" = "$total" ]; then
        tun_txt="${C_GRN}${BX_ON}${C_OFF} $up of $total up"
    elif [ "$up" = 0 ]; then
        tun_txt="${C_RED}${BX_ON}${C_OFF} $up of $total up"
    else
        tun_txt="${C_YEL}${BX_ON}${C_OFF} $up of $total up"
    fi
    panel "STATUS"
    panel_field "Core ver" "$core_txt"
    panel_field "Script ver" "$PINGIFY_VERSION"
    panel_field "Tunnels" "$tun_txt"
    panel_field "Watchdog" "$(state_badge "$(watchdog_state)")"
    panel_end
}

first_run() {
    [ -x "$CORE_BIN" ] && return 0
    banner
    head2 "First-time setup"
    panel "INSTALL"
    panel_field "1  Manager" "installed at $PINGIFY_BIN"
    panel_field "2  Core" "compiled here from the source inside this script"
    panel_field "3  Services" "systemd units and the health watchdog"
    panel_end
    blank
    if build_core; then
        unit_write
        ok "Pingify is ready - choose New tunnel from the next screen"
        sleep 1
        return 0
    fi
    blank
    fail "the core could not be built"
    dim "it needs a Go toolchain, which this script offers to fetch when it is missing"
    pause
    return 1
}

# ensure_core_current rebuilds a core that does not match the script: they
# read the same config file, so a mismatch rejects tunnels.
ensure_core_current() {
    [ -x "$CORE_BIN" ] || return 0
    core_matches_script && return 0
    banner
    head2 "Core update"
    warn "the core is $(core_version), this script is $PINGIFY_VERSION"
    dim "they have to match - the config format is shared between them"
    blank
    if build_core; then
        restart_all "the core was updated"
    else
        blank
        fail "the core could not be updated"
        dim "until it matches, new tunnels will be rejected"
    fi
    pause
}

screen_home() {
    banner
    info_panel
    group "TUNNELS"
    item 1 "New tunnel" "set this server up, or finish the pair"
    item 2 "Manage tunnels" "status, ports, tuning, logs, remove"
    item 3 "Health" "live status, watchdog, health log"
    group "NETWORK"
    item 4 "Optimize" "host profiles, BBR, forwarding, swap"
    item 5 "Blocking" "ICMP, speedtest, UDP 443"
    item 6 "Diagnostics" "connectivity, iperf3, MTU, rules"
    group "MAINTENANCE"
    item 7 "Update Pingify" "script and core together, to the same version"
    item 8 "Remove" "uninstall part of it, or all of it"
    blank
    item 0 "Exit"
    blank
}

main_menu() {
    local c
    while :; do
        screen_home
        menu_key c || return 0
        case $c in
        1) new_tunnel; wiz_end ;;
        2) manage_tunnels ;;
        3) health_menu ;;
        4) optimize_menu ;;
        5) blocking_menu ;;
        6) diagnostics_menu ;;
        7) update_pingify ;;
        8) remove_menu ;;
        0 | q | Q) blank; return 0 ;;
        '') ;;
        *) blank; warn "there is nothing on $c"; sleep 1 ;;
        esac
    done
}

# ---------------------------------------------------------------------------
# what the command line asked for
# ---------------------------------------------------------------------------

# --status is what a monitoring script calls. It exits non-zero if any tunnel
# it was asked about is not running.
cmd_status() {
    local n names=() rc=0
    if [ -n "$ARG_NAME" ]; then
        [ -f "$(cfg_file "$ARG_NAME")" ] || die "there is no tunnel called $ARG_NAME"
        names=("$ARG_NAME")
    else
        while IFS= read -r n; do names+=("$n"); done < <(cfg_list)
    fi
    [ "${#names[@]}" -gt 0 ] || { warn "no tunnels are configured" >&2; return 1; }
    if [ -n "$ARG_JSON" ]; then
        for n in "${names[@]}"; do
            status_json "$n"
            [ "$(svc_state "$n")" = active ] || rc=1
        done
        return "$rc"
    fi
    if [ -n "$ARG_NAME" ]; then
        tunnel_status_block "$ARG_NAME"
    else
        list_tunnels
    fi
    for n in "${names[@]}"; do [ "$(svc_state "$n")" = active ] || rc=1; done
    return "$rc"
}

status_json() {
    local n=$1 st
    st=$(svc_state "$n")
    tun_stats "$n" || ST_UP=false
    printf '{"name":"%s","service":"%s","up":%s,"transport":"%s","profile":"%s"' \
        "$n" "$st" "${ST_UP:-false}" "$ST_TRANSPORT" "$ST_PROFILE"
    printf ',"side":"%s","in_mbit":%s,"out_mbit":%s,"lost":%s,"reordered":%s,"uptime_sec":%s}\n' \
        "$ST_SIDE" "${ST_IN:-0}" "${ST_OUT:-0}" "${ST_LOST:-0}" "${ST_LATE:-0}" "${ST_UPTIME:-0}"
}

argv() {
    ARG_MODE=menu ARG_NAME= ARG_JSON=
    while [ "$#" -gt 0 ]; do
        case $1 in
        --status)
            ARG_MODE=status
            case ${2:-} in '' | -*) ;; *) ARG_NAME=$2; shift ;; esac
            ;;
        --check)
            ARG_MODE=check
            case ${2:-} in '' | -*) die "--check needs the name of a tunnel" ;; esac
            ARG_NAME=$2
            shift
            ;;
        --json) ARG_JSON=1 ;;
        --new) ARG_MODE=new ;;
        --update) ARG_MODE=update ;;
        --rebuild-core) ARG_MODE=rebuild ;;
        --uninstall) ARG_MODE=uninstall ;;
        --install) ARG_MODE=install ;;
        --health-check) ARG_MODE=health ;;
        --apply-firewall) ARG_MODE=firewall ;;
        --version | -v) ARG_MODE=version ;;
        --help | -h) ARG_MODE=help ;;
        *)
            usage >&2
            die "$1 is not an option this script has"
            ;;
        esac
        shift
    done
}

main() {
    local rc
    argv "$@"
    case $ARG_MODE in
    help) usage; exit 0 ;;
    version)
        say "Pingify $PINGIFY_VERSION"
        [ -x "$CORE_BIN" ] && say "core $(core_version)"
        exit 0
        ;;
    esac

    require_root
    detect_os
    ensure_dirs

    case $ARG_MODE in
    status) cmd_status; exit $? ;;
    check) health_check "$ARG_NAME" "${ARG_JSON:+--json}"; exit $? ;;
    health) run_health_check; exit 0 ;;
    firewall) apply_blocking quiet; nat_apply_all; exit 0 ;;
    uninstall)
        full_uninstall
        rc=$?
        [ "$rc" = 2 ] && rc=0
        exit "$rc"
        ;;
    update) update_pingify; exit $? ;;
    install) ensure_deps; install_self && ok "installed"; exit $? ;;
    rebuild) rebuild_core; exit $? ;;
    esac

    ensure_deps
    migrate_layout
    install_self
    srv_info
    first_run || exit 1
    ensure_core_current

    case $ARG_MODE in
    new) new_tunnel; wiz_end ;;
    *) main_menu ;;
    esac
}

# build.sh and the tests source this file to get at its functions; that must
# not launch the menu.
[ -n "${PINGIFY_NO_MAIN:-}" ] || main "$@"
